def make_fonts(root):
    families = {f.lower(): f for f in tkfont.families(root)}
    default = tkfont.nametofont("TkDefaultFont").actual("family")

    def pick(*names):
        for n in names:
            if n.lower() in families:
                return families[n.lower()]
        return default

    sans = pick("Segoe UI", "SF Pro Text", "Helvetica Neue", "Inter", "Ubuntu",
                "Cantarell", "Noto Sans", "DejaVu Sans", "Arial")
    mono = pick("JetBrains Mono", "SF Mono", "Menlo", "Cascadia Mono", "Consolas",
                "Ubuntu Mono", "DejaVu Sans Mono", "Courier New")
    base = 13 if IS_MAC else 10
    return {
        "ui": (sans, base),
        "ui_bold": (sans, base, "bold"),
        "small": (sans, base - 1),
        "small_bold": (sans, base - 1, "bold"),
        "tiny": (sans, max(base - 2, 7)),
        "h1": (sans, base + 9, "bold"),
        "h2": (sans, base + 2, "bold"),
        "brand": (sans, base + 5, "bold"),
        "stat": (sans, base + 7, "bold"),
        "mono": (mono, base),
        "timer": (mono, int(base * 4.2)),
        "timer_mid": (mono, int(base * 3.0)),
        "mini": (mono, int(base * 2.3)),
    }


