# ───────────────────────── форматирование ─────────────────────────

def plural(n, forms):
    n = abs(int(n)) % 100
    if 10 < n < 20:
        return forms[2]
    n1 = n % 10
    if n1 == 1:
        return forms[0]
    if 2 <= n1 <= 4:
        return forms[1]
    return forms[2]


def fmt_clock(seconds, up=False):
    s = max(0, int(seconds) if up else math.ceil(seconds - 1e-6))
    h, rem = divmod(s, 3600)
    m, s = divmod(rem, 60)
    return f"{h}:{m:02d}:{s:02d}" if h else f"{m:02d}:{s:02d}"


def fmt_stopwatch(seconds):
    t = int(seconds * 10)
    h, rem = divmod(t, 36000)
    m, rem = divmod(rem, 600)
    s, d = divmod(rem, 10)
    return f"{h}:{m:02d}:{s:02d}.{d}" if h else f"{m:02d}:{s:02d}.{d}"


def fmt_minutes(minutes):
    minutes = int(round(minutes))
    h, m = divmod(minutes, 60)
    if h and m:
        return f"{h} ч {m} мин"
    if h:
        return f"{h} ч"
    return f"{m} мин"


def fmt_hm(minutes):
    minutes = int(round(minutes))
    return f"{minutes // 60}:{minutes % 60:02d}"


def fmt_day(d):
    return f"{WD_SHORT[d.weekday()]}, {d:%d.%m}"


def fmt_range(a, b):
    if a.month == b.month:
        return f"{a.day}–{b.day} {MONTHS_GEN[b.month - 1]}"
    return f"{a.day} {MONTHS_GEN[a.month - 1]} – {b.day} {MONTHS_GEN[b.month - 1]}"


def fmt_due(due_iso, today):
    if not due_iso:
        return ""
    d = date.fromisoformat(due_iso)
    delta = (d - today).days
    if delta == 0:
        return "сегодня"
    if delta == 1:
        return "завтра"
    if delta < 0:
        return f"просрочено на {-delta} {plural(-delta, DAY_FORMS)}"
    if delta < 7:
        return fmt_day(d)
    return f"{d:%d.%m}" if d.year == today.year else f"{d:%d.%m.%Y}"


def fmt_plan(plan_iso, today):
    if not plan_iso:
        return ""
    d = date.fromisoformat(plan_iso)
    if d <= today:
        return "сегодня"
    if d == today + timedelta(days=1):
        return "завтра"
    return fmt_day(d)


def blend(c1, c2, t):
    t = max(0.0, min(1.0, t))
    a = [int(c1[i:i + 2], 16) for i in (1, 3, 5)]
    b = [int(c2[i:i + 2], 16) for i in (1, 3, 5)]
    return "#%02x%02x%02x" % tuple(round(x + (y - x) * t) for x, y in zip(a, b))


def fit_text(font, text, width):
    if font.measure(text) <= width:
        return text
    while text and font.measure(text + "…") > width:
        text = text[:-1]
    return text + "…"


def day_of(dt, start_hour):
    """Логический день: работа в 2 ночи при старте дня в 4:00 идёт в предыдущий день."""
    return (dt - timedelta(hours=int(start_hour))).date()


# ───────────────────────── разбор ввода ─────────────────────────

WEEKDAYS = {"пн": 0, "пон": 0, "вт": 1, "ср": 2, "чт": 3, "пт": 4, "сб": 5, "вс": 6,
            "mon": 0, "tue": 1, "wed": 2, "thu": 3, "fri": 4, "sat": 5, "sun": 6}


def parse_date(text, today):
    s = text.strip().lower().rstrip(".")
    if not s:
        return None
    if s in ("сегодня", "сег", "today"):
        return today
    if s in ("вчера", "yesterday"):
        return today - timedelta(days=1)
    if s in ("завтра", "зав", "tomorrow"):
        return today + timedelta(days=1)
    if s == "послезавтра":
        return today + timedelta(days=2)
    if s in WEEKDAYS:
        ahead = (WEEKDAYS[s] - today.weekday()) % 7 or 7
        return today + timedelta(days=ahead)
    m = re.fullmatch(r"\+(\d{1,3})\s*(д|d|нед|н|w)?", s)
    if m:
        n = int(m[1])
        return today + timedelta(days=n * (7 if m[2] in ("нед", "н", "w") else 1))
    m = re.fullmatch(r"(\d{4})-(\d{1,2})-(\d{1,2})", s)
    if m:
        return date(int(m[1]), int(m[2]), int(m[3]))
    m = re.fullmatch(r"(\d{1,2})[./](\d{1,2})(?:[./](\d{2}|\d{4}))?", s)
    if m:
        d, mo = int(m[1]), int(m[2])
        if m[3]:
            y = int(m[3])
            return date(y + 2000 if y < 100 else y, mo, d)
        cand = date(today.year, mo, d)
        if (today - cand).days > 180:
            cand = date(today.year + 1, mo, d)
        return cand
    raise ValueError(f"не понял дату: {text}")


def parse_duration(text):
    s = text.strip().lower().replace(",", ".")
    m = re.fullmatch(r"(\d+(?:\.\d+)?)\s*(ч|h|мин|м|min|m|сек|с|s)?", s)
    if m:
        unit = m[2] or "м"
        mult = 3600 if unit in ("ч", "h") else 1 if unit in ("сек", "с", "s") else 60
        return int(float(m[1]) * mult)
    parts = s.split(":")
    if len(parts) in (2, 3) and all(p.isdigit() for p in parts):
        nums = [int(p) for p in parts]
        if len(nums) == 2:
            return nums[0] * 60 + nums[1]
        return nums[0] * 3600 + nums[1] * 60 + nums[2]
    raise ValueError(f"не понял длительность: {text}")


def match_project(query, projects):
    q = query.replace("_", " ").strip().lower()
    if not q:
        return None
    for p in projects:
        if p.lower() == q:
            return p
    for p in projects:
        words = [w for w in re.split(r"[\s\-]+", p) if w]
        if len(words) > 1 and "".join(w[0] for w in words).lower() == q:
            return p
    for p in projects:
        if p.lower().startswith(q):
            return p
    for p in projects:
        if q in p.lower():
            return p
    return query.replace("_", " ").strip()


# ───────────────────────── повторы ─────────────────────────
# Правила: "d" каждый день, "wd" по будням, "w:0,3" по дням недели,
#          "n:14" раз в N дней, "m:21" каждый месяц такого-то числа.

def parse_recur_token(s):
    s = s.lower().strip(",")
    if s in ("д", "день", "ежедн", "ежедневно", "каждый", "d", "daily"):
        return "d"
    if s in ("будни", "wd", "weekdays"):
        return "wd"
    if s in ("нед", "неделя", "еженед", "w", "weekly"):
        return "W"
    if s in ("мес", "месяц", "ежемес", "m", "monthly"):
        return "M"
    m = re.fullmatch(r"(\d{1,2})\s*(н|нед|w)", s)
    if m:
        return f"n:{7 * int(m[1])}" if int(m[1]) > 0 else None
    m = re.fullmatch(r"(\d{1,3})\s*(д|d)?", s)
    if m:
        return f"n:{int(m[1])}" if int(m[1]) > 0 else None
    parts = [p for p in s.split(",") if p]
    if parts and all(p in WEEKDAYS for p in parts):
        return "w:" + ",".join(str(i) for i in sorted({WEEKDAYS[p] for p in parts}))
    return None


def finalize_recur(rule, base):
    if rule == "W":
        return f"w:{base.weekday()}"
    if rule == "M":
        return f"m:{base.day}"
    if rule == "n:1":
        return "d"
    return rule


def recur_weekdays(rule):
    kind, _, arg = (rule or "").partition(":")
    if kind != "w":
        return []
    return sorted({int(x) for x in arg.split(",") if x.strip().isdigit() and 0 <= int(x) <= 6})


def occurrence_on_or_after(rule, d):
    kind, _, arg = rule.partition(":")
    if kind == "wd":
        return d if d.weekday() < 5 else d + timedelta(days=7 - d.weekday())
    if kind == "w":
        days = recur_weekdays(rule) or [d.weekday()]
        for i in range(7):
            c = d + timedelta(days=i)
            if c.weekday() in days:
                return c
    if kind == "m":
        dom = int(arg) if arg.isdigit() else d.day
        y, mo = d.year, d.month
        for _ in range(3):
            c = date(y, mo, min(dom, calendar.monthrange(y, mo)[1]))
            if c >= d:
                return c
            mo += 1
            if mo > 12:
                mo, y = 1, y + 1
    return d


def next_occurrence(rule, due, today):
    kind, _, arg = rule.partition(":")
    if kind == "n":
        k = max(1, int(arg)) if arg.isdigit() else 1
        base = due if (due and due >= today) else today
        return base + timedelta(days=k)
    if due and due < today:
        return occurrence_on_or_after(rule, today)
    return occurrence_on_or_after(rule, (due or today) + timedelta(days=1))


def fmt_recur(rule):
    if not rule:
        return ""
    kind, _, arg = rule.partition(":")
    if kind == "d":
        return "каждый день"
    if kind == "wd":
        return "по будням"
    if kind == "w":
        days = recur_weekdays(rule)
        return "каждый день" if len(days) == 7 else ", ".join(WD_SHORT[i] for i in days)
    if kind == "n":
        k = int(arg) if arg.isdigit() else 1
        if k % 7 == 0:
            w = k // 7
            return "каждую неделю" if w == 1 else f"раз в {w} {plural(w, WEEK_FORMS)}"
        return "каждый день" if k == 1 else f"раз в {k} {plural(k, DAY_FORMS)}"
    if kind == "m":
        return f"каждый месяц, {arg}-го"
    return rule


def parse_quick(text, projects, today):
    res = {"title": "", "project": None, "priority": None, "due": None,
           "estimate": None, "plan": None, "recur": None}
    words = []
    recur = None
    for tok in text.split():
        if tok == "*":
            res["plan"] = today
            continue
        if len(tok) > 1 and tok[0] == "*":
            try:
                res["plan"] = parse_date(tok[1:], today)
                continue
            except ValueError:
                pass
        if len(tok) > 1 and tok[0] == "#" and re.search(r"[^\W\d_]", tok[1:]):
            res["project"] = match_project(tok[1:], projects)
            continue
        m = re.fullmatch(r"!([1-3])", tok)
        if m:
            res["priority"] = int(m[1])
            continue
        m = re.fullmatch(r"~(\d{1,2})", tok)
        if m:
            res["estimate"] = max(1, int(m[1]))
            continue
        if len(tok) > 1 and tok[0] == "@":
            try:
                res["due"] = parse_date(tok[1:], today)
                continue
            except ValueError:
                pass
        if len(tok) > 1 and tok[0] == "^":
            spec = parse_recur_token(tok[1:])
            if spec:
                recur = spec
                continue
        words.append(tok)
    res["title"] = " ".join(words)
    if recur:
        res["recur"] = finalize_recur(recur, res["due"] or today)
        if res["due"] is None:
            res["due"] = occurrence_on_or_after(res["recur"], today)
    return res


# ───────────────────────── иконка (рисуется кодом) ─────────────────────────

def _star_poly(cx, cy, r_out, r_in):
    pts = []
    for i in range(10):
        a = -math.pi / 2 + i * math.pi / 5
        r = r_out if i % 2 == 0 else r_in
        pts.append((cx + r * math.cos(a), cy + r * math.sin(a)))
    return pts


def _inside(poly, x, y):
    hit = False
    j = len(poly) - 1
    for i in range(len(poly)):
        xi, yi = poly[i]
        xj, yj = poly[j]
        if (yi > y) != (yj > y) and x < (xj - xi) * (y - yi) / (yj - yi) + xi:
            hit = not hit
        j = i
    return hit


def _icon_rows(size, disc=(63, 78, 31), ring=(201, 162, 39), star=(226, 181, 60)):
    """Значок Генштаба: оливковый круг, латунное кольцо и пятиконечная звезда (сглаживание 2×2)."""
    cx = cy = size / 2
    r_out = size * 0.47
    ring_r, ring_w = size * 0.405, max(0.6, size * 0.022)
    poly = _star_poly(cx, cy + size * 0.015, size * 0.30, size * 0.122)
    subs = ((0.25, 0.25), (0.75, 0.25), (0.25, 0.75), (0.75, 0.75))
    rows = []
    for y in range(size):
        row = bytearray()
        for x in range(size):
            acc = [0.0, 0.0, 0.0]
            cover = 0
            for sx, sy in subs:
                px_, py_ = x + sx, y + sy
                dist = math.hypot(px_ - cx, py_ - cy)
                if dist > r_out:
                    continue
                cover += 1
                if _inside(poly, px_, py_):
                    col = star
                elif abs(dist - ring_r) <= ring_w:
                    col = ring
                else:
                    col = disc
                acc[0] += col[0]
                acc[1] += col[1]
                acc[2] += col[2]
            if not cover:
                row += b"\x00\x00\x00\x00"
                continue
            rgb = [int(v / cover + 0.5) for v in acc]
            row += bytes((*rgb, int(255 * cover / len(subs) + 0.5)))
        rows.append(bytes(row))
    return rows

def png_bytes(size):
    raw = b"".join(b"\x00" + r for r in _icon_rows(size))

    def chunk(tag, data):
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", size, size, 8, 6, 0, 0, 0))
            + chunk(b"IDAT", zlib.compress(raw, 9)) + chunk(b"IEND", b""))


def ico_bytes(sizes=(16, 24, 32, 48, 64, 128, 256)):
    pngs = [png_bytes(s) for s in sizes]
    out = struct.pack("<HHH", 0, 1, len(sizes))
    offset = 6 + 16 * len(sizes)
    for s, data in zip(sizes, pngs):
        out += struct.pack("<BBBBHHII", s % 256, s % 256, 0, 0, 1, 32, len(data), offset)
        offset += len(data)
    return out + b"".join(pngs)


# ───────────────────────── система ─────────────────────────

def _spawn(args):
    try:
        subprocess.Popen(args, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
        return True
    except OSError:
        return False


def ps_str(s):
    return "'" + str(s).replace("'", "''") + "'"


def run_powershell(script, wait=True, timeout=60):
    full = "[Console]::OutputEncoding = [Text.Encoding]::UTF8\n" + script
    enc = base64.b64encode(full.encode("utf-16-le")).decode()
    args = ["powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-EncodedCommand", enc]
    if not wait:
        return _spawn(args)
    r = subprocess.run(args, capture_output=True, timeout=timeout, creationflags=NO_WINDOW)
    return r.returncode, r.stdout.decode("utf-8", "replace"), r.stderr.decode("utf-8", "replace")


def open_path(path):
    try:
        if IS_WIN:
            os.startfile(str(path))
        elif IS_MAC:
            _spawn(["open", str(path)])
        else:
            _spawn(["xdg-open", str(path)])
    except OSError:
        pass


def sound_command():
    if IS_MAC:
        p = "/System/Library/Sounds/Glass.aiff"
        if os.path.exists(p) and shutil.which("afplay"):
            return ["afplay", p]
    elif IS_LINUX:
        sounds = ["/usr/share/sounds/freedesktop/stereo/complete.oga",
                  "/usr/share/sounds/freedesktop/stereo/bell.oga"]
        for player in ("paplay", "pw-play"):
            if shutil.which(player):
                for p in sounds:
                    if os.path.exists(p):
                        return [player, p]
    return None


def system_notification(title, message):
    try:
        if IS_MAC:
            def esc(x):
                return x.replace("\\", "\\\\").replace('"', '\\"')
            _spawn(["osascript", "-e", f'display notification "{esc(message)}" with title "{esc(title)}"'])
        elif IS_WIN:
            ico = APP_DIR / "genshtab.ico"
            icon = (f"New-Object System.Drawing.Icon({ps_str(ico)})" if ico.exists()
                    else "[System.Drawing.SystemIcons]::Information")
            run_powershell(
                "Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName System.Drawing\n"
                "$n = New-Object System.Windows.Forms.NotifyIcon\n"
                f"$n.Icon = {icon}\n"
                f"$n.BalloonTipTitle = {ps_str(title)}\n$n.BalloonTipText = {ps_str(message)}\n"
                "$n.Visible = $true; $n.ShowBalloonTip(6000); Start-Sleep -Seconds 7; $n.Dispose()",
                wait=False)
        elif shutil.which("notify-send"):
            _spawn(["notify-send", "-a", APP_NAME, title, message])
    except Exception:
        pass


def system_prefers_dark():
    try:
        if IS_WIN:
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                                r"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize") as k:
                return winreg.QueryValueEx(k, "AppsUseLightTheme")[0] == 0
        if IS_MAC:
            r = subprocess.run(["defaults", "read", "-g", "AppleInterfaceStyle"],
                               capture_output=True, text=True, timeout=2)
            return "dark" in r.stdout.lower()
        if shutil.which("gsettings"):
            for key in ("color-scheme", "gtk-theme"):
                r = subprocess.run(["gsettings", "get", "org.gnome.desktop.interface", key],
                                   capture_output=True, text=True, timeout=2)
                if "dark" in r.stdout.lower():
                    return True
    except Exception:
        pass
    return False


def gui_python():
    exe = Path(sys.executable)
    if IS_WIN:
        cand = exe.with_name("pythonw.exe")
        if cand.exists():
            return str(cand)
    return str(exe)


def _desktop_quote(arg):
    if re.fullmatch(r"[\w@%+=:,./-]+", arg):
        return arg
    return '"' + re.sub(r'(["`$\\])', r"\\\1", arg) + '"'


class Integration:
    """Установка в систему: копия скрипта, иконка, ярлыки, автозапуск."""

    RUN_KEY = r"Software\Microsoft\Windows\CurrentVersion\Run"
    RUN_VALUE = "Genshtab"

    def command(self, minimized=False):
        cmd = [str(SCRIPT_PATH)] if FROZEN else [gui_python(), str(INSTALLED_SCRIPT)]
        if minimized:
            cmd.append("--minimized")
        return cmd

    def running_from_install(self):
        return FROZEN or SCRIPT_PATH == INSTALLED_SCRIPT.resolve()

    def installed_differs(self):
        if self.running_from_install() or not INSTALLED_SCRIPT.exists():
            return False
        try:
            return SCRIPT_PATH.read_bytes() != INSTALLED_SCRIPT.read_bytes()
        except OSError:
            return False

    def copy_self(self):
        if FROZEN:
            return
        APP_DIR.mkdir(parents=True, exist_ok=True)
        if not self.running_from_install():
            shutil.copy2(SCRIPT_PATH, INSTALLED_SCRIPT)

    def write_icons(self):
        APP_DIR.mkdir(parents=True, exist_ok=True)
        png = APP_DIR / "genshtab.png"
        if not png.exists():
            png.write_bytes(png_bytes(256))
        if IS_WIN:
            ico = APP_DIR / "genshtab.ico"
            if not ico.exists():
                ico.write_bytes(ico_bytes())
        return png

    # --- состояние ---
    def shortcuts_exist(self):
        if IS_WIN:
            appdata = os.environ.get("APPDATA")
            return bool(appdata) and (Path(appdata) / "Microsoft" / "Windows" / "Start Menu" / "Programs"
                                      / f"{APP_NAME}.lnk").exists()
        if IS_MAC:
            return self._mac_app().exists()
        return self._linux_menu_entry().exists()

    def autostart_enabled(self):
        try:
            if IS_WIN:
                import winreg
                with winreg.OpenKey(winreg.HKEY_CURRENT_USER, self.RUN_KEY) as k:
                    winreg.QueryValueEx(k, self.RUN_VALUE)
                return True
            if IS_MAC:
                return self._mac_agent().exists()
            return self._linux_autostart().exists()
        except OSError:
            return False

    # --- действия ---
    def install(self, autostart=None):
        self.copy_self()
        self.write_icons()
        if IS_WIN:
            made = self._win_shortcuts()
        elif IS_MAC:
            made = [str(self._mac_bundle())]
        else:
            made = self._linux_entries()
        if autostart is not None:
            self.set_autostart(autostart)
        elif self.autostart_enabled():
            self.set_autostart(True)
        return made

    def uninstall(self):
        removed = []
        self.set_autostart(False)
        try:
            guard_set(False)
        except Exception:
            pass
        if IS_WIN:
            script = ("foreach ($dir in @([Environment]::GetFolderPath('Desktop'), "
                      "[Environment]::GetFolderPath('Programs'))) {\n"
                      f"  $p = Join-Path $dir {ps_str(APP_NAME + '.lnk')}\n"
                      "  if (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Force; Write-Output $p }\n}")
            code, out, _err = run_powershell(script)
            removed += [line.strip() for line in out.splitlines() if line.strip()]
        elif IS_MAC:
            app = self._mac_app()
            if app.exists():
                shutil.rmtree(app, ignore_errors=True)
                removed.append(str(app))
        else:
            for p in (self._linux_menu_entry(), self._linux_desktop_dir() / "genshtab.desktop"):
                if p.exists():
                    p.unlink()
                    removed.append(str(p))
        return removed

    def set_autostart(self, on):
        if on:
            self.copy_self()
            self.write_icons()
        if IS_WIN:
            import winreg
            with winreg.CreateKey(winreg.HKEY_CURRENT_USER, self.RUN_KEY) as k:
                if on:
                    winreg.SetValueEx(k, self.RUN_VALUE, 0, winreg.REG_SZ,
                                      subprocess.list2cmdline(self.command(minimized=True)))
                else:
                    try:
                        winreg.DeleteValue(k, self.RUN_VALUE)
                    except OSError:
                        pass
        elif IS_MAC:
            agent = self._mac_agent()
            if on:
                app = self._mac_bundle()
                agent.parent.mkdir(parents=True, exist_ok=True)
                with open(agent, "wb") as f:
                    plistlib.dump({"Label": BUNDLE_ID, "RunAtLoad": True,
                                   "ProgramArguments": ["/usr/bin/open", "-a", str(app), "--args", "--minimized"]}, f)
            elif agent.exists():
                agent.unlink()
        else:
            path = self._linux_autostart()
            if on:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(self._desktop_entry(minimized=True, autostart=True), encoding="utf-8")
            elif path.exists():
                path.unlink()

    # --- Windows ---
    def _win_shortcuts(self):
        cmd = self.command()
        target, args = cmd[0], subprocess.list2cmdline(cmd[1:])
        ico = APP_DIR / "genshtab.ico"
        script = (
            "$ws = New-Object -ComObject WScript.Shell\n"
            "foreach ($dir in @([Environment]::GetFolderPath('Desktop'), [Environment]::GetFolderPath('Programs'))) {\n"
            "  if (-not $dir) { continue }\n"
            f"  $path = Join-Path $dir {ps_str(APP_NAME + '.lnk')}\n"
            "  $s = $ws.CreateShortcut($path)\n"
            f"  $s.TargetPath = {ps_str(target)}\n"
            f"  $s.Arguments = {ps_str(args)}\n"
            f"  $s.WorkingDirectory = {ps_str(APP_DIR)}\n"
            f"  $s.IconLocation = {ps_str(str(ico) + ',0')}\n"
            f"  $s.Description = {ps_str('Генштаб: приказ на день, штурмы, дисциплина, тыл и разведка')}\n"
            "  $s.Save()\n"
            "  Write-Output $path\n"
            "}\n")
        code, out, err = run_powershell(script)
        if code != 0:
            raise OSError(err.strip() or "PowerShell не смог создать ярлыки")
        return [line.strip() for line in out.splitlines() if line.strip()]

    # --- macOS ---
    def _frozen_bundle(self):
        if FROZEN and IS_MAC:
            for parent in SCRIPT_PATH.parents:
                if parent.suffix == ".app":
                    return parent
        return None

    def _mac_app(self):
        bundle = self._frozen_bundle()
        if bundle is not None:
            return bundle
        return Path.home() / "Applications" / f"{APP_NAME}.app"

    def _mac_agent(self):
        return Path.home() / "Library" / "LaunchAgents" / f"{BUNDLE_ID}.plist"

    def _mac_bundle(self):
        bundle = self._frozen_bundle()
        if bundle is not None:
            return bundle
        app = self._mac_app()
        macos, res = app / "Contents" / "MacOS", app / "Contents" / "Resources"
        macos.mkdir(parents=True, exist_ok=True)
        res.mkdir(parents=True, exist_ok=True)
        launcher = macos / "genshtab"
        launcher.write_text("#!/bin/sh\nexec " + " ".join(shlex.quote(c) for c in self.command()) + ' "$@"\n',
                            encoding="utf-8")
        launcher.chmod(0o755)
        info = {"CFBundleName": APP_NAME, "CFBundleDisplayName": APP_NAME, "CFBundleIdentifier": BUNDLE_ID,
                "CFBundleExecutable": "genshtab", "CFBundlePackageType": "APPL",
                "CFBundleShortVersionString": VERSION, "CFBundleVersion": VERSION,
                "NSHighResolutionCapable": True}
        if self._mac_icns(res / "genshtab.icns"):
            info["CFBundleIconFile"] = "genshtab"
        with open(app / "Contents" / "Info.plist", "wb") as f:
            plistlib.dump(info, f)
        return app

    def _mac_icns(self, out):
        if out.exists():
            return True
        if not shutil.which("iconutil"):
            return False
        with tempfile.TemporaryDirectory() as tmp:
            iconset = Path(tmp) / "genshtab.iconset"
            iconset.mkdir()
            cache = {}
            for base in (16, 32, 128, 256):
                for scale in (1, 2):
                    size = base * scale
                    if size not in cache:
                        cache[size] = png_bytes(size)
                    suffix = "@2x" if scale == 2 else ""
                    (iconset / f"icon_{base}x{base}{suffix}.png").write_bytes(cache[size])
            r = subprocess.run(["iconutil", "-c", "icns", str(iconset), "-o", str(out)], capture_output=True)
            return r.returncode == 0 and out.exists()

    # --- Linux ---
    def _linux_menu_entry(self):
        return Path.home() / ".local" / "share" / "applications" / "genshtab.desktop"

    def _linux_autostart(self):
        return Path(os.environ.get("XDG_CONFIG_HOME") or Path.home() / ".config") / "autostart" / "genshtab.desktop"

    def _linux_desktop_dir(self):
        try:
            if shutil.which("xdg-user-dir"):
                out = subprocess.run(["xdg-user-dir", "DESKTOP"], capture_output=True, text=True, timeout=3).stdout
                if out.strip() and Path(out.strip()) != Path.home():
                    return Path(out.strip())
        except Exception:
            pass
        return Path.home() / "Desktop"

    def _desktop_entry(self, minimized=False, autostart=False):
        lines = ["[Desktop Entry]", "Type=Application", "Version=1.0", f"Name={APP_NAME}",
                 "Comment=Генштаб: приказ на день, штурмы, дисциплина, тыл и разведка",
                 "Exec=" + " ".join(_desktop_quote(c) for c in self.command(minimized)),
                 f"Icon={APP_DIR / 'genshtab.png'}", "Terminal=false", "Categories=Office;Utility;",
                 "StartupWMClass=Genshtab"]
        if autostart:
            lines.append("X-GNOME-Autostart-enabled=true")
        return "\n".join(lines) + "\n"

    def _linux_entries(self):
        made = []
        menu = self._linux_menu_entry()
        menu.parent.mkdir(parents=True, exist_ok=True)
        menu.write_text(self._desktop_entry(), encoding="utf-8")
        made.append(str(menu))
        desk = self._linux_desktop_dir()
        if desk.is_dir():
            p = desk / "genshtab.desktop"
            p.write_text(self._desktop_entry(), encoding="utf-8")
            p.chmod(0o755)
            made.append(str(p))
        return made


def legacy_port():
    try:
        user = getpass.getuser()
    except Exception:
        user = "user"
    return 42000 + zlib.crc32(f"{LEGACY_ID}:{user}:{LEGACY_DIR / 'data.json'}".encode()) % 20000


def legacy_ping(message):
    """Сообщение запущенному Темпу 8.0 (тот же протокол, его порт)."""
    try:
        with socket.create_connection(("127.0.0.1", legacy_port()), timeout=1.5) as c:
            c.sendall(f"{LEGACY_ID}:{message}\n".encode())
            c.settimeout(1.5)
            return c.recv(64).startswith(f"{LEGACY_ID}:ok".encode())
    except OSError:
        return False


def stop_legacy():
    """Закрывает запущенный Темп: иначе два приложения считают одни и те же часы и слушают одного бота."""
    if not legacy_ping("quit"):
        return False
    for _ in range(20):
        time.sleep(0.5)
        if not legacy_ping("ping"):
            break
    time.sleep(0.5)
    return True


def migrate_legacy_data():
    """Первый запуск Генштаба: данные Темпа (~/.tempo) копируются в ~/.genshtab. Оригинал остаётся как был.
    Возвращает список скопированного или None."""
    if DATA_FILE.exists() or os.environ.get("GENSHTAB_DATA") or os.environ.get("TEMPO_DATA"):
        return None
    if not (LEGACY_DIR / "data.json").exists():
        return None
    stop_legacy()
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    copied = []
    for p in sorted(LEGACY_DIR.iterdir()):
        if p.is_file() and (p.name in ("data.json", "state.json") or p.name.startswith("notes.db")):
            shutil.copy2(p, DATA_DIR / p.name)
            copied.append(p.name)
    if (LEGACY_DIR / "backups").is_dir():
        try:
            shutil.copytree(LEGACY_DIR / "backups", DATA_DIR / "backups", dirs_exist_ok=True)
            copied.append("backups")
        except OSError:
            pass
    try:
        (LEGACY_DIR / "ПЕРЕЕХАЛО В ГЕНШТАБ.txt").write_text(
            f"Данные скопированы в {DATA_DIR} при первом запуске Генштаба {datetime.now():%d.%m.%Y %H:%M}.\n"
            f"Эта папка больше не используется: Генштаб работает с {DATA_DIR}. Её можно удалить, когда\n"
            "убедишься, что всё на месте.\n", encoding="utf-8")
    except OSError:
        pass
    return copied


def cleanup_legacy():
    """Убирает автозапуск, стража и ярлыки Темпа, чтобы при входе в систему не стартовали оба приложения."""
    out = []
    if IS_WIN:
        try:
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, Integration.RUN_KEY, 0, winreg.KEY_SET_VALUE) as k:
                winreg.DeleteValue(k, LEGACY_RUN_VALUE)
                out.append("автозапуск Темпа")
        except OSError:
            pass
        try:
            r = subprocess.run(["schtasks", "/Delete", "/F", "/TN", LEGACY_GUARD], capture_output=True, timeout=30,
                               creationflags=NO_WINDOW)
            if r.returncode == 0:
                out.append("страж Темпа")
        except (OSError, subprocess.SubprocessError):
            pass
        try:
            _code, o, _err = run_powershell(
                "foreach ($dir in @([Environment]::GetFolderPath('Desktop'), [Environment]::GetFolderPath('Programs'))) {\n"
                f"  $p = Join-Path $dir {ps_str(LEGACY_NAME + '.lnk')}\n"
                "  if (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Force; Write-Output $p }\n}")
            out += [line.strip() for line in o.splitlines() if line.strip()]
        except Exception:
            pass
    elif IS_MAC:
        agent = Path.home() / "Library" / "LaunchAgents" / "local.tempo.app.plist"
        if agent.exists():
            agent.unlink()
            out.append(str(agent))
    else:
        for p in (Path(os.environ.get("XDG_CONFIG_HOME") or Path.home() / ".config") / "autostart" / "tempo.desktop",
                  Path.home() / ".local" / "share" / "applications" / "tempo.desktop"):
            if p.exists():
                p.unlink()
                out.append(str(p))
    return out


def write_status(state):
    """status.json для других программ (Focus и любых): идёт ли сейчас штурм, по чему и до скольки."""
    try:
        DATA_DIR.mkdir(parents=True, exist_ok=True)
        tmp = STATUS_FILE.with_name("status.json.tmp")
        tmp.write_text(json.dumps(state, ensure_ascii=False, indent=1), encoding="utf-8")
        os.replace(tmp, STATUS_FILE)
    except OSError:
        pass


class SingleInstance:
    """Второй запуск не открывает второе окно, а показывает уже открытое."""

    def __init__(self):
        try:
            user = getpass.getuser()
        except Exception:
            user = "user"
        self.port = 42000 + zlib.crc32(f"{APP_ID}:{user}:{DATA_FILE}".encode()) % 20000
        self.sock = None

    def acquire(self):
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            if IS_WIN and hasattr(socket, "SO_EXCLUSIVEADDRUSE"):
                s.setsockopt(socket.SOL_SOCKET, socket.SO_EXCLUSIVEADDRUSE, 1)
            s.bind(("127.0.0.1", self.port))
            s.listen(4)
        except OSError:
            s.close()
            return False
        self.sock = s
        return True

    def ping(self, message="show"):
        try:
            with socket.create_connection(("127.0.0.1", self.port), timeout=1.5) as c:
                c.sendall(f"{APP_ID}:{message}\n".encode())
                c.settimeout(1.5)
                return c.recv(64).startswith(f"{APP_ID}:ok".encode())
        except OSError:
            return False

    def serve(self, on_message):
        if self.sock is None:
            return

        def run():
            while True:
                try:
                    conn, _addr = self.sock.accept()
                except OSError:
                    return
                with conn:
                    try:
                        conn.settimeout(2)
                        data = conn.recv(256).decode("utf-8", "ignore").strip()
                        if data.startswith(APP_ID + ":"):
                            conn.sendall(f"{APP_ID}:ok".encode())
                            on_message(data.split(":", 1)[1])
                    except OSError:
                        pass

        threading.Thread(target=run, daemon=True).start()


# ───────────────────────── трей и глобальные клавиши ─────────────────────────

TRAY_COLORS = {"work": "#4F6228", "flow": "#7A5C1E", "short": "#2E7D4F", "long": "#B07A12"}


class Tray:
    """Значок в трее: таймер виден без окна, а окно можно спрятать совсем.

    Работает на Windows и Linux, если доступны pystray и Pillow (в собранной программе они есть).
    На macOS вместо трея используется собственная иконка в Dock.
    """

    def __init__(self, app):
        self.app = app
        self.icon = None
        self.ok = False
        self._shown = None
        self._title = None
        try:
            import pystray
            from PIL import Image, ImageDraw
            self.lib = (pystray, Image, ImageDraw)
        except Exception:
            self.lib = None

    @property
    def supported(self):
        return self.lib is not None and not IS_MAC

    def start(self):
        if not self.supported:
            return False
        pystray, Image, _draw = self.lib
        app = self.app
        item = pystray.MenuItem
        menu = pystray.Menu(
            item("Открыть Генштаб", lambda: app.post(app.show_main), default=True),
            item(lambda _i: "Пауза" if app.pomo.running else "Штурм", lambda: app.post(app.pomo.toggle)),
            item("Записать мысль или факт", lambda: app.post(app.open_capture)),
            item("Перехват соблазна (ПВО)", lambda: app.post(app.open_urge)),
            item("Записать трату", lambda: app.post(lambda: app.edit_money(None))),
            item("Построение", lambda: app.post(lambda: app.coach.open_morning())),
            item("Вечерняя сводка", lambda: app.post(app.checkin)),
            item("Пауза дежурного на час", lambda: app.post(lambda: app.coach.pause(60))),
            item("Пауза дежурного до утра", lambda: app.post(app.coach.pause_until_morning)),
            item("Повторить карточки", lambda: app.post(app.open_cards)),
            item("Мини-окно", lambda: app.post(app.open_mini)),
            pystray.Menu.SEPARATOR,
            item("Выход", lambda: app.post(app.request_quit)),
        )
        try:
            base = Image.open(io.BytesIO(png_bytes(64))).convert("RGBA")
            self.icon = pystray.Icon(APP_ID, base, self._text(APP_NAME), menu)
        except Exception:
            traceback.print_exc()
            return False

        def ready(icon):
            icon.visible = True
            self.ok = True

        def run():
            try:
                self.icon.run(setup=ready)
            except Exception:
                traceback.print_exc()
            self.ok = False

        threading.Thread(target=run, daemon=True).start()
        return True

    @staticmethod
    def _text(text):
        """На Linux X11 подпись значка обязана быть латиницей, иначе pystray падает."""
        if IS_WIN:
            return text
        try:
            text.encode("latin-1")
            return text
        except UnicodeEncodeError:
            table = {APP_NAME: "Genshtab", "Штурм": "Assault", "Бросок": "Push", "Большой привал": "Long break",
                     "Привал": "Break", ", пауза": ", paused", "сегодня": "today", " из ": " of "}
            for ru, en in table.items():
                text = text.replace(ru, en)
            return text.encode("latin-1", "ignore").decode("latin-1")

    def _render(self, frac, color, running, grow):
        _p, Image, ImageDraw = self.lib
        img = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
        d = ImageDraw.Draw(img)
        rgb = tuple(int(color[i:i + 2], 16) for i in (1, 3, 5)) if running else (138, 148, 166)
        d.ellipse((2, 2, 62, 62), fill=rgb + (255,))
        if frac > 0.002:
            if grow:
                start, end = -90, -90 + 360 * frac
            else:
                start, end = -90 + 360 * (1 - frac), 270
            d.arc((13, 13, 51, 51), start, end, fill=(255, 255, 255, 255), width=8)
        return img

    def update(self):
        if not self.ok or self.icon is None:
            return
        app = self.app
        p = app.pomo
        try:
            if p.is_active():
                val = p.display_seconds()
                title = (f"{APP_NAME}: {MODE_LABELS[p.mode]} {fmt_clock(val, up=p.mode == 'flow')}"
                         + ("" if p.running else ", пауза"))
                state = (p.mode, p.running, round(p.progress(), 2))
                if state != self._shown:
                    self._shown = state
                    self.icon.icon = self._render(p.progress(), TRAY_COLORS[p.mode], p.running, p.mode == "flow")
                    self.icon.update_menu()
            else:
                title = f"{APP_NAME}: сегодня {app.pomos_on(app.today())} из {app.store.settings['daily_goal']}"
                if self._shown is not None:
                    self._shown = None
                    self.icon.icon = self.lib[1].open(io.BytesIO(png_bytes(64))).convert("RGBA")
                    self.icon.update_menu()
            if app.timelog.running() and IS_WIN:
                title += f"\n{app.timelog.current.get('category')} {fmt_clock(app.timelog.elapsed(), up=True)}"
            title = self._text(title)
            if title != self._title:
                self._title = title
                self.icon.title = title[:120]
        except Exception:
            traceback.print_exc()
            self.ok = False

    def notify(self, title, message):
        if not self.ok or self.icon is None or not IS_WIN:
            return False
        try:
            self.icon.notify(message, title)
            return True
        except Exception:
            return False

    def stop(self):
        if self.icon is not None:
            try:
                self.icon.stop()
            except Exception:
                pass
        self.ok = False


class GlobalHotkeys:
    """Системные сочетания на Windows: работают, даже когда окно Генштаба скрыто."""

    MOD_ALT, MOD_CONTROL, MOD_NOREPEAT = 0x1, 0x2, 0x4000
    WM_HOTKEY = 0x0312

    def __init__(self, app):
        self.app = app
        self.registered = []
        self.failed = []

    def start(self, bindings):
        """bindings: [(подпись, виртуальный код клавиши, функция)] с Ctrl+Alt."""
        if not IS_WIN:
            return

        def run():
            try:
                import ctypes
                from ctypes import wintypes
                user32 = ctypes.windll.user32
                for i, (label, vk, _fn) in enumerate(bindings, 1):
                    if user32.RegisterHotKey(None, i, self.MOD_CONTROL | self.MOD_ALT | self.MOD_NOREPEAT, vk):
                        self.registered.append(label)
                    else:
                        self.failed.append(label)
                msg = wintypes.MSG()
                while user32.GetMessageW(ctypes.byref(msg), None, 0, 0) > 0:
                    if msg.message == self.WM_HOTKEY and 1 <= msg.wParam <= len(bindings):
                        self.app.post(bindings[msg.wParam - 1][2])
            except Exception:
                traceback.print_exc()

        threading.Thread(target=run, daemon=True).start()


