TASK_DEFAULTS = {
    "title": "",
    "project": "",
    "priority": 2,
    "due": None,
    "estimate": 1,
    "done_pomos": 0,
    "status": "todo",
    "planned_for": None,
    "recur": None,
    "spawned_id": None,
    "inbox": False,
    "star": None,
    "notes": "",
    "created": None,
    "completed_at": None,
    "completed_day": None,
}


def new_task(**fields):
    t = dict(TASK_DEFAULTS)
    t.update(fields)
    t["id"] = uuid.uuid4().hex[:12]
    t["created"] = datetime.now().isoformat(timespec="seconds")
    return t


def normalize_task(raw):
    t = dict(TASK_DEFAULTS)
    t.update(raw)
    if not t.get("id"):
        t["id"] = uuid.uuid4().hex[:12]
    try:
        t["priority"] = min(3, max(1, int(t["priority"])))
        t["estimate"] = max(1, int(t["estimate"]))
        t["done_pomos"] = max(0, int(t["done_pomos"]))
    except (TypeError, ValueError):
        t["priority"], t["estimate"], t["done_pomos"] = 2, 1, 0
    if t["status"] not in ("todo", "done"):
        t["status"] = "todo"
    return t


def spawn_next(task, today):
    """Следующий экземпляр повторяющейся задачи."""
    due = date.fromisoformat(task["due"]) if task.get("due") else None
    nxt = next_occurrence(task["recur"], due, today)
    return new_task(title=task["title"], project=task["project"], priority=task["priority"],
                    estimate=task["estimate"], recur=task["recur"], notes=task.get("notes", ""),
                    due=nxt.isoformat())


class Store:
    def __init__(self, path):
        self.path = Path(path)
        self.fresh = not self.path.exists()
        self.data = {
            "version": 2,
            "settings": dict(DEFAULT_SETTINGS),
            "projects": list(DEFAULT_PROJECTS),
            "tasks": [],
            "sessions": [],
            "habits": [],
            "habit_log": {},
            "log": [],
            "categories": [dict(c) for c in DEFAULT_CATEGORIES],
            "projects_meta": {},
            "system": None,
        }
        self._load()

    def _load(self):
        if not self.path.exists():
            return
        try:
            raw = json.loads(self.path.read_text(encoding="utf-8"))
            if not isinstance(raw, dict):
                raise ValueError("ожидался JSON-объект")
        except (OSError, ValueError) as exc:
            backup = self.path.with_name(f"{self.path.stem}.broken-{datetime.now():%Y%m%d-%H%M%S}.json")
            try:
                shutil.copy2(self.path, backup)
            except OSError:
                pass
            print(f"[{APP_NAME}] Не удалось прочитать {self.path} ({exc}). Копия: {backup}", file=sys.stderr)
            return
        settings = dict(DEFAULT_SETTINGS)
        settings.update(raw.get("settings") or {})
        self.data["settings"] = settings
        if isinstance(raw.get("projects"), list):
            self.data["projects"] = [str(p) for p in raw["projects"] if str(p).strip()]
        self.data["tasks"] = [normalize_task(t) for t in raw.get("tasks", []) if isinstance(t, dict)]
        sessions = []
        for s in raw.get("sessions", []):
            if isinstance(s, dict) and s.get("day"):
                s.setdefault("kind", "pomodoro")
                s.setdefault("pomos", 1 if s.get("completed") else 0)
                s.setdefault("interruptions", 0)
                sessions.append(s)
        self.data["sessions"] = sessions
        self.data["habits"] = [normalize_habit(h) for h in raw.get("habits", []) if isinstance(h, dict)]
        hlog = raw.get("habit_log")
        self.data["habit_log"] = hlog if isinstance(hlog, dict) else {}
        self.data["log"] = [e for e in raw.get("log", []) if isinstance(e, dict) and e.get("start")]
        cats = [c for c in raw.get("categories", []) if isinstance(c, dict) and c.get("name")]
        self.data["categories"] = cats or [dict(c) for c in DEFAULT_CATEGORIES]
        meta = raw.get("projects_meta")
        self.data["projects_meta"] = meta if isinstance(meta, dict) else {}
        system = raw.get("system")
        self.data["system"] = system if isinstance(system, dict) else None

    def save(self):
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            tmp = self.path.with_name(self.path.name + ".tmp")
            tmp.write_text(json.dumps(self.data, ensure_ascii=False, indent=1), encoding="utf-8")
            os.replace(tmp, self.path)
        except OSError as exc:
            print(f"[{APP_NAME}] Не удалось сохранить данные: {exc}", file=sys.stderr)

    def backup_now(self, name=None):
        if not self.path.exists():
            self.save()
        folder = self.path.parent / "backups"
        folder.mkdir(parents=True, exist_ok=True)
        target = folder / (name or f"data-{datetime.now():%Y-%m-%d-%H%M%S}.json")
        shutil.copy2(self.path, target)
        return target

    def backup_daily(self, keep=14):
        today = date.today().isoformat()
        if self.settings.get("last_backup") == today or not self.path.exists():
            return
        try:
            self.backup_now(f"data-{today}.json")
            daily = sorted((self.path.parent / "backups").glob("data-????-??-??.json"))
            for old in daily[:-keep]:
                old.unlink()
            self.settings["last_backup"] = today
        except OSError:
            pass

    def load_state(self):
        try:
            state = json.loads((self.path.parent / "state.json").read_text(encoding="utf-8"))
            return state if isinstance(state, dict) else {}
        except (OSError, ValueError):
            return {}

    def save_state(self, state):
        try:
            p = self.path.parent / "state.json"
            p.parent.mkdir(parents=True, exist_ok=True)
            tmp = p.with_name("state.json.tmp")
            tmp.write_text(json.dumps(state, ensure_ascii=False), encoding="utf-8")
            os.replace(tmp, p)
        except OSError:
            pass

    @property
    def settings(self):
        return self.data["settings"]

    @property
    def projects(self):
        return self.data["projects"]

    @property
    def tasks(self):
        return self.data["tasks"]

    @property
    def sessions(self):
        return self.data["sessions"]

    @property
    def habits(self):
        return self.data["habits"]

    @property
    def habit_log(self):
        return self.data["habit_log"]

    @property
    def categories(self):
        return self.data["categories"]


# ───────────────────────── движки таймеров ─────────────────────────

class PomodoroEngine:
    """Фокус и перерывы считают вниз, поток считает вверх."""

    def __init__(self, app):
        self.app = app
        self.mode = "work"
        self.last_focus = "work"
        self.running = False
        self.end_at = 0.0
        self.remaining = 0.0
        self.total = 0
        self.flow_acc = 0.0
        self.flow_from = 0.0
        self.started_at = None
        self.cycle_done = 0
        self.interruptions = 0
        self.custom_break = None
        self.break_tip = ""
        self.flow_reminded = False
        self._last_wall = time.time()
        self._last_value = 0.0
        self._reset_values()

    @property
    def s(self):
        return self.app.store.settings

    def _duration(self, mode):
        if mode == "short" and self.custom_break:
            return int(self.custom_break) * 60
        key = {"work": "work_min", "short": "short_min", "long": "long_min"}[mode]
        return max(1, int(self.s[key])) * 60

    def _reset_values(self):
        self.running = False
        self.started_at = None
        self.interruptions = 0
        self.flow_reminded = False
        self.flow_acc = 0.0
        if self.mode == "flow":
            self.total = 0
            self.remaining = 0.0
        else:
            self.total = self._duration(self.mode)
            self.remaining = float(self.total)
        if self.mode in ("short", "long"):
            self.break_tip = random.choice(BREAK_TIPS)
        self._last_value = self.remaining

    def _changed(self):
        self.app.on_pomo_change()
        self.app.save_engine_state()

    # --- чтение ---
    def flow_elapsed(self):
        return self.flow_acc + (time.monotonic() - self.flow_from if self.running else 0.0)

    def current_remaining(self):
        if self.mode == "flow":
            return 0.0
        return max(0.0, self.end_at - time.monotonic()) if self.running else self.remaining

    def elapsed(self):
        return self.flow_elapsed() if self.mode == "flow" else self.total - self.current_remaining()

    def display_seconds(self):
        return self.flow_elapsed() if self.mode == "flow" else self.current_remaining()

    def is_active(self):
        return self.running or self.elapsed() >= 1

    def progress(self):
        if self.mode == "flow":
            lap = max(60, int(self.s["work_min"]) * 60)
            return (self.flow_elapsed() % lap) / lap
        return self.current_remaining() / self.total if self.total else 0.0

    def flow_break_minutes(self):
        minutes = self.flow_elapsed() / 60
        return int(min(60, max(3, round(minutes / max(2, int(self.s["flow_break_div"]))))))

    # --- управление ---
    def start(self):
        if self.running:
            return
        if self.mode == "flow":
            self.flow_from = time.monotonic()
        else:
            if self.remaining <= 0:
                self.remaining = float(self.total)
            self.end_at = time.monotonic() + self.remaining
        self.running = True
        if self.started_at is None:
            self.started_at = datetime.now()
        self._changed()

    def pause(self):
        if not self.running:
            return
        if self.mode == "flow":
            self.flow_acc = self.flow_elapsed()
        else:
            self.remaining = max(0.0, self.end_at - time.monotonic())
        self.running = False
        self._changed()

    def toggle(self):
        if self.running:
            self.pause()
        else:
            self.start()

    def reset(self):
        self._reset_values()
        self._changed()

    def set_mode(self, mode):
        self.mode = mode
        if mode in FOCUS_MODES:
            self.last_focus = mode
        self.custom_break = None
        self._reset_values()
        self._changed()

    def extend(self, minutes=5):
        if self.mode == "flow":
            return
        self.total += minutes * 60
        if self.running:
            self.end_at += minutes * 60
        else:
            self.remaining += minutes * 60
        self._changed()

    def add_interruption(self):
        if self.mode in FOCUS_MODES and self.is_active():
            self.interruptions += 1

    def tick(self):
        now = time.time()
        gap = now - self._last_wall
        self._last_wall = now
        if self.running and gap > SLEEP_GAP and self.mode in FOCUS_MODES:
            if self.mode == "flow":
                self.flow_acc = self._last_value
            else:
                self.remaining = max(1.0, self._last_value)
            self.running = False
            self._changed()
            self.app.notify("Таймер на паузе",
                            f"Компьютер не отвечал {fmt_minutes(gap / 60)}. Продолжи, когда вернёшься.")
            return
        if not self.running:
            self._last_value = self.flow_acc if self.mode == "flow" else self.remaining
            return
        if self.mode == "flow":
            e = self.flow_elapsed()
            self._last_value = e
            remind = int(self.s.get("flow_remind_min") or 0)
            if remind and not self.flow_reminded and e >= remind * 60:
                self.flow_reminded = True
                self.app.notify("Долгий поток", f"Уже {fmt_minutes(e / 60)} без перерыва. Может, пора отдохнуть?")
            return
        self.remaining = max(0.0, self.end_at - time.monotonic())
        self._last_value = self.remaining
        if self.remaining <= 0:
            self._finish(completed=True)

    def finish_early(self):
        if self.mode in FOCUS_MODES and self.elapsed() < 60:
            self.reset()
            return
        self._finish(completed=(self.mode == "flow"))

    def _finish(self, completed):
        was = self.mode
        end = datetime.now()
        message = None
        if was == "work":
            el = self.total if completed else self.elapsed()
            self.app.log_session(self.started_at or end - timedelta(seconds=el), end, el / 60, completed,
                                 "pomodoro", 1 if completed else 0, self.interruptions)
            if completed:
                self.cycle_done += 1
            nxt = "long" if completed and self.cycle_done >= int(self.s["long_every"]) else "short"
            self.custom_break = None
            if completed:
                message = ("Штурм готов", f"{MODE_LABELS[nxt]}: {self._duration(nxt) // 60} мин")
        elif was == "flow":
            el = self.flow_elapsed()
            brk = self.flow_break_minutes()
            pomos = int(el // (max(1, int(self.s["work_min"])) * 60))
            self.app.log_session(self.started_at or end - timedelta(seconds=el), end, el / 60, True,
                                 "flow", pomos, self.interruptions)
            nxt = "short"
            self.custom_break = brk
        else:
            if was == "long":
                self.cycle_done = 0
            nxt = self.last_focus
            self.custom_break = None
            if completed:
                message = ("Перерыв окончен", "Пора возвращаться к работе")
        self.mode = nxt
        self._reset_values()
        if message:
            self.app.notify(*message)
        if completed:
            auto = self.s["auto_breaks"] if nxt in ("short", "long") else self.s["auto_work"]
            if auto:
                self.start()
                return
        self._changed()

    # --- сохранение между запусками ---
    def to_state(self):
        return {
            "mode": self.mode, "last_focus": self.last_focus, "running": self.running,
            "end_wall": time.time() + self.current_remaining() if self.running and self.mode != "flow" else None,
            "remaining": self.current_remaining(), "total": self.total,
            "flow_acc": self.flow_elapsed() if self.mode == "flow" else 0.0,
            "started_at": self.started_at.isoformat(timespec="seconds") if self.started_at else None,
            "cycle_done": self.cycle_done, "interruptions": self.interruptions,
            "custom_break": self.custom_break, "day": self.app.today().isoformat(), "saved": time.time(),
        }

    def restore(self, st):
        """Возвращает ('ended', datetime), если штурм закончился, пока приложение было закрыто."""
        if not st:
            return None
        try:
            mode = st.get("mode") if st.get("mode") in MODE_LABELS else "work"
            self.mode = mode
            self.last_focus = st.get("last_focus") if st.get("last_focus") in FOCUS_MODES else "work"
            self.custom_break = st.get("custom_break")
            self._reset_values()
            if st.get("day") == self.app.today().isoformat():
                self.cycle_done = int(st.get("cycle_done") or 0)
            self.interruptions = int(st.get("interruptions") or 0)
            if st.get("started_at"):
                self.started_at = datetime.fromisoformat(st["started_at"])
            now = time.time()
            saved = float(st.get("saved") or now)
            if mode == "flow":
                acc = float(st.get("flow_acc") or 0)
                if st.get("running") and now - saved < RESUME_GAP:
                    self.flow_acc = acc + max(0.0, now - saved)
                    self.start()
                else:
                    self.flow_acc = acc
                    if acc < 1:
                        self.started_at = None
                    self._changed()
                return None
            self.total = int(st.get("total") or self.total)
            if st.get("running") and st.get("end_wall"):
                left = float(st["end_wall"]) - now
                if left > 0:
                    self.remaining = left
                    self.start()
                    return None
                ended = datetime.fromtimestamp(float(st["end_wall"]))
                if mode == "work":
                    self.remaining = float(self.total)
                    self._changed()
                    return ("ended", ended)
                if mode == "long":
                    self.cycle_done = 0
                self.mode = self.last_focus
                self.custom_break = None
                self._reset_values()
                self._changed()
                return None
            self.remaining = max(0.0, min(float(st.get("remaining") or self.total), float(self.total)))
            if self.remaining >= self.total:
                self.started_at = None
            self._changed()
        except (TypeError, ValueError):
            self.mode = "work"
            self._reset_values()
        return None


class Countdown:
    def __init__(self, seconds=10 * 60):
        self.total = seconds
        self.remaining = float(seconds)
        self.running = False
        self.end_at = 0.0

    def current(self):
        return max(0.0, self.end_at - time.monotonic()) if self.running else self.remaining

    def set(self, seconds):
        self.running = False
        self.total = max(1, int(seconds))
        self.remaining = float(self.total)

    def toggle(self):
        if self.running:
            self.remaining = self.current()
            self.running = False
        else:
            if self.remaining <= 0:
                self.remaining = float(self.total)
            self.end_at = time.monotonic() + self.remaining
            self.running = True

    def reset(self):
        self.set(self.total)

    def tick(self):
        if self.running and self.current() <= 0:
            self.running = False
            self.remaining = 0.0
            return True
        return False


class Stopwatch:
    def __init__(self):
        self.acc = 0.0
        self.started = None
        self.laps = []

    @property
    def running(self):
        return self.started is not None

    def elapsed(self):
        return self.acc + (time.monotonic() - self.started if self.started is not None else 0.0)

    def toggle(self):
        if self.running:
            self.acc = self.elapsed()
            self.started = None
        else:
            self.started = time.monotonic()

    def lap(self):
        if self.elapsed() > 0:
            self.laps.append(self.elapsed())

    def reset(self):
        self.acc = 0.0
        self.started = None
        self.laps = []


# ───────────────────────── привычки и антипривычки ─────────────────────────

HABIT_DEFAULTS = {
    "title": "",
    "kind": "do",          # do — делаю, quit — бросаю
    "target": 1,           # сколько раз в день для «делаю»
    "unit": "",
    "days": [0, 1, 2, 3, 4, 5, 6],
    "note": "",            # зачем это нужно
    "since": None,
    "created": None,
    "archived": False,
}


def new_habit(**fields):
    h = dict(HABIT_DEFAULTS)
    h.update(fields)
    h["id"] = uuid.uuid4().hex[:12]
    h["created"] = datetime.now().isoformat(timespec="seconds")
    if not h.get("since"):
        h["since"] = date.today().isoformat()
    return h


def normalize_habit(raw):
    h = dict(HABIT_DEFAULTS)
    h.update(raw)
    if not h.get("id"):
        h["id"] = uuid.uuid4().hex[:12]
    try:
        h["target"] = max(1, int(h["target"]))
    except (TypeError, ValueError):
        h["target"] = 1
    days = []
    for d in h.get("days") or []:
        try:
            if 0 <= int(d) <= 6:
                days.append(int(d))
        except (TypeError, ValueError):
            pass
    h["days"] = sorted(set(days)) or [0, 1, 2, 3, 4, 5, 6]
    if h["kind"] not in ("do", "quit"):
        h["kind"] = "do"
    if not h.get("since"):
        h["since"] = (h.get("created") or datetime.now().isoformat())[:10]
    return h


def habit_since(h):
    try:
        return date.fromisoformat(h["since"])
    except (TypeError, ValueError):
        return date.today()


def habit_scheduled(h, d):
    return True if h["kind"] == "quit" else d.weekday() in h["days"]


def habit_value(hlog, hid, d):
    try:
        return int((hlog.get(hid) or {}).get(d.isoformat(), 0))
    except (TypeError, ValueError, AttributeError):
        return 0


def habit_done(h, value):
    return value == 0 if h["kind"] == "quit" else value >= h["target"]


def habit_streak(h, hlog, today):
    """«Делаю»: сколько запланированных дней подряд закрыто. «Бросаю»: сколько дней без срыва."""
    since = habit_since(h)
    d = today
    if h["kind"] == "do" and habit_scheduled(h, d) and not habit_done(h, habit_value(hlog, h["id"], d)):
        d -= timedelta(days=1)
    n = 0
    while d >= since:
        if not habit_scheduled(h, d):
            d -= timedelta(days=1)
            continue
        if habit_done(h, habit_value(hlog, h["id"], d)):
            n += 1
            d -= timedelta(days=1)
        else:
            break
    return n


def habit_best(h, hlog, today):
    since = habit_since(h)
    best = run = 0
    d = since
    while d <= today:
        if habit_scheduled(h, d):
            if habit_done(h, habit_value(hlog, h["id"], d)):
                run += 1
                best = max(best, run)
            else:
                run = 0
        d += timedelta(days=1)
    return max(best, habit_streak(h, hlog, today))


def habit_rate(h, hlog, today, days=28):
    since = habit_since(h)
    done = total = 0
    for i in range(days):
        d = today - timedelta(days=i)
        if d < since or not habit_scheduled(h, d):
            continue
        total += 1
        if habit_done(h, habit_value(hlog, h["id"], d)):
            done += 1
    return done, total


def habit_slips(h, hlog, today, days=30):
    return sum(habit_value(hlog, h["id"], today - timedelta(days=i)) for i in range(days))


