class BulkAddDialog(tk.Toplevel):
    """Вставить список строк и получить список задач."""

    def __init__(self, app):
        super().__init__(app)
        self.app = app
        F, px = app.fonts, app.px
        self.title("Добавить списком")
        self.configure(bg=C.BG)
        self.transient(app)
        body = tk.Frame(self, bg=C.BG, padx=px(22), pady=px(18))
        body.pack(fill="both", expand=True)
        tk.Label(body, text="Каждая строка — задача", font=F["h1"], bg=C.BG, fg=C.INK).pack(anchor="w")
        tk.Label(body, text="Работают те же метки: " + QUICK_HINT, font=F["small"], bg=C.BG, fg=C.MUTED,
                 anchor="w", justify="left", wraplength=px(560)).pack(fill="x", pady=(px(4), px(10)))
        self.text = tk.Text(body, height=12, width=62, font=F["ui"], wrap="word", relief="flat",
                            bg=C.SURFACE, fg=C.INK, insertbackground=C.INK, highlightthickness=1,
                            highlightbackground=C.LINE, highlightcolor=C.FOCUS, padx=px(8), pady=px(6))
        self.text.pack(fill="both", expand=True)

        row = tk.Frame(body, bg=C.BG)
        row.pack(fill="x", pady=(px(10), 0))
        tk.Label(row, text="Проект для строк без #", font=F["ui"], bg=C.BG, fg=C.MUTED).pack(side="left")
        self.proj_var = tk.StringVar(value="")
        ttk.Combobox(row, textvariable=self.proj_var, values=[""] + app.store.projects, font=F["ui"],
                     width=24).pack(side="left", padx=px(8))
        btns = tk.Frame(body, bg=C.BG)
        btns.pack(fill="x", pady=(px(14), 0))
        ttk.Button(btns, text="Отмена", command=self.destroy).pack(side="right")
        ttk.Button(btns, text="Добавить", style="Work.TButton", command=self._save).pack(side="right", padx=(0, px(8)))
        tk.Label(btns, text="Ctrl+Enter добавляет", font=F["small"], bg=C.BG, fg=C.MUTED).pack(side="left")

        self.bind("<Escape>", lambda e: self.destroy())
        self.bind("<Control-Return>", lambda e: self._save())
        self.update_idletasks()
        x = app.winfo_rootx() + max(0, (app.winfo_width() - self.winfo_reqwidth()) // 2)
        y = app.winfo_rooty() + px(70)
        self.geometry(f"+{x}+{y}")
        self.text.focus_set()
        self.after(80, self._grab)

    def _grab(self):
        try:
            self.grab_set()
        except tk.TclError:
            pass

    def _save(self):
        app = self.app
        lines = [l.strip(" -•\t") for l in self.text.get("1.0", "end").splitlines()]
        lines = [l for l in lines if l]
        if not lines:
            self.destroy()
            return
        project = self.proj_var.get().strip()
        added, bad = 0, 0
        app.checkpoint()
        for line in lines:
            task, err = app.add_task(line, project=project, checkpoint=False, commit=False)
            if err:
                bad += 1
            else:
                added += 1
        app._commit()
        text = f"Добавлено {added} {plural(added, TASK_FORMS)}"
        if bad:
            text += f", {bad} {plural(bad, ('строка', 'строки', 'строк'))} без названия пропущено"
        app.toast(text, app.undo_action)
        self.destroy()


