def default_blocks():
    return {t: [{"start": a, "end": b, "label": l, "kind": k, "hint": h} for a, b, l, k, h in rows]
            for t, rows in SYS_BLOCKS.items()}


def parse_hm(value, default=None):
    m = re.fullmatch(r"\s*(\d{1,2})[:.](\d{2})\s*", str(value or ""))
    if not m or int(m[1]) > 23 or int(m[2]) > 59:
        return default
    return int(m[1]), int(m[2])


def at_time(d, value, default="00:00"):
    h, m = parse_hm(value) or parse_hm(default) or (0, 0)
    return datetime(d.year, d.month, d.day, h, m)


def blocks_to_text(blocks):
    return "\n".join(f"{b.get('start')}-{b.get('end')} {b.get('kind', 'study')} {b.get('label', '')}"
                     + (f" | {b['hint']}" if b.get("hint") else "") for b in blocks)


def blocks_from_text(text):
    """«09:00-11:00 study Блок 1 | подсказка» → список блоков. Ошибка — ValueError с номером строки."""
    out = []
    for n, line in enumerate(text.splitlines(), 1):
        line = line.strip()
        if not line:
            continue
        m = re.fullmatch(r"(\d{1,2}[:.]\d{2})\s*[-–—]\s*(\d{1,2}[:.]\d{2})\s+(\S+)\s*(.*)", line)
        if not m or not parse_hm(m[1]) or not parse_hm(m[2]):
            raise ValueError(f"строка {n}: нужно «09:00-11:00 study Блок 1»")
        kind = m[3].lower()
        rest = m[4]
        if kind not in BLOCK_KINDS:
            rev = {v: k for k, v in BLOCK_KINDS.items()}
            if kind in rev:
                kind = rev[kind]
            else:
                rest = f"{m[3]} {rest}".strip()
                kind = "study"
        label, _sp, hint = rest.partition("|")
        a, b = parse_hm(m[1]), parse_hm(m[2])
        out.append({"start": f"{a[0]:02d}:{a[1]:02d}", "end": f"{b[0]:02d}:{b[1]:02d}", "kind": kind,
                    "label": label.strip() or BLOCK_KINDS[kind].capitalize(), "hint": hint.strip()})
    out.sort(key=lambda b: b["start"])
    return out


def xp_level(xp):
    level = int(math.sqrt(max(0.0, xp) / 50)) + 1
    return level, 50 * (level - 1) ** 2, 50 * level ** 2


