def _seed_tasks(store, indices=None):
    titles = {t["title"] for t in store.tasks}
    today = date.today()
    for i, (title, project, prio, due, plan) in enumerate(SYS_SEED_TASKS):
        if indices is not None and i not in indices:
            continue
        if title in titles:
            continue
        if project and project not in store.projects:
            store.projects.append(project)
        planned = None
        if plan:
            planned = max(date.fromisoformat(due), today).isoformat()
        store.tasks.append(new_task(title=title, project=project, priority=prio, due=due, estimate=1,
                                    planned_for=planned))


def _seed_habits(store, start):
    have = {h.get("auto") for h in store.habits}
    for title, key, days, note in SYS_SEED_HABITS:
        if key not in have:
            store.habits.append(new_habit(title=title, kind="do", target=1, days=days, note=note,
                                          since=start, auto=key))


def _rows_to_blocks(rows):
    return [{"start": a, "end": b, "label": l, "kind": k, "hint": h} for a, b, l, k, h in rows]


def migrate_campaign(raw, store):
    """Система 96 дней (Темп 8.0) → кампания-70 (Генштаб 9.0). История дней, сессии, оценки, навыки, сеть
    и журнал остаются. Меняются период, цели, режимы дней, этапы, бюджеты, расписание, награды и дежурный.
    Прежние настройки сохраняются в system.archive.v1."""
    keep = ("start", "end", "goals", "phases", "budgets", "day_types", "weekday_types", "blocks", "touch_plan",
            "rewards", "events")
    arch = raw.get("archive") if isinstance(raw.get("archive"), dict) else {}
    arch["v1"] = json.loads(json.dumps({k: raw.get(k) for k in keep}, ensure_ascii=False))
    arch["v1"]["moved"] = date.today().isoformat()
    raw["archive"] = arch
    raw["start"], raw["end"] = CAMPAIGN_START, CAMPAIGN_END
    goals = raw.get("goals") if isinstance(raw.get("goals"), dict) else {}
    goals.update(hours=630, touches=0)
    raw["goals"] = goals

    # режимы дня: старые названия → новые, свои типы остаются
    new_types = [dict(t) for t in SYS_DAY_TYPES]
    names = {t["name"] for t in new_types}
    for t in raw.get("day_types") or []:
        if not isinstance(t, dict):
            continue
        nm = DAYTYPE_RENAME.get(t.get("name"), t.get("name"))
        if nm and nm not in names:
            new_types.append(dict(t, name=nm))
            names.add(nm)
    raw["day_types"] = new_types
    wds = [DAYTYPE_RENAME.get(x, x) for x in (raw.get("weekday_types") or [])]
    raw["weekday_types"] = wds if len(wds) == 7 and all(w in names for w in wds) else list(SYS_WEEKDAY_TYPES)
    for rec in (raw.get("days") or {}).values():
        if isinstance(rec, dict) and rec.get("type") in DAYTYPE_RENAME:
            rec["type"] = DAYTYPE_RENAME[rec["type"]]

    # расписание: стандартные блоки → новые, свои — переезжают под новым именем
    blocks = default_blocks()
    old_blocks = raw.get("blocks") if isinstance(raw.get("blocks"), dict) else {}
    for name, rows in old_blocks.items():
        if not isinstance(rows, list):
            continue
        if name in SYS_BLOCKS_V1 and rows == _rows_to_blocks(SYS_BLOCKS_V1[name]):
            continue
        blocks[DAYTYPE_RENAME.get(name, name)] = rows
    raw["blocks"] = blocks

    # этапы и бюджеты
    raw["phases"] = [dict(p) for p in SYS_PHASES]
    budgets = {k: list(v) for k, v in SYS_BUDGETS.items()}
    retakes = [r for r in raw.get("retakes") or [] if isinstance(r, dict)]
    if retakes and all(r.get("status") == "Сдано" for r in retakes):
        budgets["Пересдачи ТВ/МС"] = [0] * len(SYS_PHASES)
        for k, add in RETAKE_FREE_HOURS.items():
            budgets[k][0] += add
    for k, vals in (raw.get("budgets") or {}).items():
        if k not in budgets and isinstance(vals, list) and vals:
            cur = vals[1] if len(vals) > 1 else vals[0]
            try:
                cur = float(cur or 0)
            except (TypeError, ValueError):
                cur = 0
            budgets[k] = [cur] * len(SYS_PHASES)
    raw["budgets"] = budgets
    for name in budgets:
        if name not in store.projects:
            store.projects.append(name)
    raw["touch_plan"] = {}
    if isinstance(raw.get("net"), dict):
        raw["net"]["quota"] = False

    # навыки: облигации и финсистема
    skills = [s for s in raw.get("skills") or [] if isinstance(s, dict)]
    if not any(s.get("project") == "Облигации и финсистема" for s in skills):
        skills += [s for s in sys_default_skills() if s.get("project") == "Облигации и финсистема"]
    raw["skills"] = skills

    # календарь: старые вехи 96 дней → вехи кампании, сеть снята
    events = [e for e in raw.get("events") or [] if isinstance(e, dict)]
    drop = ("Ревью фазы 1 и развилка", "Ревью фазы 2", "Финиш: итоговое ревью",
            "Экзамены зимней сессии: вписать даты в «Оценки»")
    events = [e for e in events if not (e.get("status") != "Сделано" and str(e.get("title", "")).startswith(drop))]
    for e in events:
        title = str(e.get("title", ""))
        if e.get("status") != "Сделано" and (title.startswith("Профиль LinkedIn") or
                                             title.startswith("Информационная кампания")):
            e["status"] = "Перенесено"
            e["note"] = (e.get("note") or "") + " Сеть снята с кампании 28.09."
    have = {e.get("title") for e in events}
    for e in sys_default_events():
        if e["title"] not in have and not e["title"].startswith(("Турнир по прогнозированию", "Тесты SHL",
                                                                   "Олимпиада по ДКП")):
            events.append(e)
    raw["events"] = events

    # награды: стандартные неполученные → медали кампании, полученные и свои — остаются
    rewards = [r for r in raw.get("rewards") or [] if isinstance(r, dict)
               and (r.get("got") or r.get("title") not in SYS_REWARDS_V1)]
    titles = {r.get("title") for r in rewards}
    rewards += [{"id": _sid(), "title": t, "kind": k, "target": n, "prize": p, "got": None}
                for t, k, n, p in SYS_REWARDS if t not in titles]
    raw["rewards"] = rewards

    # дежурный: «Боевая готовность» — построение утром обязательно
    coach = raw.get("coach") if isinstance(raw.get("coach"), dict) else {}
    if coach.get("profile") in (None, "normal"):
        for section, values in COACH_PROFILES["normal"].items():
            sec = coach.get(section) if isinstance(coach.get(section), dict) else {}
            sec.update(values)
            coach[section] = sec
        coach["profile"] = "normal"
    if not coach.get("motivation") or coach.get("motivation") == COACH_MOTIVATION_V1:
        coach["motivation"] = list(COACH_DEFAULTS["motivation"])
    tc = coach.get("touches") if isinstance(coach.get("touches"), dict) else {}
    tc["on"] = False
    coach["touches"] = tc
    raw["coach"] = coach

    al = raw.get("aliases") if isinstance(raw.get("aliases"), dict) else {}
    for k, v in SYS_ALIASES.items():
        al.setdefault(k, v)
    raw["aliases"] = al
    journal = raw.get("journal") if isinstance(raw.get("journal"), list) else []
    journal.append({"ts": datetime.now().isoformat(timespec="seconds"), "kind": "campaign",
                    "text": "Генштаб: развёрнута кампания-70 (23.10–31.12), система 96 дней — в архиве"})
    raw["journal"] = journal
    for h in store.habits:
        if h.get("auto") == "hours" and h.get("title") == "План часов на день":
            h["title"] = "Норма часов на день"
            h["note"] = "Закрывается сам, когда часы дня дошли до нормы"
    _seed_tasks(store, CAMPAIGN_TASKS)
    _seed_habits(store, CAMPAIGN_START)


def ensure_system(store):
    """Подключает кампанию к данным. True — подключили только что, "migrated" — переехали с системы 96 дней."""
    raw = store.data.get("system")
    if isinstance(raw, dict) and raw.get("version"):
        try:
            version = int(raw.get("version") or 1)
        except (TypeError, ValueError):
            version = 1
        if version < 2:
            try:
                store.backup_now("data-before-genshtab.json")
            except OSError:
                pass
            migrate_campaign(raw, store)
            store.data["system"] = normalize_system(raw)
            store.settings["last_view"] = "system"
            return "migrated"
        store.data["system"] = normalize_system(raw)
        return False
    if store.path.exists():
        try:
            store.backup_now("data-before-5.0.json")
        except OSError:
            pass
    sysd = sys_defaults()
    store.data["system"] = sysd
    store.settings["last_view"] = "system"
    for name in list(sysd["budgets"]) + SYS_NO_COUNT:
        if name not in store.projects:
            store.projects.append(name)
    _seed_tasks(store)
    _seed_habits(store, sysd["start"])
    return True


def course_threshold(course, grade):
    if course.get("mode") == "ten":
        return grade - 0.5
    cands = []
    for pair in course.get("thresholds") or DEFAULT_THRESHOLDS:
        try:
            pct, g = float(pair[0]), int(pair[1])
        except (TypeError, ValueError, IndexError):
            continue
        if g >= grade:
            cands.append(pct)
    return min(cands) if cands else 100.0


def course_grade(course, score):
    if score is None:
        return None
    if course.get("mode") == "ten":
        return int(max(0, min(10, math.floor(score + 0.5))))
    pairs = []
    for pair in course.get("thresholds") or DEFAULT_THRESHOLDS:
        try:
            pairs.append((float(pair[0]), int(pair[1])))
        except (TypeError, ValueError, IndexError):
            pass
    pairs.sort(reverse=True)
    for pct, g in pairs:
        if score >= pct - 1e-9:
            return g
    return max(0, min(g for _p, g in pairs) - 1) if pairs else None


def course_calc(course):
    comps = course.get("components") or []
    top = 10.0 if course.get("mode") == "ten" else 100.0
    total_w = graded_w = graded_s = 0.0
    for c in comps:
        try:
            w = float(c.get("weight") or 0)
        except (TypeError, ValueError):
            w = 0.0
        total_w += w
        if c.get("score") is not None:
            try:
                graded_s += w * float(c["score"])
                graded_w += w
            except (TypeError, ValueError):
                pass
    try:
        target = int(course.get("target") or 9)
    except (TypeError, ValueError):
        target = 9
    thr = course_threshold(course, target)
    current = graded_s / graded_w if graded_w else None
    rest = total_w - graded_w
    need = None
    if total_w > 0 and rest > 1e-9:
        need = (thr * total_w - graded_s) / rest
    final = graded_s / total_w if total_w > 0 and rest <= 1e-9 else None
    best = (graded_s + top * rest) / total_w if total_w > 0 else None
    return {"total_w": total_w, "graded_w": graded_w, "current": current, "rest": rest, "need": need,
            "thr": thr, "top": top, "target": target, "final": final, "best": best,
            "current_grade": course_grade(course, final if final is not None else current),
            "best_grade": course_grade(course, best), "graded_share": graded_w / total_w if total_w else 0.0}


def fmt_score(course, value):
    if value is None:
        return "—"
    if course.get("mode") == "ten":
        return fmt_num(value, 1)
    return f"{value:.0f}%"


# ───────────────────────── Генштаб: резерв, переносы, наряды, звания, рубежи, разведка ─────────────────────────

def rank_of(level):
    i = max(0, min(len(RANKS) - 1, int(level) - 1))
    return i, RANKS[i]


def days_word(n):
    return f"{n} {plural(n, DAY_FORMS)}"


def cap(text):
    return text[:1].upper() + text[1:] if text else text


class CampaignMixin:
    """Твёрдость и гибкость кампании поверх системы: резерв Ставки, перенос нормы, наряды вне очереди,
    штрафы и звания, обратное планирование рубежей, линия фронта и прогноз Монте-Карло."""

    def _cached(self, name, key, fn, ttl=5.0):
        memo = self.__dict__.setdefault("_memo", {})
        hit = memo.get(name)
        now = time.monotonic()
        if hit is not None and hit[0] == key and now - hit[2] < ttl:
            return hit[1]
        value = fn()
        memo[name] = (key, value, now)
        return value

    def _ckey(self, today):
        return (self._gen, today, len(self.app.store.sessions), len(self.s["days"]), len(self.duties()),
                len(self.reserve_cfg()["used"]))

    # --- правила дисциплины и название кампании ---
    def rules(self):
        r = self.s.get("rules")
        if not isinstance(r, dict):
            r = self.s["rules"] = {}
        return r

    def rule(self, key):
        return rule_value(self.rules(), key)

    def name(self):
        return (self.s.get("name") or "").strip() or CAMPAIGN

    def rules_text(self):
        text = self.s.get("rules_text")
        return text if isinstance(text, str) and text.strip() else SYS_RULES

    # --- резерв Ставки ---
    def reserve_cfg(self):
        r = self.s.get("reserve")
        if not isinstance(r, dict):
            r = self.s["reserve"] = {"base": RESERVE_BASE, "used": {}}
        if not isinstance(r.get("used"), dict):
            r["used"] = {}
        r.setdefault("base", RESERVE_BASE)
        return r

    def is_reserve(self, d):
        return d.isoformat() in self.reserve_cfg()["used"]

    def reserve_reason(self, d):
        return self.reserve_cfg()["used"].get(d.isoformat())

    def reserve_earned(self, today):
        return self._cached("earn", self._ckey(today), lambda: self._reserve_earned(today))

    def _reserve_earned(self, today):
        """+1 резерв за каждые 7 засчитанных дней подряд; резервные дни серию не рвут, но и не считаются."""
        earned = run = 0
        for d in self.dates(self.start(), min(today - timedelta(days=1), self.end())):
            if self.is_reserve(d):
                continue
            if self.good_day(d):
                run += 1
                if run % self.rule("reserve_earn_streak") == 0:
                    earned += 1
            else:
                run = 0
        return min(earned, self.rule("reserve_earn_cap"))

    def reserve_total(self, today):
        try:
            base = int(self.reserve_cfg().get("base") or 0)
        except (TypeError, ValueError):
            base = RESERVE_BASE
        return base + self.reserve_earned(today)

    def reserve_left(self, today):
        return max(0, self.reserve_total(today) - len(self.reserve_cfg()["used"]))

    def reserve_check(self, d, now=None):
        """Можно ли объявить резерв на день d: (да/нет, почему нет)."""
        now = now or PLATFORM["now"]()
        today = self.app.today()
        if not self.active(d):
            return False, "день вне кампании"
        if self.is_reserve(d):
            return False, "этот день уже в резерве"
        if d < today:
            return False, "задним числом резерв не объявляется"
        if d == today and now >= at_time(d, self.rule("reserve_deadline")):
            return False, f"на сегодня резерв объявляется до {self.rule('reserve_deadline')}"
        if self.reserve_left(today) <= 0:
            return False, "резерв исчерпан"
        return True, ""

    def use_reserve(self, d, reason):
        r = self.reserve_cfg()
        r["used"][d.isoformat()] = (reason or "").strip()[:200]
        self._shift_extra(d)
        self.journal_add("reserve", f"{d:%d.%m}: {reason}")
        self.invalidate()

    def cancel_reserve(self, d):
        if d < self.app.today():
            return False
        if self.reserve_cfg()["used"].pop(d.isoformat(), None) is None:
            return False
        self.journal_add("reserve", f"{d:%d.%m}: резерв отменён")
        self.invalidate()
        return True

    # --- норма дня: тип + наряды и переносы − перенесённое ---
    def extra_items(self, d):
        return [x for x in (self.day(d).get("extra_items") or []) if isinstance(x, dict)]

    def extra_hours(self, d, kind=None):
        total = 0.0
        for x in self.extra_items(d):
            if kind is None or x.get("kind") == kind:
                try:
                    total += float(x.get("hours") or 0)
                except (TypeError, ValueError):
                    pass
        return total

    def moved_hours(self, d):
        try:
            return max(0.0, float(self.day(d).get("moved") or 0))
        except (TypeError, ValueError):
            return 0.0

    def base_plan(self, d):
        return self.type_hours(self.day_type(d)) if self.active(d) else 0.0

    def duty_days(self, d, n=1):
        """n ближайших дней после d, где есть норма: в кампании, не резерв, тип дня с часами."""
        out, x = [], d + timedelta(days=1)
        while len(out) < n and x <= self.end():
            if self.active(x) and not self.is_reserve(x) and self.base_plan(x) > 0:
                out.append(x)
            x += timedelta(days=1)
        return out

    def _add_extra(self, d, src, hours, kind):
        items = self.extra_items(d)
        items.append({"src": src, "hours": round(float(hours), 2), "kind": kind})
        self.day_update(d, extra_items=items)
        self.invalidate()

    def _shift_extra(self, d):
        """День уходит в резерв или увольнение: его наряды и переносы — на следующий день с нормой."""
        items = self.extra_items(d)
        if not items:
            return
        self.day_update(d, extra_items=[])
        nxt = self.duty_days(d, 1)
        if not nxt:
            return
        for x in items:
            self._add_extra(nxt[0], x.get("src"), x.get("hours") or 0, x.get("kind"))
        for duty in self.duties_open():
            if duty.get("kind") == "hours" and duty.get("target") == d.isoformat():
                duty["target"] = duty["due"] = nxt[0].isoformat()
                duty["title"] = f"+{fmt_h(duty.get('hours') or 1)} ч к норме {nxt[0]:%d.%m}"

    # --- перенос нормы ---
    def carry_debt(self, today):
        return sum(self.extra_hours(x, "carry") for x in self.dates(max(today, self.start()), self.end()))

    def carry_info(self, d, now=None):
        """Сколько недобора дня d можно перенести на два следующих дня: (часов, почему нельзя)."""
        now = now or PLATFORM["now"]()
        today = self.app.today()
        if not self.rule("carry_on"):
            return 0.0, "перенос нормы выключен в правилах"
        if not self.active(d) or self.is_reserve(d):
            return 0.0, "день без нормы"
        if d == today:
            if now < at_time(d, self.rule("carry_from")):
                return 0.0, f"перенос объявляется вечером, после {self.rule('carry_from')}"
        elif d == today - timedelta(days=1):
            if now >= at_time(today, self.rule("reserve_deadline")):
                return 0.0, f"вчерашний недобор переносится до {self.rule('reserve_deadline')}"
        else:
            return 0.0, "переносится только сегодняшний или вчерашний недобор"
        if self.moved_hours(d) > 0:
            return 0.0, "с этого дня уже переносил"
        monday = week_monday(d)
        n = sum(1 for x in self.dates(max(monday, self.start()), min(monday + timedelta(days=6), self.end()))
                if self.moved_hours(x) > 0)
        if n >= self.rule("carry_max_week"):
            return 0.0, f"на этой неделе уже {n} {plural(n, ('перенос', 'переноса', 'переносов'))} — больше нельзя"
        room = self.rule("carry_max_debt") - self.carry_debt(today)
        if room < 0.25:
            return 0.0, f"долг по переносам уже {fmt_h(self.rule('carry_max_debt') - room)} ч"
        gap = self.day_plan(d) - self.hours_on(d)
        if gap < 0.25:
            return 0.0, "недобора нет"
        if len(self.duty_days(d, self.rule("carry_days"))) < 1:
            return 0.0, "переносить некуда: кампания кончается"
        return math.floor(min(gap, self.rule("carry_max_day"), room) * 4) / 4, ""

    def carry(self, d, hours, reason):
        targets = self.duty_days(d, self.rule("carry_days"))
        if not targets or hours <= 0:
            return []
        hours = float(hours)
        self.day_update(d, moved=round(self.moved_hours(d) + hours, 2), moved_reason=(reason or "")[:200])
        part = round(hours / len(targets), 2)
        for i, t in enumerate(targets):
            h = part if i < len(targets) - 1 else round(hours - part * (len(targets) - 1), 2)
            self._add_extra(t, f"carry:{d.isoformat()}", h, "carry")
        self.journal_add("carry", f"{fmt_h(hours)} ч с {d:%d.%m} на " + ", ".join(f"{t:%d.%m}" for t in targets)
                         + (f": {reason}" if reason else ""))
        self.invalidate()
        return targets

    # --- оборона ---
    def defense_count(self, d):
        """Сколько дней «Оборона» в окне 7 дней, заканчивающемся днём d (включая его)."""
        return sum(1 for x in self.dates(max(self.start(), d - timedelta(days=6)), d)
                   if self.day_type(x) == DEFENSE_TYPE and not self.is_reserve(x))

    # --- наряды вне очереди ---
    def duties(self):
        lst = self.s.get("duties")
        if not isinstance(lst, list):
            lst = self.s["duties"] = []
        return lst

    def duties_open(self):
        return [x for x in self.duties() if x.get("status") == "open"]

    def duty_add(self, kind, title, reason, due, **extra):
        cap_n = self.rule("duty_cap")
        if len(self.duties_open()) >= cap_n:
            self.journal_add("duty", f"перегруз: наряд «{title}» не выдан — открыто уже {cap_n}")
            return None
        duty = {"id": _sid(), "kind": kind, "title": title, "reason": reason,
                "created": self.app.today().isoformat(), "due": due.isoformat(), "status": "open", "closed": None}
        duty.update(extra)
        self.duties().append(duty)
        if kind == "hours":
            target = sys_date(extra.get("target")) or due
            self._add_extra(target, f"duty:{duty['id']}", extra.get("hours") or 1, "duty")
        self.journal_add("duty", f"выдан: {title} — {reason}")
        self.invalidate()
        return duty

    def duty_close(self, duty, status, note=""):
        duty["status"] = status
        duty["closed"] = self.app.today().isoformat()
        if note:
            duty["note"] = note[:4000]
        verb = {"done": "выполнен", "failed": "провален", "cancelled": "снят"}.get(status, status)
        self.journal_add("duty", f"{verb}: {duty.get('title', '')}")
        self.invalidate()

    def duties_evaluate(self, today):
        changed = False
        for duty in self.duties_open():
            kind = duty.get("kind")
            due = sys_date(duty.get("due")) or today
            if kind == "hours":
                t = sys_date(duty.get("target")) or due
                if t < today:
                    self.duty_close(duty, "done" if self.day_met(t) else "failed")
                    changed = True
            elif kind == "task":
                task = self.app.task_by_id(duty.get("task_id"))
                if task is None:
                    self.duty_close(duty, "cancelled", "задача удалена")
                    changed = True
                elif task.get("status") == "done":
                    self.duty_close(duty, "done")
                    changed = True
                elif due < today:
                    self.duty_close(duty, "failed")
                    changed = True
            elif kind == "write" and due < today:
                self.duty_close(duty, "failed")
                changed = True
        return changed

    def upkeep(self, today, now):
        """Раз в день после утреннего часа: итог вчерашнего дня и наряды. True — данные изменились."""
        changed = self.duties_evaluate(today)
        if self.s.get("upkeep") == today.isoformat():
            return changed
        h, m = self.app.coach.morning_after()
        if now < at_time(today, f"{h:02d}:{m:02d}"):
            return changed
        self.s["upkeep"] = today.isoformat()
        y = today - timedelta(days=1)
        if not self.active(y) or self.is_reserve(y) or self.base_plan(y) <= 0:
            return True
        if not self.rule("duties_on"):
            return True
        rec = self.day(y)
        if not rec.get("done"):
            self.duty_add("write", f"Письменный разбор {y:%d.%m}",
                          "сводка пропущена" if rec.get("skipped") else "сводки нет",
                          today + timedelta(days=1))
        elif self.day_plan(y) > 0 and not self.good_day(y):
            score = self.day_score(y)[0]
            nxt = self.duty_days(y, 1)
            extra = self.rule("duty_hours")
            if nxt and nxt[0] >= today:
                self.duty_add("hours", f"+{fmt_h(extra)} ч к норме {nxt[0]:%d.%m}",
                              f"{y:%d.%m} не засчитан: боеготовность {score}",
                              nxt[0], target=nxt[0].isoformat(), hours=extra)
        mit = self.app.task_by_id(rec.get("mit_id"))
        if mit is not None and mit.get("status") != "done":
            self.duty_add("task", f"Довести главный удар: {one_line(mit['title'], 60)}",
                          f"главный удар {y:%d.%m} не доведён", today + timedelta(days=self.rule("duty_task_days")),
                          task_id=mit["id"])
        return True

    # --- штрафы и звания ---
    def penalty_cfg(self):
        p = dict(PENALTY_DEFAULTS)
        for k, v in (self.coach.get("penalties") or {}).items():
            try:
                p[k] = max(0, int(v))
            except (TypeError, ValueError):
                pass
        return p

    def penalties(self, today):
        return self._cached("pen", self._ckey(today), lambda: self._penalties(today))

    def _penalties(self, today):
        p = self.penalty_cfg()
        out = []
        wake_goal = parse_hm(self.s["goals"].get("wake"), (7, 0))
        prev_fail = False
        for d in self.dates(self.start(), min(today - timedelta(days=1), self.end())):
            if self.is_reserve(d):
                continue
            rec = self.day(d)
            if self.base_plan(d) <= 0 and not rec.get("done"):
                prev_fail = False
                continue
            fail = False
            if not rec.get("done"):
                if rec.get("skipped"):
                    out.append((d, p["skip"], PENALTY_NAMES["skip"]))
                    fail = True
                elif d < today - timedelta(days=1):
                    out.append((d, p["nocheck"], PENALTY_NAMES["nocheck"]))
                    fail = True
            elif self.day_plan(d) > 0 and not self.good_day(d):
                out.append((d, p["fail"], PENALTY_NAMES["fail"]))
                fail = True
                if prev_fail:
                    out.append((d, p["fail2"], PENALTY_NAMES["fail2"]))
            wake = parse_hm(rec.get("wake"))
            if wake and wake_goal and (wake[0] * 60 + wake[1]) - (wake_goal[0] * 60 + wake_goal[1]) > \
                    self.rule("wake_penalty"):
                out.append((d, p["wake"], f"подъём в {rec['wake']}"))
            if self.day_type(d) == DEFENSE_TYPE and self.defense_count(d) > self.rule("defense_free"):
                out.append((d, p["defense"], PENALTY_NAMES["defense"]))
            prev_fail = fail
        for duty in self.duties():
            if duty.get("status") == "failed":
                out.append((sys_date(duty.get("closed")) or today, p["duty"], f"наряд провален: {duty.get('title')}"))
        out.sort(key=lambda x: x[0])
        return out

    def xp_cached(self, today):
        return self._cached("xp", self._ckey(today), lambda: self.xp(today))

    def xp_carry(self):
        try:
            return max(0, int(self.s.get("xp_carry") or 0))
        except (TypeError, ValueError):
            return 0

    def xp_net(self, today):
        return max(0, self.xp_cached(today) + self.xp_carry() - sum(pts for _d, pts, _t in self.penalties(today)))

    def rank(self, today):
        xp = self.xp_net(today)
        level, lo, hi = xp_level(xp)
        idx, name = rank_of(level)
        nxt = RANKS[idx + 1] if idx + 1 < len(RANKS) else None
        return {"xp": xp, "level": level, "lo": lo, "hi": hi, "idx": idx, "name": name, "next": nxt,
                "gross": self.xp_cached(today), "carry": self.xp_carry(),
                "pen": sum(pts for _d, pts, _t in self.penalties(today))}

    # --- рубежи и обратное планирование ---
    def rubezhi(self, today, horizon=60):
        """Ближайшие рубежи с датой: элементы оценок, пересдачи, события «Курсы» и «Пересдачи»."""
        out = []
        for r in self.calendar():
            d = r.get("date")
            if not d or r.get("done") or d < today or (d - today).days > horizon:
                continue
            if r["src"] in ("Оценки", "Пересдачи") or (r["src"] in ("Курсы",) and r["iid"].startswith("ev:")):
                out.append(r)
        out.sort(key=lambda r: (r["date"], -(r.get("weight") or 0)))
        return out

    def major(self, row):
        """Рубеж, к которому нужен план подготовки: пересдача, элемент от 15% или событие курса."""
        if row["src"] == "Пересдачи" or row["iid"].startswith("ev:"):
            return True
        return float(row.get("weight") or 0) >= 15

    def backplanned(self, iid):
        return iid in (self.s.get("backplans") or {})

    def backplan(self, row, today):
        """Задачи подготовки назад от даты рубежа: Д-7, Д-5, Д-3, Д-2, Д-1. Возвращает созданные задачи."""
        store = self.app.store
        d = row["date"]
        left = (d - today).days
        if left < 1:
            return []
        proj = row.get("project") or ""
        if proj and proj not in store.projects:
            store.projects.append(proj)
        short = one_line(re.sub(r"\s*\(\d+(?:[.,]\d+)?%\)$", "", row["title"]), 46)
        made = []
        steps = backplan_steps(self.rules())
        for off, text in steps:
            day = d - timedelta(days=off)
            if day < today:
                if off != steps[0][0]:
                    continue
                day = today  # разведку не пропускаем: если до рубежа меньше недели — сегодня
            task = new_task(title=f"Рубеж {d:%d.%m} · {short} — {text}", project=proj,
                            priority=1 if off <= 3 else 2, due=day.isoformat(), planned_for=day.isoformat(),
                            estimate=4 if off in (5, 3) else 2, notes=f"План подготовки к рубежу: {row['title']}")
            store.tasks.append(task)
            made.append(task)
        self.s.setdefault("backplans", {})[row["iid"]] = {"date": d.isoformat(), "created": today.isoformat(),
                                                          "tasks": [t["id"] for t in made]}
        if not self.day(d).get("type") and self.day_type(d) in ("Боевой", "Марш", "Тыловой"):
            self.day_update(d, type=EXAM_TYPE)
        self.journal_add("campaign", f"план подготовки к рубежу {d:%d.%m}: {short} — задач {len(made)}")
        self.invalidate()
        return made

    # --- линия фронта ---
    def last_hours_day(self):
        last = {}
        for (day, p), v in self._hours()[1].items():
            if v > 0 and day > last.get(p, ""):
                last[p] = day
        return last

    def fronts(self, today):
        start, end = self.start(), self.end()
        upto = min(today, end)
        ph = self.phase_at(min(max(today, start), end))
        ph_end = ph["end"] if ph else end
        tot = self.hours_by_project()
        last = self.last_hours_day()
        rows = []
        for p in self.directions():
            if not p:
                continue
            b_td = self.budget_between(p, start, upto)
            b_ph = self.budget_between(p, start, ph_end)
            fact = tot.get(p, 0.0)
            weekly = self.budget(p)[ph["i"]] if ph else 0.0
            ld = sys_date(last.get(p))
            silent = (today - ld).days if ld else ((today - start).days + 1 if today >= start else 0)
            days_left = max(1, (ph_end - max(today, start)).days + 1)
            need = max(0.0, b_ph - fact) / days_left
            if b_td <= 0:
                state = "резерв" if weekly <= 0 else "наступает"
            elif fact >= b_td * 0.95:
                state = "наступает"
            elif fact >= b_td * 0.8:
                state = "держит"
            else:
                state = "отступает"
            rows.append({"name": p, "fact": fact, "budget": b_td, "gap": b_td - fact, "phase_budget": b_ph,
                         "weekly": weekly, "need": need, "silent": silent, "last": ld, "state": state})
        rows.sort(key=lambda r: (-r["gap"], r["name"]))
        return rows

    def silent_fronts(self, today, days=5):
        """Направления с бюджетом в текущем этапе, где часов нет уже days дней и больше."""
        if not self.active(today) or (today - self.start()).days < days:
            return []
        return [r for r in self.fronts(today) if r["weekly"] > 0 and r["silent"] >= days]

    # --- разведка: прогноз Монте-Карло ---
    def raw_hours(self, d):
        """Часы дня по сессиям — и вне периода кампании (для истории до старта)."""
        def build():
            skip = set(self.s.get("no_count") or [])
            acc = defaultdict(float)
            for x in self.app.store.sessions:
                if (x.get("project") or "") in skip:
                    continue
                try:
                    acc[x.get("day", "")] += float(x.get("minutes", 0) or 0) / 60
                except (TypeError, ValueError):
                    pass
            return acc
        return self._cached("raw", (self._gen, len(self.app.store.sessions)), build, ttl=30)[d.isoformat()] \
            if d else 0.0

    def history_ratios(self, today, days=28):
        """Доля выполненной нормы за последние дни (до старта кампании — по режимам дня без нарядов)."""
        out = []
        arch = (self.s.get("archive") or {}).get("v1") or {}
        first = sys_date(arch.get("start")) or self.start()
        for d in self.dates(max(first, today - timedelta(days=days)), today - timedelta(days=1)):
            if self.is_reserve(d):
                continue
            if self.active(d):
                plan, fact = self.day_plan(d), self.hours_on(d)
            else:
                plan, fact = self.type_hours(self.day_type(d)), self.raw_hours(d)
            if plan > 0:
                out.append((d, min(2.0, fact / plan)))
        return out

    def forecast(self, today, sims=2000):
        key = (self._gen, today, len(self.app.store.sessions), round(self.hours_on(today), 1), len(self.s["days"]),
               len(self.reserve_cfg()["used"]))
        return self._cached("fc", key, lambda: self._forecast(today, sims), ttl=300)

    def _forecast(self, today, sims):
        start, end = self.start(), self.end()
        goal = self.goal("hours", 630)
        hist = self.history_ratios(today)
        ratios = [r for _d, r in hist]
        prior = len(ratios) < 3
        if prior:
            ratios = ratios + [0.6, 0.75, 0.85, 0.95, 1.0]
        done_before = self.hours_between(start, today - timedelta(days=1)) if today > start else 0.0
        h_today = self.hours_on(today) if self.active(today) else 0.0
        future = [(d, self.day_plan(d)) for d in self.dates(max(today, start), end)]
        plan_rest = sum(p for _d, p in future)
        today_plan = self.day_plan(today) if self.active(today) else 0.0
        on_plan = done_before + sum(max(p, h_today) if d == today else p for d, p in future)
        rest_plan = sum(p for d, p in future if d != today) + max(0.0, today_plan - h_today)
        out = {"goal": goal, "done": done_before + h_today, "plan_rest": plan_rest, "days_left": len(future),
               "n": len(hist), "prior": prior, "mean": sum(ratios) / len(ratios) if ratios else 0.0,
               "on_plan": on_plan}
        if not future:
            out.update(p=1.0 if done_before >= goal else 0.0, q10=done_before, q50=done_before, q90=done_before,
                       hist=[], need_ratio=None, need_day=0.0)
            return out
        rnd = random.Random(today.toordinal() * 7919 + len(self.app.store.sessions))
        totals = []
        n = len(ratios)
        for _ in range(sims):
            m = min(1.35, max(0.55, rnd.gauss(1.0, 0.08)))
            tot = done_before
            for d, p in future:
                h = ratios[rnd.randrange(n)] * m * p
                if d == today:
                    h = max(h_today, h)
                tot += h
            totals.append(tot)
        totals.sort()

        def q(f):
            return totals[min(len(totals) - 1, max(0, int(f * len(totals))))]
        lo, hi = q(0.01), q(0.99)
        bins = 24
        width = max(1e-6, (hi - lo) / bins)
        hist_bins = [0] * bins
        for t in totals:
            i = int((t - lo) / width)
            if 0 <= i < bins:
                hist_bins[i] += 1
        left = max(0.0, goal - done_before - h_today)
        out.update(p=sum(1 for t in totals if t >= goal) / len(totals), q10=q(0.10), q50=q(0.50), q90=q(0.90),
                   lo=lo, hi=hi, width=width, hist=hist_bins,
                   need_ratio=(left / rest_plan) if rest_plan > 0 else None,
                   need_day=left / max(1, len(future)))
        return out

    def intel_text(self, today):
        f = self.forecast(today)
        lines = [f"Разведсводка на {today:%d.%m}: цель {int(f['goal'])} ч, сделано {fmt_h(f['done'])}"]
        if not f.get("hist") and f["days_left"] == 0:
            lines.append("Кампания завершена.")
            return "\n".join(lines)
        lines.append(f"Вероятность взять цель: {int(round(f['p'] * 100))}%")
        lines.append(f"Ожидаемый итог: {fmt_h(f['q50'])} ч (80% — от {fmt_h(f['q10'])} до {fmt_h(f['q90'])})")
        lines.append(f"Если дальше строго по норме: {fmt_h(f['on_plan'])} ч")
        if f.get("need_ratio") is not None:
            lines.append(f"Для цели нужно выполнять {int(round(f['need_ratio'] * 100))}% нормы "
                         f"(сейчас в среднем {int(round(f['mean'] * 100))}%), это {fmt_h(f['need_day'])} ч в день")
        if f["prior"]:
            lines.append("Данных пока мало: прогноз опирается на осторожное допущение.")
        return "\n".join(lines)

    # --- приказ на день ---
    def order_items(self, d):
        """Пункты приказа на день: норма, главный удар, направления огня, рубежи, наряды, тыл."""
        items = []
        if not self.active(d):
            return items
        if self.is_reserve(d):
            items.append(("Резерв Ставки", f"день без нормы: {self.reserve_reason(d) or 'отдых'}. Серия не рвётся."))
            return items
        plan = self.day_plan(d)
        extra = []
        if self.extra_hours(d, "duty"):
            extra.append(f"наряды +{fmt_h(self.extra_hours(d, 'duty'))}")
        if self.extra_hours(d, "carry"):
            extra.append(f"перенос +{fmt_h(self.extra_hours(d, 'carry'))}")
        if self.moved_hours(d):
            extra.append(f"перенесено −{fmt_h(self.moved_hours(d))}")
        items.append(("Норма", f"{fmt_h(plan)} ч · режим «{self.day_type(d)}»" + (f" ({', '.join(extra)})" if extra else "")))
        rub = self.rubezhi(d, 3)
        if rub:
            r = rub[0]
            left = (r["date"] - d).days
            items.append(("Главный удар", ("сегодня" if left == 0 else f"Д-{left}") + f": {r['title']}"))
        behind = self.behind(d)[:3]
        if behind:
            items.append(("Направления огня", ", ".join(f"{p} −{fmt_h(g)} ч" for g, p, _b, _f in behind)))
        silent = self.silent_fronts(d)
        if silent:
            items.append(("Молчат", ", ".join(f"{r['name']} {days_word(r['silent'])}" for r in silent[:3])))
        duties = self.duties_open()
        if duties:
            items.append(("Наряды", "; ".join(x.get("title", "") for x in duties)))
        rub = [r for r in self.rubezhi(d, 14) if self.major(r)]
        if rub:
            items.append(("Рубежи", "; ".join(f"Д-{(r['date'] - d).days} {one_line(r['title'], 40)}" for r in rub[:3])))
        tr = "тренировка по плану" if self.train_expected(d) else "день без тренировки"
        items.append(("Тыл", f"{tr}, отбой {(self.coach.get('bedtime') or {}).get('time') or '23:00'}, "
                             f"подъём {self.s['goals'].get('wake') or '07:00'}"))
        return items

    def campaign_line(self, today):
        total = self.total_days()
        if today < self.start():
            n = (self.start() - today).days
            return f"до старта {days_word(n)}"
        if today > self.end():
            return "кампания завершена"
        left = self.days_to_finish(today)
        ny = (date(self.end().year + 1, 1, 1) - today).days
        return f"день {self.day_no(today)} из {total} · до Нового года {days_word(ny)}" if self.end().month == 12 \
            and self.end().day == 31 else f"день {self.day_no(today)} из {total} · осталось {days_word(left)}"

    def pre_campaign_hours(self):
        arch = (self.s.get("archive") or {}).get("v1") or {}
        a = sys_date(arch.get("start"))
        if not a or a >= self.start():
            return None
        b = self.start() - timedelta(days=1)
        return a, b, sum(self.raw_hours(d) for d in self.dates(a, b))

    def rank_text(self, today):
        r = self.rank(today)
        week = [x for x in self.penalties(today) if x[0] >= today - timedelta(days=7)]
        lines = [f"Звание: {r['name']} · опыт {r['xp']} (за кампанию {r['gross']}"
                 + (f", выслуга {r['carry']}" if r["carry"] else "") + f", штрафы −{r['pen']})"]
        if r["next"]:
            lines.append(f"До звания «{r['next']}»: {r['hi'] - r['xp']} очков")
        if week:
            lines.append(f"Штрафы за 7 дней: −{sum(p for _d, p, _t in week)}")
            lines += [f"  {d:%d.%m} −{p} {t}" for d, p, t in week[-6:]]
        else:
            lines.append("Штрафов за 7 дней нет.")
        return "\n".join(lines)

    def duties_text(self, today):
        open_ = self.duties_open()
        lines = [f"Нарядов открыто: {len(open_)} из {self.rule('duty_cap')}."]
        for d in open_:
            due = sys_date(d.get("due"))
            lines.append(f"• {d.get('title')} — {d.get('reason')}" + (f" (до {due:%d.%m})" if due else ""))
        if any(d.get("kind") == "write" for d in open_):
            lines.append(f"Письменный разбор: «разбор: текст» от {self.rule('write_min')} знаков.")
        lines.append(f"Резерв: осталось {self.reserve_left(today)}. Долг по переносам: {fmt_h(self.carry_debt(today))} ч.")
        return "\n".join(lines)

    def type_change_check(self, d, new, now=None):
        """Можно ли сменить режим дня d на new: (да/нет, почему нет). Режим с меньшей нормой — заранее или
        до 16:00 этого дня; задним числом и вечером — только перенос нормы. Увольнение — только за резерв."""
        now = now or PLATFORM["now"]()
        today = self.app.today()
        cur = self.day_type(d)
        if new is None:
            new = self.s["weekday_types"][d.weekday()]
        if not new or new == cur:
            return True, ""
        if new == LEAVE_TYPE and not self.is_reserve(d):
            return False, "увольнение — только за резерв Ставки"
        if self.type_hours(new) < self.type_hours(cur) - 1e-9:
            if d < today or (d == today and now >= at_time(d, self.rule("downgrade_until"))):
                return False, (f"режим с меньшей нормой объявляется заранее или до {self.rule('downgrade_until')}; "
                               "вечером — перенос нормы")
            if self.moved_hours(d) > 0:
                return False, "с этого дня уже перенесена норма"
        return True, ""


class KitMixin:
    """Генштаб 10.0: ПВО (перехват соблазнов), протоколы «если — то», боевые листы, физподготовка, казна,
    послужной список и смена кампании."""

    # --- ПВО: перехват соблазнов ---
    def urges(self):
        return self.s["urges"]

    def urge_day(self, u):
        return sys_date(u.get("day")) or sys_date(u.get("ts"))

    def urge_kinds(self):
        out = []
        for k in list(URGE_KINDS) + [u.get("what") for u in reversed(self.urges())]:
            if k and k not in out:
                out.append(k)
        return out

    def urge_hold(self):
        try:
            return max(1, min(60, int((self.coach.get("urges") or {}).get("hold") or URGE_HOLD_MIN)))
        except (TypeError, ValueError):
            return URGE_HOLD_MIN

    def urge_add(self, what, power=3, result=None, note="", when=None, hold=True, source=None):
        now = when or PLATFORM["now"]()
        try:
            power = max(1, min(5, int(power)))
        except (TypeError, ValueError):
            power = 3
        u = {"id": _sid(), "ts": now.isoformat(timespec="seconds"),
             "day": day_of(now, self.app.store.settings["day_start_hour"]).isoformat(),
             "what": (what or "Другое").strip()[:80], "power": power, "result": result, "note": (note or "")[:300],
             "focus": bool(getattr(self.app, "coach", None) and self.app.coach.focused())}
        if source:
            u["src"] = source
        if result is None and hold:
            u["until"] = (now + timedelta(minutes=self.urge_hold())).isoformat(timespec="seconds")
        elif result is not None:
            u["closed"] = u["ts"]
        self.urges().append(u)
        del self.urges()[:-2000]
        if result == "fell":
            self.journal_add("urge", f"сорвался: {u['what']}")
        self.invalidate()
        return u

    def urge_resolve(self, u, result, note=""):
        u["result"] = result
        u.pop("until", None)
        u["closed"] = PLATFORM["now"]().isoformat(timespec="seconds")
        if note:
            u["note"] = note[:300]
        if result == "fell":
            self.journal_add("urge", f"сорвался: {u.get('what', '')}")
        self.invalidate()

    def urge_open(self):
        return [u for u in self.urges() if u.get("result") is None]

    def urge_due(self, now=None):
        """Перехваты, у которых удержание кончилось, а итога ещё нет."""
        now = now or PLATFORM["now"]()
        out = []
        for u in self.urge_open():
            try:
                if u.get("until") and datetime.fromisoformat(u["until"]) <= now:
                    out.append(u)
            except (TypeError, ValueError):
                u.pop("until", None)
        return out

    def urge_stats(self, a, b):
        items = [u for u in self.urges() if (d := self.urge_day(u)) and a <= d <= b]
        held = sum(1 for u in items if u.get("result") == "held")
        fell = sum(1 for u in items if u.get("result") == "fell")
        kinds = defaultdict(lambda: [0, 0, 0])
        hours = [0] * 24
        for u in items:
            k = kinds[u.get("what") or "Другое"]
            k[0] += 1
            if u.get("result") == "held":
                k[1] += 1
            elif u.get("result") == "fell":
                k[2] += 1
            try:
                hours[datetime.fromisoformat(u["ts"]).hour] += 1
            except (KeyError, TypeError, ValueError):
                pass
        powers = [int(u.get("power") or 0) for u in items if u.get("power")]
        return {"n": len(items), "held": held, "fell": fell, "open": len(items) - held - fell,
                "rate": held / (held + fell) if held + fell else None,
                "kinds": sorted(kinds.items(), key=lambda kv: (-kv[1][0], kv[0])), "hours": hours,
                "power": sum(powers) / len(powers) if powers else None,
                "focus": sum(1 for u in items if u.get("focus"))}

    def urge_clean_days(self, today):
        """Дней подряд без срыва, считая сегодняшний (с первого перехвата)."""
        days = [self.urge_day(u) for u in self.urges()]
        days = [d for d in days if d]
        if not days:
            return 0
        fell = {self.urge_day(u) for u in self.urges() if u.get("result") == "fell"}
        first, d, n = min(days), today, 0
        while d >= first and d not in fell:
            n += 1
            d -= timedelta(days=1)
        return n

    def kit_report_lines(self, a, b):
        """Строки донесения про ПВО, листы, казну и физо за период — только если там что-то было."""
        out = []
        st = self.urge_stats(a, b)
        if st["n"]:
            out.append(f"ПВО: перехватов {st['n']}, устоял {st['held']}, сорвался {st['fell']}"
                       + (f" — удержание {int(round(st['rate'] * 100))}%" if st["rate"] is not None else ""))
        closed = total = 0
        for d in self.dates(a, b):
            dl, nl, _m, _i = self.checks_day(d)
            closed += dl
            total += nl
        if closed:
            out.append(f"Боевые листы: закрыто {closed} из {total}")
        spent = self.money_spent(a, b)
        if spent:
            imp = [e for e in self.money_entries(a, b) if e.get("impulse")]
            out.append(f"Казна: траты {fmt_money(spent, self.money_cur())}"
                       + (f", импульсных {len(imp)}" if imp else "")
                       + (f", дней без трат {self.nospend_days(a, b)}" if b > a else ""))
        tests = [t for t in self.fit()["tests"] if a.isoformat() <= t["date"] <= b.isoformat()]
        if tests:
            parts = []
            for t in tests[-5:]:
                n = self.norm(t["norm"])
                if n:
                    parts.append(f"{n['name']} {fmt_fit_value(n['kind'], t['value'])}")
            out.append("Физо: " + ", ".join(parts))
        return out

    def kit_alerts(self, today):
        """Сигналы 10.0 для «Сводки»: перехваты без итога, перерасход, нормативы, желания на решение."""
        app = self.app
        out = []
        stale = [u for u in self.urge_due() if u.get("asked")]
        if stale:
            out.append(("warn", f"Перехваты без итога: {len(stale)} — " + ", ".join(u.get("what", "") for u in stale[:3])
                        + ". Устоял или сорвался — честно.", lambda: app.views["discipline"].set_tab("pvo"), "ПВО"))
        m = self.money()
        if m.get("entries"):
            mm = self.money_month(today)
            cur = self.money_cur()
            if mm["limit"] and mm["spent"] > mm["limit"]:
                out.append(("bad", f"Казна: перерасход месяца {fmt_money(mm['spent'] - mm['limit'], cur)}. До конца "
                                   "месяца — только необходимое.", lambda: app._goto("money"), "Казна"))
            elif mm["limit"] and mm["pace"] and mm["pace"] > 1.15 and today.day >= 5:
                out.append(("warn", f"Казна: траты идут на {int(round((mm['pace'] - 1) * 100))}% быстрее лимита. "
                                    f"В день — не больше {fmt_money(max(0, int(mm['per_day'])), cur)}.",
                            lambda: app._goto("money"), "Казна"))
            ready = [w for w in m.get("wishes") or [] if w.get("status") == "wait" and self.wish_ready(w)]
            if ready:
                out.append(("info", f"Желания ждут решения: {', '.join(w['title'] for w in ready[:3])}. Хочется так же — "
                                    "купи осознанно, прошло — откажись.", lambda: app._goto("money"), "Казна"))
        if self.fit_due(today):
            last = self.fit_last_date()
            out.append(("info", "Пора сдать нормативы по физподготовке" + (f": последняя проверка {last:%d.%m}" if last
                                                                           else ": проверки ещё не было") + ".",
                        app.fit_test, "Сдать"))
        return out

    def protocol_of_day(self, d):
        ps = self.protocols()
        return ps[d.toordinal() % len(ps)] if ps else None

    def protocols(self, kind=None):
        ps = [p for p in self.s["protocols"] if p.get("on", True)]
        if kind is None:
            return ps
        return [p for p in ps if kind in (p.get("urges") or [])]

    # --- боевые листы ---
    def checklists(self, d=None, when=None):
        out = []
        for c in self.s["checklists"]:
            if not c.get("on", True) or not c.get("items"):
                continue
            if d is not None and d.weekday() not in (c.get("days") or range(7)):
                continue
            if when is not None and c.get("when") != when:
                continue
            out.append(c)
        return out

    def checklist(self, cid):
        return next((c for c in self.s["checklists"] if c.get("id") == cid), None)

    def check_state(self, d, cid):
        run = (self.s["check_runs"].get(d.isoformat()) or {}).get(cid) or []
        return {i for i in run if isinstance(i, int)}

    def check_set(self, d, cid, i, on):
        runs = self.s["check_runs"]
        day = runs.setdefault(d.isoformat(), {})
        cur = set(day.get(cid) or [])
        if on:
            cur.add(int(i))
        else:
            cur.discard(int(i))
        day[cid] = sorted(cur)
        if len(runs) > 400:
            for k in sorted(runs)[:-400]:
                runs.pop(k, None)
        self.invalidate()

    def check_done(self, d, c):
        n = len(c.get("items") or [])
        return n > 0 and len(self.check_state(d, c["id"]) & set(range(n))) >= n

    def checks_day(self, d):
        """(закрыто листов, листов на день, отмечено пунктов, пунктов) — по листам, положенным на день d."""
        lists = self.checklists(d)
        done_l = items = marked = 0
        for c in lists:
            n = len(c["items"])
            m = len(self.check_state(d, c["id"]) & set(range(n)))
            items += n
            marked += m
            done_l += 1 if m >= n else 0
        return done_l, len(lists), marked, items

    def checks_streak(self, cid, today):
        c = self.checklist(cid)
        if c is None:
            return 0
        d = today if self.check_done(today, c) else today - timedelta(days=1)
        n = 0
        for _ in range(400):
            if d.weekday() not in (c.get("days") or range(7)):
                d -= timedelta(days=1)
                continue
            if not self.check_done(d, c):
                break
            n += 1
            d -= timedelta(days=1)
        return n

    # --- физподготовка ---
    def fit(self):
        return self.s["fitness"]

    def norms(self, all_=False):
        return [n for n in self.fit()["norms"] if all_ or n.get("on", True)]

    def norm(self, nid):
        return next((n for n in self.fit()["norms"] if n.get("id") == nid), None)

    def norm_by_name(self, query):
        q = (query or "").strip().lower()
        if not q:
            return None
        ns = self.norms(True)
        return (next((n for n in ns if n["name"].lower() == q), None)
                or next((n for n in ns if n["name"].lower().startswith(q)), None)
                or next((n for n in ns if q in n["name"].lower()), None))

    def fit_tests(self, nid):
        return sorted((t for t in self.fit()["tests"] if t.get("norm") == nid), key=lambda t: (t["date"], t.get("ts", "")))

    def fit_last(self, n):
        tests = self.fit_tests(n["id"])
        return tests[-1] if tests else None

    def fit_best(self, n):
        tests = self.fit_tests(n["id"])
        if not tests:
            return None
        if n.get("better") == "less":
            return min(tests, key=lambda t: t["value"])
        if n.get("better") == "more":
            return max(tests, key=lambda t: t["value"])
        return tests[-1]

    def fit_add(self, nid, d, value, note=""):
        t = {"id": _sid(), "norm": nid, "date": d.isoformat(), "value": value, "note": (note or "")[:200],
             "ts": PLATFORM["now"]().isoformat(timespec="seconds")}
        self.fit()["tests"].append(t)
        self.invalidate()
        return t

    def fit_last_date(self):
        dates = [sys_date(t.get("date")) for t in self.fit()["tests"]]
        dates = [d for d in dates if d]
        return max(dates) if dates else None

    def fit_due(self, today):
        every = int(self.fit().get("every") or 0)
        if not every or not self.norms():
            return False
        last = self.fit_last_date()
        return last is None or (today - last).days >= every

    def fit_summary(self):
        """Оценки по последним замерам: [(норматив, последний замер, оценка 0–3)] и средняя оценка."""
        rows, levels = [], []
        for n in self.norms():
            last = self.fit_last(n)
            g = fit_grade(n, last["value"]) if last else None
            rows.append((n, last, g))
            if g is not None:
                levels.append(g)
        return rows, (sum(levels) / len(levels) if levels else None)

    # --- казна ---
    def money(self):
        return self.s["money"]

    def money_cur(self):
        return self.money().get("currency") or "₽"

    def money_cats(self):
        return [c["name"] for c in self.money()["cats"]]

    def money_cat(self, query):
        q = (query or "").strip().lower()
        if not q:
            return None
        cats = self.money_cats()
        return (next((c for c in cats if c.lower() == q), None) or next((c for c in cats if c.lower().startswith(q)), None)
                or next((c for c in cats if q in c.lower()), None))

    def money_add(self, d, amount, cat, note="", impulse=False, kind="out", source=None):
        e = {"id": _sid(), "date": d.isoformat(), "sum": round(float(amount), 2), "cat": cat or "Прочее",
             "note": (note or "")[:200], "impulse": bool(impulse), "kind": kind,
             "ts": PLATFORM["now"]().isoformat(timespec="seconds")}
        if source:
            e["src"] = source
        m = self.money()
        m["entries"].append(e)
        if not m.get("since") or e["date"] < m["since"]:
            m["since"] = e["date"]
        self.invalidate()
        return e

    def money_entries(self, a, b, kind="out"):
        ai, bi = a.isoformat(), b.isoformat()
        return [e for e in self.money()["entries"] if ai <= e["date"] <= bi and (kind is None or e.get("kind") == kind)]

    def money_spent(self, a, b, cat=None):
        return sum(e["sum"] for e in self.money_entries(a, b) if cat is None or e.get("cat") == cat)

    def money_by_cat(self, a, b):
        acc = defaultdict(float)
        for e in self.money_entries(a, b):
            acc[e.get("cat") or "Прочее"] += e["sum"]
        return acc

    def money_since(self):
        return sys_date(self.money().get("since"))

    def nospend_days(self, a, b):
        since = self.money_since()
        if since is None:
            return 0
        spent = {e["date"] for e in self.money_entries(max(a, since), b)}
        return sum(1 for d in self.dates(max(a, since), b) if d.isoformat() not in spent)

    def nospend_streak(self, today):
        since = self.money_since()
        if since is None:
            return 0
        spent = {e["date"] for e in self.money()["entries"] if e.get("kind") == "out"}
        d = today if today.isoformat() not in spent else None
        if d is None:
            return 0
        n = 0
        while d >= since and d.isoformat() not in spent:
            n += 1
            d -= timedelta(days=1)
        return n

    def money_month(self, today):
        a, b = month_bounds(today)
        m = self.money()
        spent = self.money_spent(a, min(b, today))
        limit = float(m.get("month_limit") or 0) or sum(c["limit"] for c in m["cats"])
        days_left = (b - today).days + 1
        spent_today = self.money_spent(today, today)
        left = limit - spent if limit else None
        per_day = math.floor((limit - (spent - spent_today)) / days_left) if limit else None
        imp = [e for e in self.money_entries(a, b) if e.get("impulse")]
        by_cat = self.money_by_cat(a, b)
        cats = [(c["name"], by_cat.get(c["name"], 0.0), c["limit"]) for c in m["cats"]]
        extra = [(k, v, 0.0) for k, v in by_cat.items() if k not in {c["name"] for c in m["cats"]}]
        return {"a": a, "b": b, "spent": spent, "limit": limit, "left": left, "per_day": per_day,
                "days_left": days_left, "today": spent_today, "impulse_n": len(imp),
                "impulse_sum": sum(e["sum"] for e in imp), "cats": cats + extra,
                "income": sum(e["sum"] for e in self.money_entries(a, b, "in")),
                "nospend": self.nospend_days(a, min(b, today)),
                "pace": (spent / limit) / (((today - a).days + 1) / ((b - a).days + 1)) if limit else None}

    def wish_ready(self, w, now=None):
        now = now or PLATFORM["now"]()
        try:
            added = datetime.fromisoformat(w.get("added") or "")
        except ValueError:
            return True
        return now >= added + timedelta(hours=int(self.money().get("cooldown") or 0))

    def money_saved(self):
        return sum(float(w.get("price") or 0) for w in self.money()["wishes"] if w.get("status") == "dropped")

    # --- короткие тексты для телефона, донесений и пакета для Claude ---
    def pvo_text(self, today):
        d0 = self.urge_stats(today, today)
        w7 = self.urge_stats(today - timedelta(days=6), today)
        lines = [f"ПВО: сегодня {d0['n']} {plural(d0['n'], ('перехват', 'перехвата', 'перехватов'))} "
                 f"(устоял {d0['held']}, сорвался {d0['fell']}), без срыва {days_word(self.urge_clean_days(today))}",
                 f"За 7 дней: {w7['n']}, удержание " + (f"{int(round(w7['rate'] * 100))}%" if w7["rate"] is not None
                                                        else "—")]
        if w7["kinds"]:
            lines.append("Чаще всего: " + ", ".join(f"{k} {v[0]}" for k, v in w7["kinds"][:3]))
        opened = self.urge_open()
        if opened:
            lines.append("Без итога: " + ", ".join(u.get("what", "") for u in opened[-3:]) + " — «устоял» или «сорвался»")
        return "\n".join(lines)

    def money_text(self, today):
        cur = self.money_cur()
        mm = self.money_month(today)
        lines = [f"Казна, {MONTHS_NOM[today.month - 1].lower()}: потрачено {fmt_money(mm['spent'], cur)}"
                 + (f" из {fmt_money(mm['limit'], cur)}" if mm["limit"] else "")]
        if mm["limit"]:
            lines.append(f"Можно в день до конца месяца: {fmt_money(max(0, int(mm['per_day'])), cur)}; сегодня "
                         f"{fmt_money(mm['today'], cur)}")
        lines.append(f"Без трат подряд: {days_word(self.nospend_streak(today))}; импульсных за месяц {mm['impulse_n']} "
                     f"на {fmt_money(mm['impulse_sum'], cur)}")
        top = sorted((x for x in mm["cats"] if x[1]), key=lambda x: -x[1])[:4]
        if top:
            lines.append("Больше всего: " + ", ".join(f"{n} {fmt_money(v, cur)}" for n, v, _l in top))
        return "\n".join(lines)

    def fit_text(self, today):
        rows, avg = self.fit_summary()
        last = self.fit_last_date()
        lines = ["Физподготовка: " + (f"оценка «{FIT_GRADES[int(round(avg))]}» ({fmt_num(avg)} из 3)" if avg is not None
                                      else "оценки пока нет")
                 + (f", последняя проверка {last:%d.%m}" if last else "")]
        for n, lt, g in rows:
            if lt:
                lines.append(f"  {n['name']}: {fmt_fit_value(n['kind'], lt['value'])}"
                             + (f" — {FIT_GRADES[g]}" if g is not None else ""))
        if self.fit_due(today):
            lines.append("Пора сдать нормативы: «норматив подтягивания 12», «вес 73,5».")
        return "\n".join(lines)

    def dossier_text(self, today):
        r = self.rank(today)
        got = [x.get("title") for x in self.s["rewards"] if x.get("got")]
        lines = [f"Личное дело: {r['name']}, опыт {r['xp']}" + (f" (выслуга {r['carry']})" if r["carry"] else ""),
                 f"Кампаний в послужном списке: {len(self.s.get('campaigns') or [])}; текущая — {self.name()}",
                 "Награды: " + (", ".join(got) if got else "пока нет")]
        if r["next"]:
            lines.append(f"До звания «{r['next']}»: {r['hi'] - r['xp']} очков")
        return "\n".join(lines)

    # --- сигналы: напоминания на время ---
    def signals(self, pending=True):
        out = [x for x in self.s["signals"] if not pending or not x.get("done")]
        return sorted(out, key=lambda x: x["at"])

    def signal_add(self, at, text, repeat=None, source=None):
        x = {"id": _sid(), "at": at.isoformat(timespec="minutes"), "text": text.strip()[:200], "repeat": repeat,
             "done": False}
        if source:
            x["src"] = source
        self.s["signals"].append(x)
        self.invalidate()
        return x

    def signal_fire(self, x, now=None):
        """Сигнал прозвучал: разовый — закрыт, повторяющийся — переносится на следующий раз."""
        now = now or PLATFORM["now"]()
        if x.get("repeat"):
            at = parse_dt(x["at"]) or now
            while at <= now:
                at = next_signal(at, x["repeat"])
            x["at"] = at.isoformat(timespec="minutes")
        else:
            x["done"] = True
        done = [s for s in self.s["signals"] if s.get("done")]
        if len(done) > 100:
            drop = {s["id"] for s in done[:-100]}
            self.s["signals"] = [s for s in self.s["signals"] if s["id"] not in drop]
        self.invalidate()

    def signals_due(self, now=None):
        now = now or PLATFORM["now"]()
        return [x for x in self.signals() if (parse_dt(x["at"]) or now) <= now]

    # --- опыт за дисциплину вне часов ---
    def kit_xp(self, a, b):
        """Перехват выдержан — 5 (до 5 в день), лист закрыт — 5, день с замерами физподготовки — 20."""
        held = defaultdict(int)
        for u in self.urges():
            d = self.urge_day(u)
            if d and a <= d <= b and u.get("result") == "held":
                held[d] += 1
        xp = sum(min(5, n) for n in held.values()) * 5
        for k, run in self.s["check_runs"].items():
            d = sys_date(k)
            if not d or not a <= d <= b:
                continue
            for cid in run:
                c = self.checklist(cid)
                if c is not None and self.check_done(d, c):
                    xp += 5
        fit_days = {t["date"] for t in self.fit()["tests"] if a.isoformat() <= t["date"] <= b.isoformat()}
        return xp + 20 * len(fit_days)

    # --- послужной список и смена кампании ---
    def campaign_summary(self, today):
        a, b = self.start(), self.end()
        upto = min(today, b)
        r = self.rank(today)
        pens = self.penalties(today)
        days = [d for d in self.dates(a, upto)]
        return {"name": self.name(), "start": a.isoformat(), "end": b.isoformat(),
                "goal_hours": self.goal("hours", 0), "hours": round(self.hours_total(), 1),
                "plan_hours": round(self.plan_between(a, upto), 1), "days": len(days),
                "good_days": self.good_days(today), "checkins": self.checkins_between(a, upto) if days else 0,
                "trainings": self.trainings_between(a, upto) if days else 0,
                "xp": r["xp"], "gross": r["gross"], "rank": r["name"], "penalty": sum(p for _d, p, _t in pens),
                "reserve_used": len(self.reserve_cfg()["used"]),
                "duties_done": sum(1 for x in self.duties() if x.get("status") == "done"),
                "duties_failed": sum(1 for x in self.duties() if x.get("status") == "failed"),
                "best_streak": self.best_streak(self.good_day, a, upto),
                "review": dict(self.s.get("final_review") or {}), "closed": today.isoformat()}

    def best_streak(self, pred, a, b):
        best = run = 0
        for d in self.dates(a, b):
            if pred(d):
                run += 1
                best = max(best, run)
            else:
                run = 0
        return best

    def schedule_campaign(self, **plan):
        """Следующая кампания начнётся сама, когда кончится текущая (или в день своего старта)."""
        self.s["next_campaign"] = {k: (v.isoformat() if isinstance(v, date) else v) for k, v in plan.items()}
        self.journal_add("campaign", f"запланирована кампания «{plan.get('name')}» с {plan['start']:%d.%m.%Y}")
        self.invalidate()

    def maybe_switch(self, today):
        """Пора развернуть запланированную кампанию? True — развернули."""
        nxt = self.s.get("next_campaign") or {}
        st, en = sys_date(nxt.get("start")), sys_date(nxt.get("end"))
        if not st or not en or (today <= self.end() and today < st):
            return False
        try:
            self.app.store.backup_now(f"data-before-campaign-{today:%Y%m%d}.json")
        except OSError:
            pass
        self.s["next_campaign"] = {}
        self.start_campaign(today, nxt.get("name") or CAMPAIGN, st, en, float(nxt.get("hours") or 0),
                            int(nxt.get("reserve") or 0), carry_xp=bool(nxt.get("carry_xp", True)),
                            phase=nxt.get("phase") or "Развёртывание", focus=nxt.get("focus") or "",
                            reset_rules_text=bool(nxt.get("reset_rules_text")))
        return True

    def start_campaign(self, today, name, start, end, hours, reserve, carry_xp=True, phase="Развёртывание",
                       focus="", reset_rules_text=False):
        """Итоги текущей кампании — в послужной список, опыт — в выслугу, дальше новая кампания с теми же
        направлениями, режимами дня, расписанием, курсами и привычками."""
        summary = self.campaign_summary(today)
        self.s["campaigns"].append(summary)
        if carry_xp:
            # выслуга — весь опыт на момент смены кампании (с прошлой выслугой и за вычетом штрафов)
            self.s["xp_carry"] = max(0, int(summary["xp"]))
        cur = self.phase_at(min(max(today, self.start()), self.end()))
        idx = cur["i"] if cur else 0
        for k, vals in list(self.s["budgets"].items()):
            vals = list(vals or [])
            self.s["budgets"][k] = [vals[idx] if idx < len(vals) else 0]
        self.s["phases"] = [{"name": phase or "Развёртывание", "start": start.isoformat(), "focus": focus or ""}]
        for duty in self.duties_open():
            duty["status"] = "cancelled"
            duty["closed"] = today.isoformat()
            duty["note"] = "смена кампании"
        self.s.update(name=name, start=start.isoformat(), end=end.isoformat(), final_review={}, rank_seen=-1,
                      alarms={}, backplan_asked={})
        self.s["goals"]["hours"] = hours
        self.s["reserve"] = {"base": int(reserve), "used": {}}
        if reset_rules_text:
            self.s["rules_text"] = ""
        self.journal_add("campaign", f"новая кампания «{name}»: {start:%d.%m.%Y}–{end:%d.%m.%Y}, цель {fmt_h(hours)} ч; "
                                     f"итоги «{summary['name']}» — в послужном списке")
        self.invalidate()
        return summary


class System(CampaignMixin, KitMixin):
    """Кампания поверх данных Генштаба: цели, этапы, бюджеты, дневник, рубежи, сеть, дисциплина."""

    def __init__(self, app):
        self.app = app
        self._key = None
        self._cache = None
        self._gen = 0

    @property
    def s(self):
        return self.app.store.data["system"]

    def invalidate(self):
        self._gen += 1

    # --- период ---
    def start(self):
        return sys_date(self.s.get("start")) or date.fromisoformat(CAMPAIGN_START)

    def end(self):
        return max(sys_date(self.s.get("end")) or date.fromisoformat(CAMPAIGN_END), self.start())

    def total_days(self):
        return (self.end() - self.start()).days + 1

    def active(self, d):
        return self.start() <= d <= self.end()

    def day_no(self, today):
        if today < self.start():
            return 0
        return min(self.total_days(), (today - self.start()).days + 1)

    def days_to_finish(self, today):
        """Сколько дней осталось, считая сегодняшний."""
        if today > self.end():
            return 0
        return (self.end() - max(today, self.start())).days + 1

    def goal(self, key, default=0.0):
        try:
            return float(self.s["goals"].get(key, default))
        except (TypeError, ValueError):
            return float(default)

    @staticmethod
    def dates(a, b):
        d = a
        while d <= b:
            yield d
            d += timedelta(days=1)

    # --- дни и их типы ---
    def day(self, d):
        return self.s["days"].get(d.isoformat()) or {}

    def day_update(self, d, **fields):
        rec = dict(self.day(d))
        rec.update(fields)
        self.s["days"][d.isoformat()] = rec

    def type_names(self):
        return [t.get("name", "") for t in self.s["day_types"]]

    def day_type(self, d):
        names = self.type_names()
        t = self.day(d).get("type")
        if t in names:
            return t
        t = self.s["weekday_types"][d.weekday()]
        return t if t in names else (names[0] if names else "")

    def type_hours(self, name):
        for t in self.s["day_types"]:
            if t.get("name") == name:
                try:
                    return max(0.0, float(t.get("hours", 0)))
                except (TypeError, ValueError):
                    return 0.0
        return 0.0

    def day_plan(self, d):
        """Норма дня: часы режима + наряды и перенесённое на этот день − перенесённое с него. Резерв — 0."""
        if not self.active(d) or self.is_reserve(d):
            return 0.0
        return max(0.0, self.base_plan(d) + self.extra_hours(d) - self.moved_hours(d))

    def day_met(self, d):
        """День выполнен: часы дошли до 97% плана (выходной по плану выполнен всегда)."""
        plan = self.day_plan(d)
        return plan <= 0 or self.hours_on(d) >= plan * self.rule("met_share") / 100 - 1e-9

    def plan_between(self, a, b):
        a, b = max(a, self.start()), min(b, self.end())
        return sum(self.day_plan(d) for d in self.dates(a, b)) if b >= a else 0.0

    # --- часы из сессий ---
    def counts(self, project):
        return (project or "") not in set(self.s.get("no_count") or [])

    def _hours(self):
        sessions = self.app.store.sessions
        key = (len(sessions), sessions[-1].get("id") if sessions else None, self.s.get("start"), self.s.get("end"),
               tuple(self.s.get("no_count") or ()), self._gen)
        if key != self._key:
            a, b = self.start().isoformat(), self.end().isoformat()
            skip = set(self.s.get("no_count") or [])
            by_day, by_dp = defaultdict(float), defaultdict(float)
            for x in sessions:
                day = x.get("day", "")
                p = x.get("project") or ""
                if not (a <= day <= b) or p in skip:
                    continue
                try:
                    h = float(x.get("minutes", 0) or 0) / 60
                except (TypeError, ValueError):
                    continue
                by_day[day] += h
                by_dp[(day, p)] += h
            self._cache = (by_day, by_dp)
            self._key = key
        return self._cache

    def hours_on(self, d):
        return self._hours()[0].get(d.isoformat(), 0.0)

    def hours_between(self, a, b):
        ai, bi = a.isoformat(), b.isoformat()
        return sum(v for k, v in self._hours()[0].items() if ai <= k <= bi)

    def hours_total(self):
        return sum(self._hours()[0].values())

    def hours_by_project(self, a=None, b=None):
        ai = a.isoformat() if a else ""
        bi = b.isoformat() if b else "9999"
        acc = defaultdict(float)
        for (day, p), v in self._hours()[1].items():
            if ai <= day <= bi:
                acc[p] += v
        return acc

    # --- фазы и бюджеты ---
    def phases(self):
        raw = sorted((p for p in self.s["phases"] if sys_date(p.get("start"))), key=lambda p: p["start"])
        out = []
        for i, p in enumerate(raw):
            st = sys_date(p["start"])
            en = sys_date(raw[i + 1]["start"]) - timedelta(days=1) if i + 1 < len(raw) else self.end()
            out.append({"i": i, "name": p.get("name", ""), "focus": p.get("focus", ""), "start": st, "end": en,
                        "raw": p})
        return out

    def reorder_phases(self):
        """Держит фазы по дате начала, а бюджеты — в том же порядке."""
        raw = self.s["phases"]
        n = len(raw)
        order = sorted(range(n), key=lambda i: raw[i].get("start") or "")
        for k, vals in list(self.s["budgets"].items()):
            vals = list(vals or []) + [0] * max(0, n - len(vals or []))
            self.s["budgets"][k] = [vals[i] for i in order]
        self.s["phases"] = [raw[i] for i in order]
        self.invalidate()

    def phase_at(self, d):
        cur = None
        for p in self.phases():
            if p["start"] <= d or cur is None:
                cur = p
        return cur

    def budget(self, project):
        n = len(self.phases())
        vals = []
        for v in list(self.s["budgets"].get(project) or []):
            try:
                vals.append(max(0.0, float(v or 0)))
            except (TypeError, ValueError):
                vals.append(0.0)
        return (vals + [0.0] * n)[:n]

    def budget_between(self, project, a, b):
        a, b = max(a, self.start()), min(b, self.end())
        if b < a:
            return 0.0
        vals = self.budget(project)
        total = 0.0
        for p in self.phases():
            lo, hi = max(a, p["start"]), min(b, p["end"])
            if hi >= lo:
                total += vals[p["i"]] * ((hi - lo).days + 1) / 7
        return total

    def directions(self):
        """Направления в порядке проектов: те, у которых есть бюджет или часы в периоде."""
        hours = self.hours_by_project()
        names = []
        for p in list(self.app.store.projects) + list(hours):
            if p in names or not self.counts(p):
                continue
            if any(self.budget(p)) or hours.get(p):
                names.append(p)
        return names

    def behind(self, today):
        """Где отстаю от бюджета текущей недели: [(разрыв, проект, бюджет, факт)]."""
        if not self.active(today):
            return []
        monday = max(week_monday(today), self.start())
        fact = self.hours_by_project(monday, today)
        out = []
        for p in self.directions():
            if not p:
                continue
            b = self.budget_between(p, monday, today)
            if b <= 0:
                continue
            gap = b - fact.get(p, 0.0)
            if gap >= 0.5:
                out.append((gap, p, b, fact.get(p, 0.0)))
        out.sort(reverse=True)
        return out

    # --- сеть ---
    def quota(self):
        """Квота касаний (цель 500) включена: касания в индексе дня, плане недели и напоминаниях."""
        return bool((self.s.get("net") or {}).get("quota", True))

    def touches(self):
        for c in self.s["contacts"]:
            for t in c.get("touches") or []:
                d = sys_date(t.get("date"))
                if d and t.get("kind") != "Заметка":
                    yield d, c, t

    def _touch_index(self):
        """{дата: (касаний, созвонов)} с кэшем: боеготовность считает касания для каждого дня периода."""
        contacts = self.s["contacts"]
        key = (self._gen, len(contacts), sum(len(c.get("touches") or ()) for c in contacts))
        if getattr(self, "_tkey", None) != key:
            idx = defaultdict(lambda: [0, 0])
            for d, _c, t in self.touches():
                rec = idx[d]
                rec[0] += 1
                if t.get("kind") in SYS_CALL_KINDS:
                    rec[1] += 1
            self._tidx = dict(idx)
            self._tkey = key
        return self._tidx

    def touches_between(self, a, b, calls=False):
        i = 1 if calls else 0
        if a == b:
            rec = self._touch_index().get(a)
            return rec[i] if rec else 0
        return sum(v[i] for d, v in self._touch_index().items() if a <= d <= b)

    def touches_total(self, calls=False):
        return self.touches_between(self.start(), self.end(), calls)

    def touch_target(self, monday):
        if not self.quota():
            return 0
        try:
            return int(self.s["touch_plan"].get(monday.isoformat(), 0) or 0)
        except (TypeError, ValueError):
            return 0

    def touch_target_until(self, today):
        total = 0
        for k, v in self.s["touch_plan"].items():
            d = sys_date(k)
            if d and d <= today:
                try:
                    total += int(v or 0)
                except (TypeError, ValueError):
                    pass
        return total

    def followups(self, today):
        ti = today.isoformat()
        return [c for c in self.s["contacts"]
                if c.get("next_date") and c["next_date"] <= ti and c.get("status") not in SYS_CLOSED]

    # --- здоровье ---
    def trained(self, d):
        return self.day(d).get("train") in self.train_counted()

    def trainings_between(self, a, b):
        return sum(1 for d in self.dates(max(a, self.start()), min(b, self.end())) if self.trained(d))

    def sleep_values(self, a, b):
        out = []
        for d in self.dates(a, b):
            v = self.day(d).get("sleep")
            if v is not None:
                try:
                    out.append(float(v))
                except (TypeError, ValueError):
                    pass
        return out

    def food_score(self, d):
        rec = self.day(d)
        food = rec.get("food")
        if not rec.get("done") or not isinstance(food, list):
            return None
        return sum(1 for x in food[:len(self.food_rules())] if x)

    def food_values(self, a, b):
        return [v for v in (self.food_score(d) for d in self.dates(a, b)) if v is not None]

    def checkins_between(self, a, b):
        return sum(1 for d in self.dates(a, b) if self.day(d).get("done"))

    def log_sleep(self, d):
        """Сон из хронометража: отрезки категории «Сон», закончившиеся утром этого дня."""
        total, wake = 0.0, None
        for e in self.app.store.data.get("log", []):
            if e.get("category") != "Сон":
                continue
            try:
                en = datetime.fromisoformat(e["end"])
            except (KeyError, TypeError, ValueError):
                continue
            if en.date() == d and en.hour < 15:
                total += float(e.get("minutes", 0) or 0)
                if wake is None or en > wake:
                    wake = en
        return (round(total / 60, 1) if total else None), (wake.strftime("%H:%M") if wake else None)

    def log_minutes(self, d, category):
        di = d.isoformat()
        return sum(float(e.get("minutes", 0) or 0) for e in self.app.store.data.get("log", [])
                   if e.get("day") == di and e.get("category") == category)

    # --- привычки, которые закрываются сами ---
    def sync_habits(self, d):
        if not self.active(d):
            return
        store = self.app.store
        rec = self.day(d)
        vals = {}
        if rec.get("done"):
            vals["train"] = self.trained(d)
            sl = rec.get("sleep")
            vals["sleep"] = sl is not None and float(sl) >= self.goal("sleep", 7.5) - 1e-9
            food = self.food_score(d)
            vals["food"] = food is not None and food >= self.goal("food", 4)
        vals["hours"] = self.day_met(d)
        vals["wake"] = self.wake_ok(d)
        iso = d.isoformat()
        for h in store.habits:
            key = h.get("auto")
            if key not in vals:
                continue
            log = store.habit_log.setdefault(h["id"], {})
            if vals[key]:
                log[iso] = int(h.get("target") or 1)
            else:
                log.pop(iso, None)

    def wake_ok(self, d):
        wake, goal = parse_hm(self.day(d).get("wake")), parse_hm(self.s["goals"].get("wake"), (7, 0))
        if not wake or not goal:
            return False
        return (wake[0] * 60 + wake[1]) - (goal[0] * 60 + goal[1]) <= self.rule("wake_slack")

    # --- оценки ---
    def course_for_project(self, project):
        return next((c for c in self.s["courses"] if c.get("project") == project), None)

    # --- календарь: события, контрольные точки, элементы оценок, пересдачи, дедлайны проектов ---
    def calendar(self):
        rows = []
        for e in self.s["events"]:
            rows.append({"iid": f"ev:{e['id']}", "date": sys_date(e.get("date")), "when": e.get("when") or "",
                         "title": e.get("title", ""), "src": e.get("cat") or "Система",
                         "done": e.get("status") == "Сделано", "status": e.get("status") or ""})
        for c in self.s["courses"]:
            for comp in c.get("components") or []:
                d = sys_date(comp.get("date"))
                try:
                    w = float(comp.get("weight") or 0)
                except (TypeError, ValueError):
                    w = 0.0
                if not d and w < 15:
                    continue
                done = comp.get("score") is not None
                rows.append({"iid": f"cmp:{c['id']}:{comp['id']}", "date": d, "weight": w,
                             "project": c.get("project") or "",
                             "when": comp.get("when") or ("" if d else "уточнить"),
                             "title": f"{c['name']}: {comp['name']} ({fmt_num(w, 0 if w == int(w) else 2)}%)",
                             "src": "Оценки", "done": done, "status": "Сдано" if done else
                             ("Запланировано" if d else "Уточнить")})
        for r in self.s["retakes"]:
            d = sys_date(r.get("date"))
            done = r.get("status") != "Ожидает"
            rows.append({"iid": f"rt:{r['id']}", "date": d, "project": "Пересдачи ТВ/МС", "weight": 100,
                         "when": "" if d else "уточнить",
                         "title": f"Пересдача: {r.get('name', '')}", "src": "Пересдачи", "done": done,
                         "status": r.get("status") or ""})
        for s in self.s["skills"]:
            for cp in s.get("checkpoints") or []:
                d = sys_date(cp.get("date"))
                rows.append({"iid": f"cp:{s['id']}:{cp['id']}", "date": d, "when": "",
                             "title": f"{s['name']}: {cp.get('text', '')}", "src": "Навыки",
                             "done": bool(cp.get("done")), "status": "Сделано" if cp.get("done") else "Запланировано"})
        net = self.s.get("net") or {}
        names = {c.get("id"): c.get("name", "") for c in self.s["contacts"]}
        for o in net.get("opportunities") or []:
            d = sys_date(o.get("deadline"))
            closed = o.get("stage") in OPP_CLOSED
            if d or not closed:
                rows.append({"iid": f"op:{o['id']}", "date": d, "when": "" if d else "уточнить",
                             "title": f"{o.get('title', '')}" + (f", {o['org']}" if o.get("org") else "")
                                      + f" ({OPP_STAGES.get(o.get('stage'), '')})",
                             "src": "Возможности", "done": closed or o.get("stage") in ("applied", "offer"),
                             "status": OPP_STAGES.get(o.get("stage"), "")})
            for t in o.get("tasks") or []:
                td = sys_date(t.get("due"))
                if td:
                    rows.append({"iid": f"ot:{o['id']}:{t['id']}", "date": td, "when": "",
                                 "title": f"{t.get('title', '')} ({o.get('title', '')})", "src": "Возможности",
                                 "done": bool(t.get("done")) or closed,
                                 "status": "Сделано" if t.get("done") else "Запланировано"})
        for m in net.get("commitments") or []:
            md = sys_date(m.get("due"))
            if md and m.get("who") == "me":
                rows.append({"iid": f"cm:{m['id']}", "date": md, "when": "",
                             "title": f"Обещал: {m.get('text', '')}" + (f" — {names[m['contact']]}"
                                                                         if names.get(m.get("contact")) else ""),
                             "src": "Сеть", "done": bool(m.get("done")),
                             "status": "Сделано" if m.get("done") else "Запланировано"})
        for name, meta in (self.app.store.data.get("projects_meta") or {}).items():
            d = sys_date((meta or {}).get("deadline"))
            if d and not (meta or {}).get("archived"):
                rows.append({"iid": f"pr:{name}", "date": d, "when": "", "title": f"Дедлайн проекта: {name}",
                             "src": "Проекты", "done": False, "status": "Запланировано"})
        return rows

    # --- сигналы для «Обзора» ---
    def alerts(self, today):
        app = self.app
        out = []
        start, end = self.start(), self.end()
        if today < start:
            out.append(("info", f"Старт кампании {start:%d.%m}. До него — разобрать силлабусы, вписать даты рубежей "
                                f"и прочитать Устав.", lambda: app.views["system"].set_tab("plan"), "Устав"))
            return out
        nxt = self.s.get("next_campaign") or {}
        if today > end:
            out.append(("bad", f"{self.name()} завершена. Итоговый разбор — в послужной список, опыт — в выслугу, "
                               "и новая кампания: без неё нет нормы, нарядов и приказа.",
                        app.new_campaign, "Новая кампания"))
            return out
        if self.days_to_finish(today) <= 7 and not nxt:
            out.append(("warn", f"До финиша {days_word(self.days_to_finish(today))}. Итоговый разбор и план следующей "
                                "кампании — заранее, чтобы первого дня не было пустым.", app.new_campaign, "Спланировать"))
        y = today - timedelta(days=1)
        opened = self.duties_open()
        if len(opened) >= self.rule("duty_cap"):
            out.append(("bad", f"Нарядов открыто {len(opened)} — потолок. Не дави сильнее: объяви оборону или "
                               "резерв и пересобери нагрузку в «Уставе».", lambda: app.views["system"].set_tab("duty"),
                        "Наряды"))
        elif opened:
            out.append(("warn", f"Наряды вне очереди: {len(opened)} — " + "; ".join(x.get("title", "") for x in opened),
                        lambda: app.views["system"].set_tab("duty"), "Наряды"))
        rec_t = self.day(today)
        now = PLATFORM["now"]()
        if not rec_t.get("morning") and not self.is_reserve(today) and self.day_plan(today) > 0 \
                and now >= at_time(today, "10:00"):
            out.append(("warn", "Построения не было: главный удар не назначен, норма не принята.",
                        lambda: app.coach.open_morning(), "Построение"))
        for r in self.rubezhi(today, 10):
            left = (r["date"] - today).days
            if left >= 1 and self.major(r) and not self.backplanned(r["iid"]):
                out.append(("bad" if left <= 3 else "warn", f"Рубеж через {days_word(left)}: {r['title']} — "
                                                            "плана подготовки нет.",
                            lambda row=r: app.do_backplan(row), "Развернуть"))
        silent = self.silent_fronts(today)
        if silent:
            out.append(("warn", "Молчат направления: " + ", ".join(f"{x['name']} {days_word(x['silent'])}"
                                                                   for x in silent[:4]) + ".",
                        lambda: app.views["system"].set_tab("fronts"), "Фронты"))
        if y >= start and not self.day(y).get("done") and not self.is_reserve(y):
            out.append(("warn", f"Вечерняя сводка за вчера ({fmt_day(y)}) не подана. Утром — наряд.",
                        lambda: app.checkin(y), "Подать"))
        if y >= start:
            plan, fact = self.plan_between(start, y), self.hours_between(start, y)
            if plan > 0 and plan - fact >= 5 and fact < plan * 0.9:
                need = max(0.0, self.goal("hours", 630) - self.hours_total()) / max(1, self.days_to_finish(today))
                out.append(("bad" if fact < plan * 0.75 else "warn",
                            f"Часы: {fmt_h(fact)} из {fmt_h(plan)} по плану к вчерашнему дню, отставание "
                            f"{fmt_h(plan - fact)} ч. До {int(self.goal('hours', 630))} нужно {fmt_h(need)} ч в день.",
                            None, None))
        d1, d2 = today - timedelta(days=1), today - timedelta(days=2)
        if d2 >= start and all(self.day_plan(d) > 0 and self.hours_on(d) < self.day_plan(d) * 0.5 for d in (d1, d2)):
            out.append(("bad", "Два дня подряд меньше половины нормы. Правило «не пропускать дважды»: "
                               "пересмотри нагрузку, объяви оборону или резерв, а не дави сильнее.", None, None))
        sleep = self.sleep_values(today - timedelta(days=7), y)
        if len(sleep) >= 3 and sum(sleep) / len(sleep) < 7:
            out.append(("warn", f"Сон за неделю в среднем {fmt_num(sum(sleep) / len(sleep))} ч. "
                                "Сдвигай отбой, а не подъём.", None, None))
        missing = []
        for c in self.s["courses"]:
            calc = course_calc(c)
            if calc["total_w"] <= 0:
                missing.append(c["name"])
                continue
            if calc["need"] is not None and calc["need"] > calc["top"] + 1e-9:
                out.append(("bad", f"{c['name']}: {calc['target']} уже недостижимо, максимум — "
                                   f"{calc['best_grade']}. Пересчитай цель.", lambda: app._goto("grades"), "Рубежи"))
            elif calc["need"] is not None and calc["need"] > calc["top"] * 0.95:
                out.append(("bad", f"{c['name']}: для {calc['target']} нужно {fmt_score(c, calc['need'])} "
                                   "на оставшемся. Первый утренний блок — ему.", lambda: app._goto("grades"), "Рубежи"))
            elif (calc["current_grade"] is not None and calc["graded_share"] >= 0.15
                  and calc["current_grade"] < self.goal("grade_min", 8)):
                out.append(("bad", f"{c['name']}: сейчас выходит {calc['current_grade']}. Первый утренний блок "
                                   f"каждый день, пока не вернётся к {fmt_h(self.goal('grade_min', 8))}.",
                            lambda: app._goto("grades"), "Рубежи"))
        if missing:
            out.append(("warn", "Нет формулы оценки: " + ", ".join(missing) + ".",
                        lambda: app._goto("grades"), "Внести"))
        waiting = [r for r in self.s["retakes"] if r.get("status") == "Ожидает" and not r.get("date")]
        if waiting:
            out.append(("warn", "Даты пересдач не вписаны: " + ", ".join(r["name"] for r in waiting) + ".",
                        lambda: app._goto("grades"), "Вписать"))
        fu = self.followups(today)
        if fu:
            names = ", ".join(c.get("name", "") for c in fu[:4]) + (
                f" и ещё {len(fu) - 4}" if len(fu) > 4 else "")
            names += "" if names.endswith(".") else "."
            out.append(("warn", f"Кому написать сегодня и просрочено: {len(fu)} — {names}",
                        lambda: app.views["network"].set_tab("today"), "Сеть"))
        net = self.s.get("net") or {}
        mine = [m for m in net.get("commitments") or [] if m.get("who") == "me" and not m.get("done")
                and sys_date(m.get("due")) and sys_date(m.get("due")) <= today]
        if mine:
            out.append(("bad", f"Обещал и не сделал: {len(mine)} — " + "; ".join(m.get("text", "") for m in mine[:2])
                        + (f" и ещё {len(mine) - 2}" if len(mine) > 2 else ""),
                        lambda: app.views["network"].set_tab("today"), "Сеть"))
        hot = [o for o in net.get("opportunities") or [] if o.get("stage") not in OPP_CLOSED
               and sys_date(o.get("deadline")) and today <= sys_date(o.get("deadline")) <= today + timedelta(days=7)]
        for o in sorted(hot, key=lambda o: o["deadline"])[:3]:
            dd = sys_date(o["deadline"])
            out.append(("bad" if (dd - today).days <= 2 else "warn",
                        f"Дедлайн {dd:%d.%m}: {o.get('title')}" + (f", {o['org']}" if o.get("org") else "")
                        + f" — {OPP_STAGES.get(o.get('stage'), '')}",
                        lambda: app.views["network"].set_tab("opps"), "Возможности"))
        monday = week_monday(today)
        target = self.touch_target(monday)
        if target and today.weekday() >= 2:
            done = self.touches_between(monday, today)
            expected = target * (today.weekday() + 1) / 7
            if done < expected * 0.6:
                out.append(("warn", f"Касания: {done} из {target} на этой неделе, к сегодня ожидалось "
                                    f"около {int(round(expected))}.", lambda: app._goto("network"), "Сеть"))
        out += self.kit_alerts(today)
        overdue = [r for r in self.calendar() if r["date"] and r["date"] < today and not r["done"]
                   and r["status"] not in ("Перенесено",)]
        if overdue:
            out.append(("warn", f"Просрочено в календаре: {len(overdue)} — "
                                + "; ".join(r["title"] for r in overdue[:2])
                                + (f" и ещё {len(overdue) - 2}" if len(overdue) > 2 else ""),
                        lambda: app.views["system"].set_tab("calendar"), "Календарь"))
        undated = [r for r in self.calendar() if not r["date"] and not r["done"]]
        if undated:
            out.append(("info", f"Без даты: {len(undated)} событий. Каждое вписанное число — меньше сюрпризов.",
                        lambda: app.views["system"].set_tab("calendar"), "Календарь"))
        return out


    # ───── 6.0: списки, расписание, боеготовность, опыт, серии, награды, обязательства, журнал ─────
    def food_rules(self):
        return [r for r in self.s.get("food_rules") or [] if r] or list(SYS_FOOD_RULES)

    def trainings(self):
        items = [t for t in self.s.get("trainings") or [] if t] or list(SYS_TRAININGS)
        return items if "Нет" in items else items + ["Нет"]

    def train_counted(self):
        return [t for t in self.s.get("train_counted") or [] if t and t != "Нет"]

    def segments(self):
        return [t for t in self.s.get("segments") or [] if t] or list(SYS_SEGMENTS)

    @property
    def coach(self):
        return self.s["coach"]

    def blocks_for(self, d):
        return list(self.s["blocks"].get(self.day_type(d)) or [])

    def block_at(self, when):
        """Блок расписания, внутри которого сейчас момент when: (блок, начало, конец) или None."""
        d = self.app.today() if isinstance(when, datetime) else when
        for b in self.blocks_for(d):
            st, en = at_time(d, b.get("start")), at_time(d, b.get("end"))
            if en <= st:
                en += timedelta(days=1)
            if st <= when < en:
                return b, st, en
        return None

    def next_block(self, when):
        d = self.app.today()
        for b in self.blocks_for(d):
            st = at_time(d, b.get("start"))
            if st > when:
                return b, st, at_time(d, b.get("end"))
        return None

    def touch_quota(self, d):
        if not self.quota():
            return 0
        monday = week_monday(d)
        days = [x for x in self.dates(max(monday, self.start()), min(monday + timedelta(days=6), self.end()))]
        target = self.touch_target(monday)
        return int(math.ceil(target / len(days))) if days and target else 0

    def train_expected(self, d):
        for h in self.app.store.habits:
            if h.get("auto") == "train":
                return d.weekday() in (h.get("days") or [])
        return d.weekday() != 6

    def day_score(self, d):
        """Боеготовность 0–100 и составляющие {ключ: (доля, пояснение)}."""
        if self.is_reserve(d):
            return 100, {"reserve": (1.0, "резерв Ставки: " + (self.reserve_reason(d) or "отдых"))}
        w = self.coach.get("weights") or {}
        rec = self.day(d)
        done = bool(rec.get("done"))
        plan, hours = self.day_plan(d), self.hours_on(d)
        parts = {"hours": (min(1.0, hours / plan) if plan > 0 else 1.0, f"часы {fmt_h(hours)} из {fmt_h(plan)}")}
        parts["checkin"] = (1.0 if done else 0.0, "сводка " + ("есть" if done else "не сделана"))
        if done:
            if self.train_expected(d):
                parts["train"] = (1.0 if self.trained(d) else 0.0, "тренировка " + (rec.get("train") or "нет").lower())
            else:
                parts["train"] = (1.0, "день без тренировки по плану")
            sl = rec.get("sleep")
            goal = self.goal("sleep", 7.5)
            parts["sleep"] = (min(1.0, float(sl) / goal) if sl and goal else 0.0, f"сон {fmt_h(sl)} ч")
            fs = self.food_score(d) or 0
            parts["food"] = (fs / max(1, len(self.food_rules())), f"питание {fs} из {len(self.food_rules())}")
        else:
            parts["train"] = (0.0, "тренировка неизвестна")
            parts["sleep"] = (0.0, "сон неизвестен")
            parts["food"] = (0.0, "питание неизвестно")
        wake, goal = parse_hm(rec.get("wake")), parse_hm(self.s["goals"].get("wake"), (7, 0))
        if wake and goal:
            late = (wake[0] * 60 + wake[1]) - (goal[0] * 60 + goal[1])
            slack = self.rule("wake_slack")
            parts["wake"] = (1.0 if late <= slack else max(0.0, 1 - (late - slack) / 60), f"подъём {rec['wake']}")
        else:
            parts["wake"] = (0.0, "подъём не отмечен")
        if plan > 0:
            mit = self.app.task_by_id(rec.get("mit_id")) if rec.get("mit_id") else None
            if mit is not None:
                hit = mit.get("status") == "done" and (mit.get("completed_day") or "9999") <= d.isoformat()
                parts["mit"] = (1.0 if hit else 0.0, "главный удар " + ("доведён" if hit else "не доведён"))
            elif rec.get("mit_text"):
                parts["mit"] = (0.5, "главный удар без задачи")
            else:
                parts["mit"] = (0.0, "главный удар не назначен")
        if self.quota():
            q = self.touch_quota(d)
            t = self.touches_between(d, d)
            parts["touches"] = (min(1.0, t / q) if q else 1.0, f"касания {t} из {q}")
        cards = self.cards_part(d)
        if cards is not None:
            parts["cards"] = cards
        since = sys_date(self.coach.get("lists_since"))
        if float(w.get("lists", 0) or 0) > 0 and since and d >= since:
            _dl, _nl, marked, items = self.checks_day(d)
            if items:
                parts["lists"] = (marked / items, f"боевые листы {marked} из {items}")
        total = sum(max(0.0, float(w.get(k, 0) or 0)) for k in parts)
        score = sum(max(0.0, float(w.get(k, 0) or 0)) * p for k, (p, _t) in parts.items())
        return (int(round(100 * score / total)) if total else 0), parts

    def cards_part(self, d):
        """Карточки в индексе дня: сегодня — сколько из положенных повторено; без карточек — не учитываются."""
        store = getattr(self.app, "notes_store", None)
        w = float((self.coach.get("weights") or {}).get("cards", 0) or 0)
        if store is None or w <= 0:
            return None
        try:
            done = store.reviews_on(d.isoformat())
            if d == self.app.today():
                left = store.due_count()
                if not done and not left:
                    return None
                total = done + left
                return (done / total if total else 1.0, f"карточки {done} из {total}")
            return (1.0, f"карточки {done}") if done else None
        except sqlite3.Error:
            return None

    def good_day(self, d):
        return self.day_score(d)[0] >= int(self.coach.get("good_score", 70) or 70)

    def streak(self, pred, today):
        d = min(today, self.end())
        if not pred(d):
            d -= timedelta(days=1)
        n = 0
        while d >= self.start() and pred(d):
            n += 1
            d -= timedelta(days=1)
        return n

    def good_days(self, today):
        return sum(1 for d in self.dates(self.start(), min(today, self.end())) if self.good_day(d))

    def xp(self, today):
        upto = min(today, self.end())
        cps = sum(1 for s in self.s["skills"] for cp in s.get("checkpoints") or [] if cp.get("done"))
        graded = sum(1 for c in self.s["courses"] for x in c.get("components") or [] if x.get("score") is not None)
        return int(self.hours_total() * 10 + self.touches_total() * 5 + self.touches_total(calls=True) * 15
                   + self.trainings_between(self.start(), upto) * 15
                   + self.checkins_between(self.start(), upto) * 10 + cps * 50 + graded * 20
                   + self.good_days(today) * 20 + self.kit_xp(self.start(), upto))

    def reward_value(self, kind, today):
        if kind == "hours":
            return self.hours_total()
        if kind == "touches":
            return self.touches_total()
        if kind == "calls":
            return self.touches_total(calls=True)
        if kind == "xp":
            return self.xp(today)
        if kind == "level":
            return xp_level(self.xp(today))[0]
        if kind == "good_days":
            return self.good_days(today)
        if kind == "good_streak":
            return self.streak(self.good_day, today)
        if kind == "checkin_streak":
            return self.streak(lambda d: bool(self.day(d).get("done")), today)
        return 0

    def promise(self, monday):
        return self.s["promises"].get(monday.isoformat()) or {}

    def journal_add(self, kind, text=""):
        self.s["journal"].append({"ts": PLATFORM["now"]().isoformat(timespec="seconds"), "kind": kind,
                                  "text": str(text)[:300]})
        del self.s["journal"][:-500]

    def journal_between(self, a, b, kind=None):
        ai, bi = a.isoformat(), (b + timedelta(days=1)).isoformat()
        return [j for j in self.s["journal"] if ai <= j.get("ts", "") < bi and (kind is None or j.get("kind") == kind)]

    def motivation(self):
        lines = [x for x in self.coach.get("motivation") or [] if x.strip()]
        why = (self.app.store.settings.get("why") or "").strip()
        if why:
            lines.append(why)
        return random.choice(lines) if lines else ""

    def sessions_on(self, d):
        di = d.isoformat()
        return [x for x in self.app.store.sessions if x.get("day") == di]

    def data_quality(self, today):
        a = max(self.start(), today - timedelta(days=7))
        b = today - timedelta(days=1)
        if b < a:
            return None
        days = (b - a).days + 1
        checked = self.checkins_between(a, b)
        total_h, with_dir, late = 0.0, 0.0, 0.0
        for x in self.app.store.sessions:
            if a.isoformat() <= x.get("day", "") <= b.isoformat():
                h = float(x.get("minutes", 0) or 0) / 60
                total_h += h
                if x.get("project"):
                    with_dir += h
                if x.get("late"):
                    late += h
        return {"days": days, "checked": checked, "dir_share": with_dir / total_h if total_h else None,
                "late": late, "skips": len(self.journal_between(a, b, "skip")),
                "snoozes": len(self.journal_between(a, b, "snooze"))}

    def insights(self, today):
        out = []
        a = max(self.start(), today - timedelta(days=27))
        b = today - timedelta(days=1)
        if b < a or (b - a).days < 2:
            return ["Инсайты появятся после трёх-четырёх дней с данными."]
        per_hour = [0.0] * 24
        first = []
        for d in self.dates(a, b):
            starts = []
            for x in self.sessions_on(d):
                if not self.counts(x.get("project")):
                    continue
                try:
                    st, en = datetime.fromisoformat(x["start"]), datetime.fromisoformat(x["end"])
                except (KeyError, TypeError, ValueError):
                    continue
                starts.append(st)
                mins = float(x.get("minutes", 0) or 0)
                span = (en - st).total_seconds()
                if span <= 0 or span > 86400 or mins <= 0:
                    continue
                cur = st
                while cur < en:
                    nxt = min(en, cur.replace(minute=0, second=0, microsecond=0) + timedelta(hours=1))
                    per_hour[cur.hour] += mins * (nxt - cur).total_seconds() / span
                    cur = nxt
            if starts and self.day_type(d) not in ("Марш", "Пары"):
                first.append(min(starts))
        total = sum(per_hour)
        if total >= 300:
            best = max(range(22), key=lambda h: sum(per_hour[h:h + 3]))
            share = sum(per_hour[best:best + 3]) / total
            out.append(f"Лучшие часы: {best:02d}:00–{best + 3:02d}:00, там {int(round(share * 100))}% твоего фокуса. "
                       "Ставь туда самое тяжёлое.")
        by_wd = defaultdict(lambda: [0.0, 0.0, 0])
        for d in self.dates(a, b):
            plan = self.day_plan(d)
            if plan > 0:
                acc = by_wd[d.weekday()]
                acc[0] += self.hours_on(d)
                acc[1] += plan
                acc[2] += 1
        rated = [(v[0] / v[1], k) for k, v in by_wd.items() if v[2] >= 2 and v[1] > 0]
        if len(rated) >= 3:
            worst = min(rated)
            out.append(f"Слабее всего {WD_FULL[worst[1]]}: {int(round(worst[0] * 100))}% плана. "
                       "Разбери в итогах недели, что мешает именно в этот день.")
        good_sleep, bad_sleep = [], []
        for d in self.dates(a, b):
            sl = self.day(d).get("sleep")
            plan = self.day_plan(d)
            if sl is None or plan <= 0:
                continue
            ratio = self.hours_on(d) / plan
            if float(sl) >= self.goal("sleep", 7.5):
                good_sleep.append(ratio)
            elif float(sl) < 7:
                bad_sleep.append(ratio)
        if len(good_sleep) >= 3 and len(bad_sleep) >= 3:
            g, bb = sum(good_sleep) / len(good_sleep), sum(bad_sleep) / len(bad_sleep)
            out.append(f"После сна от {fmt_h(self.goal('sleep', 7.5))} ч ты выполняешь {int(round(g * 100))}% плана, "
                       f"после сна меньше 7 — {int(round(bb * 100))}%.")
        if len(first) >= 3:
            avg = sum(f.hour * 60 + f.minute for f in first) / len(first)
            blocks = [x for x in self.blocks_for(today) if x.get("kind") == "study"] or \
                     [x for t in self.s["blocks"].values() for x in t if x.get("kind") == "study"]
            plan_start = parse_hm(blocks[0]["start"]) if blocks else None
            text = f"Первая сессия в среднем в {int(avg // 60):02d}:{int(avg % 60):02d}"
            if plan_start:
                late = avg - (plan_start[0] * 60 + plan_start[1])
                if late > 20:
                    text += f" — на {int(late)} мин позже плана. Утро теряется первым"
            out.append(text + ".")
        dist = [float(self.day(d).get("distract") or 0) for d in self.dates(max(a, b - timedelta(days=6)), b)]
        if dist and sum(dist) / len(dist) >= 3:
            out.append(f"Залипание: {fmt_minutes(sum(dist) / len(dist))} в день за неделю. Список сайтов — "
                       "во вкладке «Дежурный».")
        lag = []
        for p in self.directions():
            bud = self.budget_between(p, self.start(), b)
            if p and bud >= 3:
                lag.append((self.hours_by_project(self.start(), b).get(p, 0.0) / bud, p))
        if lag:
            ratio, p = min(lag)
            if ratio < 0.8:
                out.append(f"Больше всего проседает «{p}»: {int(round(ratio * 100))}% бюджета к сегодня.")
        return out or ["Пока ровно: ярких закономерностей нет."]

    def daily_report(self, d):
        score, parts = self.day_score(d)
        rec = self.day(d)
        hours = self.hours_by_project(d, d)
        top = ", ".join(f"{p or 'без направления'} {fmt_h(h)}" for p, h in
                        sorted(hours.items(), key=lambda kv: -kv[1])[:4])
        verdict = ("резерв Ставки" if self.is_reserve(d) else
                   ("засчитан" if score >= int(self.coach.get("good_score", 70) or 70) else "не засчитан"))
        lines = [f"Генштаб · сводка · {WD_SHORT[d.weekday()]}, {d:%d.%m} · день {self.day_no(d)} из {self.total_days()}",
                 f"Боеготовность: {score} — {verdict}",
                 f"Часы: {fmt_h(self.hours_on(d))} из {fmt_h(self.day_plan(d))}" + (f" ({top})" if top else ""),
                 ]
        if self.quota() or self.touches_between(d, d):
            lines.append(f"Касания: {self.touches_between(d, d)}, созвонов {self.touches_between(d, d, calls=True)}")
        store = getattr(self.app, "notes_store", None)
        if store is not None:
            try:
                n = store.reviews_on(d.isoformat())
                if n:
                    lines.append(f"Карточек повторено: {n}")
            except sqlite3.Error:
                pass
        if rec.get("done"):
            lines.append(f"Сон {fmt_h(rec.get('sleep'))} ч · {(rec.get('train') or 'без тренировки').lower()} · "
                         f"питание {self.food_score(d)} из {len(self.food_rules())}")
        notes = [x.get("note") for x in self.sessions_on(d) if x.get("note")]
        if notes:
            lines.append("Сделано: " + "; ".join(notes[:8]))
        if rec.get("mit_text"):
            mit = self.app.task_by_id(rec.get("mit_id"))
            lines.append("Главный удар: " + rec["mit_text"] + (" — доведён" if mit is not None and
                                                               mit.get("status") == "done" else ""))
        if rec.get("note"):
            lines.append("Итог: " + rec["note"])
        lines += self.kit_report_lines(d, d)
        r = self.rank(d)
        lines.append(f"Звание: {r['name']} · резерв {self.reserve_left(d)} · нарядов {len(self.duties_open())}")
        lines.append(f"Всего: {fmt_h(self.hours_total())} ч из {int(self.goal('hours', 630))}"
                     + (f", касаний {self.touches_total()} из {int(self.goal('touches', 500))}" if self.quota() else ""))
        return "\n".join(lines)

    def weekly_report(self, monday, today):
        a, b = max(monday, self.start()), min(monday + timedelta(days=6), self.end(), today)
        if b < a:
            return "Неделя ещё не началась."
        week_end = min(monday + timedelta(days=6), self.end())
        hp, hf = self.plan_between(a, week_end), self.hours_between(a, b)
        scores = [self.day_score(d)[0] for d in self.dates(a, b)]
        sl, fd = self.sleep_values(a, b), self.food_values(a, b)
        lines = [f"Генштаб · разбор недели {a:%d.%m}–{week_end:%d.%m}",
                 f"Часы: {fmt_h(hf)} из {fmt_h(hp)} по плану",
                 (f"Касания: {self.touches_between(a, b)} из {self.touch_target(monday)}, созвонов "
                  f"{self.touches_between(a, b, calls=True)}" if self.quota() else
                  f"Касания: {self.touches_between(a, b)}, созвонов {self.touches_between(a, b, calls=True)}"),
                 f"Тренировок: {self.trainings_between(a, b)} · сон {fmt_num(sum(sl) / len(sl)) if sl else '—'} ч · "
                 f"питание {fmt_num(sum(fd) / len(fd)) if fd else '—'}",
                 f"Боеготовность в среднем: {int(round(sum(scores) / len(scores))) if scores else '—'}, засчитано дней "
                 f"{sum(1 for x in scores if x >= int(self.coach.get('good_score', 70)))} из {len(scores)}"]
        pr = self.promise(monday)
        if pr:
            kept = []
            if pr.get("hours"):
                kept.append(f"часы {fmt_h(hf)} из обещанных {fmt_h(pr['hours'])}")
            if pr.get("touches"):
                kept.append(f"касания {self.touches_between(a, b)} из {pr['touches']}")
            if kept:
                lines.append("Обязательство: " + ", ".join(kept) + (f". Ставка: {pr['stake']}" if pr.get("stake") else ""))
        rev = self.s["reviews"].get(monday.isoformat()) or {}
        if rev.get("why"):
            lines.append("Почему разошлось: " + rev["why"])
        if rev.get("change"):
            lines.append("Что меняю: " + rev["change"])
        duties = [x for x in self.duties() if a.isoformat() <= (x.get("created") or "") <= b.isoformat()]
        if duties:
            lines.append(f"Нарядов за неделю: {len(duties)}, провалено "
                         f"{sum(1 for x in duties if x.get('status') == 'failed')}")
        skips = len(self.journal_between(a, b, "skip")) + len(self.journal_between(a, b, "snooze"))
        if skips:
            lines.append(f"Отговорок в журнале: {skips}")
        lines += self.kit_report_lines(a, b)
        return "\n".join(lines)

    # --- 7.0: короткие тексты для телефона и выгрузка дневника ---
    def resolve_project(self, query):
        """Направление по сокращению («эконом»), началу или части названия. None — не нашёл."""
        q = (query or "").strip().lower()
        if not q:
            return None
        projects = self.app.store.projects
        aliases = self.s.get("aliases") or {}
        hit = aliases.get(q)
        if hit in projects:
            return hit
        found = match_project(q, projects)
        if found in projects:
            return found
        for k, v in aliases.items():
            if k.startswith(q) and v in projects:
                return v
        return None

    def status_text(self, today, now=None):
        """Сводка на сейчас: день, неделя, весь период. Для Telegram-команды «статус»."""
        if not self.active(today):
            return f"Генштаб: кампания {self.start():%d.%m}–{self.end():%d.%m}, сегодня вне её."
        score, _parts = self.day_score(today)
        monday = max(week_monday(today), self.start())
        week_end = min(week_monday(today) + timedelta(days=6), self.end())
        q = self.quota()
        r = self.rank(today)
        lines = [f"Генштаб · {WD_SHORT[today.weekday()]}, {today:%d.%m} · день {self.day_no(today)} из "
                 f"{self.total_days()} · {'резерв' if self.is_reserve(today) else self.day_type(today)}",
                 f"Звание: {r['name']} · резерв {self.reserve_left(today)} · нарядов {len(self.duties_open())}",
                 f"Сегодня: {fmt_h(self.hours_on(today))} из {fmt_h(self.day_plan(today))} ч"
                 + (f", касаний {self.touches_between(today, today)} из {self.touch_quota(today)}" if q else "")
                 + f", боеготовность {score}",
                 f"Неделя: {fmt_h(self.hours_between(monday, today))} из {fmt_h(self.plan_between(monday, week_end))} ч"
                 + (f", касаний {self.touches_between(monday, today)} из {self.touch_target(week_monday(today))}"
                    if q else ""),
                 f"Всего: {fmt_h(self.hours_total())} из {int(self.goal('hours', 630))} ч"
                 + (f", касаний {self.touches_total()} из {int(self.goal('touches', 500))}" if q else "")]
        cards = self.cards_line()
        if cards:
            lines.append(cards)
        gaps = self.behind(today)[:3]
        if gaps:
            lines.append("Недобор недели: " + ", ".join(f"{p} {fmt_h(g)} ч" for g, p, _b, _f in gaps))
        if now is not None:
            blk = self.block_at(now)
            if blk:
                lines.append(f"Сейчас по плану: {blk[0].get('label')} до {blk[2]:%H:%M}")
            else:
                nb = self.next_block(now)
                if nb:
                    lines.append(f"Дальше: {nb[0].get('label')} в {nb[1]:%H:%M}")
        rec = self.day(today)
        lines.append("Сводка: " + ("принята" if rec.get("done") else "не подана")
                     + (" · построение проведено" if rec.get("morning") else " · построения не было"))
        return "\n".join(lines)

    def plan_text(self, d):
        """Приказ на день — утреннее сообщение в Telegram и команда «приказ»."""
        lines = [f"Генштаб · приказ на {WD_SHORT[d.weekday()]}, {d:%d.%m} · {self.campaign_line(d)}"]
        for head, text in self.order_items(d):
            lines.append(f"{head}: {text}")
        rec = self.day(d)
        if rec.get("mit_text"):
            lines.append("Главный удар (построение): " + rec["mit_text"])
        blocks = [b for b in self.blocks_for(d) if b.get("kind") in ("study", "train")]
        if blocks and not self.is_reserve(d):
            lines.append("Блоки: " + ", ".join(f"{b['start']}–{b['end']} {b.get('label', '')}" for b in blocks[:8]))
        soon = [x for x in self.calendar() if x.get("date") and d <= x["date"] <= d + timedelta(days=3)
                and not x.get("done")]
        for x in soon[:4]:
            lines.append(f"Скоро: {x['date']:%d.%m} {x.get('title', '')}")
        cards = self.cards_line()
        if cards:
            lines.append(cards)
        proto = self.protocol_of_day(d)
        if proto:
            lines.append(f"Протокол дня: если {lc_first(proto['if'])} — {proto['then']}")
        sig = [x for x in self.signals() if (parse_dt(x["at"]) or datetime.min).date() == d]
        if sig:
            lines.append("Сигналы: " + ", ".join(f"{parse_dt(x['at']):%H:%M} {x['text']}" for x in sig[:5]))
        lines.append("Факты — сюда: «+1,5 тервер», «старт эконом» / «стоп», «перехват ютуб 4», «трата 350 кафе», "
                     "«напомни 18:00 …», «статус».")
        return "\n".join(lines)

    def cards_line(self):
        store = getattr(self.app, "notes_store", None)
        if store is None:
            return ""
        try:
            due, done = store.due_count(), store.reviews_today()
        except sqlite3.Error:
            return ""
        if not due and not done:
            return ""
        return f"Карточки: к повторению {due}" + (f", сегодня повторено {done}" if done else "")

    DIARY_COLUMNS = [("date", "Дата"), ("weekday", "День недели"), ("no", "День системы"), ("type", "Тип дня"),
                     ("plan", "Норма, ч"), ("hours", "Факт, ч"), ("score", "Боеготовность"), ("good", "Засчитан"),
                     ("checkin", "Сводка"), ("sleep", "Сон, ч"), ("wake", "Подъём"), ("train", "Тренировка"),
                     ("food", "Питание"), ("energy", "Энергия"), ("touches", "Касания"), ("calls", "Созвоны"),
                     ("distract", "Залипание, мин"), ("first_active", "Первое действие"),
                     ("last_active", "Последняя активность"), ("promise", "Обещал утром, ч"),
                     ("mit", "Главное на день"), ("note", "Итог дня"), ("urges", "Перехватов"), ("fell", "Срывов"),
                     ("lists", "Листов закрыто"), ("spent", "Траты")]

    def diary_rows(self, today):
        out = []
        for d in self.dates(self.start(), min(today, self.end())):
            rec = self.day(d)
            score, _p = self.day_score(d)
            out.append({"date": d.isoformat(), "weekday": WD_SHORT[d.weekday()], "no": self.day_no(d),
                        "type": "резерв" if self.is_reserve(d) else self.day_type(d),
                        "plan": fmt_plain(self.day_plan(d)),
                        "hours": fmt_plain(round(self.hours_on(d), 2)), "score": score,
                        "good": "да" if score >= int(self.coach.get("good_score", 70) or 70) else "",
                        "checkin": "да" if rec.get("done") else ("пропуск" if rec.get("skipped") else ""),
                        "sleep": fmt_plain(rec.get("sleep")) if rec.get("sleep") is not None else "",
                        "wake": rec.get("wake") or "", "train": rec.get("train") or "",
                        "food": self.food_score(d) if rec.get("done") else "",
                        "energy": rec.get("energy") or "", "touches": self.touches_between(d, d),
                        "calls": self.touches_between(d, d, calls=True),
                        "distract": fmt_plain(rec.get("distract")) if rec.get("distract") else "",
                        "first_active": rec.get("first_active") or "", "last_active": rec.get("last_active") or "",
                        "promise": fmt_plain(rec.get("promise")) if rec.get("promise") else "",
                        "mit": rec.get("mit_text") or "", "note": rec.get("note") or ""})
            st = self.urge_stats(d, d)
            dl, nl, _m, _i = self.checks_day(d)
            spent = self.money_spent(d, d)
            out[-1].update(urges=st["n"] or "", fell=st["fell"] or "", lists=f"{dl} из {nl}" if nl else "",
                           spent=fmt_plain(round(spent, 2)) if spent else "")
        return out


