def ui_card(parent, app, padx=14, pady=10):
    outer = tk.Frame(parent, bg=C.LINE, padx=1, pady=1)
    card = tk.Frame(outer, bg=C.SURFACE, padx=app.px(padx), pady=app.px(pady))
    card.pack(fill="both", expand=True)
    return outer, card


def ui_link(parent, app, text, command, fg=None, font="small"):
    lbl = tk.Label(parent, text=text, font=app.fonts[font], bg=parent.cget("bg"), fg=fg or C.FOCUS, cursor="hand2")
    lbl.bind("<Button-1>", lambda e: command())
    return lbl


def ui_text(parent, app, text, font="small", fg=None, wrap=None, **kw):
    lbl = tk.Label(parent, text=text, font=app.fonts[font], bg=parent.cget("bg"), fg=fg or C.MUTED,
                   anchor="w", justify="left", **kw)
    if wrap:
        lbl.configure(wraplength=app.px(wrap))
    else:
        lbl.bind("<Configure>", lambda e: _rewrap(lbl, e.width))
    return lbl


def _rewrap(lbl, width):
    """Перенос строк по ширине. Если за полсекунды ширина второй раз возвращается к тому же значению (перенос
    меняет ширину, ширина — перенос), цикл обрывается: иначе окно зависает в бесконечной перекладке.
    Обычные изменения размера окна (развернуть, вернуть) идут дольше и не блокируются."""
    w = max(120, int(width) - 4)
    try:
        cur = int(float(str(lbl.cget("wraplength")) or 0))
    except (tk.TclError, ValueError):
        return
    if w == cur:
        return
    now = time.monotonic()
    hist = [(x, t) for x, t in getattr(lbl, "_wrap_hist", ()) if now - t < 0.5]
    if sum(1 for x, _t in hist if x == w) >= 2:
        return
    hist.append((w, now))
    lbl._wrap_hist = hist[-8:]
    lbl.configure(wraplength=w)


def ensure_visible(app):
    """Окно спрятано в трей, а нужен диалог: вернуть главное окно (под экраном блокировки — без подъёма)."""
    try:
        if app.state() in ("withdrawn", "iconic"):
            coach = getattr(app, "coach", None)
            if coach is not None and coach.lock is not None:
                app.deiconify()
            else:
                app.show_main()
    except tk.TclError:
        pass


def dialog_place(win, app, y=110):
    win.update_idletasks()
    try:
        x = app.winfo_rootx() + max(0, (app.winfo_width() - win.winfo_reqwidth()) // 2)
        yy = app.winfo_rooty() + app.px(y)
        sh = win.winfo_screenheight()
        if yy + win.winfo_reqheight() > sh - 40:
            yy = max(0, sh - 40 - win.winfo_reqheight())
        win.geometry(f"+{x}+{yy}")
    except tk.TclError:
        pass


def dialog_grab(win):
    def grab():
        try:
            win.grab_set()
        except tk.TclError:
            pass
    win.after(80, grab)


class Bar(tk.Canvas):
    """Полоска прогресса. mark — где надо быть сейчас (доля), рисуется вертикальной чертой."""

    def __init__(self, master, app, frac, color=None, mark=None, height=8):
        super().__init__(master, height=app.px(height), bg=master.cget("bg"), highlightthickness=0)
        self.frac, self.color, self.mark = frac, color or C.FOCUS, mark
        self.bind("<Configure>", lambda e: self.draw())

    def draw(self):
        self.delete("all")
        w, h = self.winfo_width(), self.winfo_height()
        if w < 4:
            return
        self.create_rectangle(0, 0, w, h, fill=C.TRACK, outline="")
        f = max(0.0, min(1.0, self.frac or 0.0))
        if f > 0:
            self.create_rectangle(0, 0, max(2, w * f), h, fill=self.color, outline="")
        if self.mark is not None:
            x = w * max(0.0, min(1.0, self.mark))
            self.create_line(x, 0, x, h, fill=C.INK, width=2)


class FormDialog(tk.Toplevel):
    """Форма из списка полей. on_save(values) может вернуть False, чтобы окно не закрывалось.

    Поле: {"key", "label", "kind": entry|date|time|int|float|combo|text|check|section, "value", "options",
           "hint", "width", "lo", "hi", "optional", "required", "height", "free"}.
    section — заголовок группы полей без значения. scroll=True — длинная форма с прокруткой, кнопки внизу.
    """

    def __init__(self, app, title, fields, on_save, on_delete=None, note=None, width=44, delete_text="Удалить",
                 ok_text="Сохранить", scroll=False, extra_buttons=None):
        ensure_visible(app)
        super().__init__(app)
        self.app = app
        self.fields = fields
        self.on_save = on_save
        self.on_delete = on_delete
        F, px = app.fonts, app.px
        self.title(title)
        self.configure(bg=C.BG)
        self.transient(app)
        self.resizable(False, False)
        self._sf = ScrollFrame(self) if scroll else None
        body = tk.Frame(self._sf.inner if scroll else self, bg=C.BG, padx=px(22), pady=px(18))
        body.pack(fill="both", expand=True)
        body.columnconfigure(1, weight=1)
        row = 0
        if note:
            tk.Label(body, text=note, font=F["small"], bg=C.BG, fg=C.MUTED, anchor="w", justify="left",
                     wraplength=px(520)).grid(row=row, column=0, columnspan=2, sticky="we", pady=(0, px(8)))
            row += 1
        self.widgets = {}
        first = None
        for f in fields:
            kind = f.get("kind", "entry")
            if kind == "section":
                tk.Label(body, text=f.get("label", ""), font=F["ui_bold"], bg=C.BG, fg=C.FOCUS, anchor="w").grid(
                    row=row, column=0, columnspan=2, sticky="we", pady=(px(12) if row else 0, px(2)))
                row += 1
                if f.get("hint"):
                    tk.Label(body, text=f["hint"], font=F["small"], bg=C.BG, fg=C.MUTED, anchor="w", justify="left",
                             wraplength=px(520)).grid(row=row, column=0, columnspan=2, sticky="w")
                    row += 1
                continue
            if kind != "check":
                tk.Label(body, text=f.get("label", ""), font=F["ui"], bg=C.BG, fg=C.MUTED, anchor="nw").grid(
                    row=row, column=0, sticky="nw", padx=(0, px(14)), pady=px(5))
            value = f.get("value")
            if kind == "text":
                w = tk.Text(body, height=f.get("height", 4), width=f.get("width", width), font=F["ui"], wrap="word",
                            relief="flat", bg=C.SURFACE, fg=C.INK, insertbackground=C.INK, highlightthickness=1,
                            highlightbackground=C.LINE, highlightcolor=C.FOCUS, padx=px(8), pady=px(6))
                w.insert("1.0", value or "")
                w.grid(row=row, column=1, sticky="we", pady=px(3))
                self.widgets[f["key"]] = w
            elif kind == "check":
                v = tk.BooleanVar(value=bool(value))
                w = ttk.Checkbutton(body, text=f.get("label", ""), variable=v)
                w.grid(row=row, column=1, sticky="w", pady=px(3))
                self.widgets[f["key"]] = v
            elif kind == "combo":
                v = tk.StringVar(value="" if value is None else str(value))
                w = ttk.Combobox(body, textvariable=v, values=list(f.get("options") or []), font=F["ui"],
                                 state="normal" if f.get("free") else "readonly", width=f.get("width", 28))
                w.grid(row=row, column=1, sticky="w", pady=px(3))
                self.widgets[f["key"]] = v
            elif kind in ("int", "float"):
                v = tk.StringVar(value=fmt_plain(value))
                w = ttk.Spinbox(body, from_=f.get("lo", 0), to=f.get("hi", 1000), increment=f.get("step", 1),
                                textvariable=v, width=f.get("width", 8), font=F["ui"])
                w.grid(row=row, column=1, sticky="w", pady=px(3))
                self.widgets[f["key"]] = v
            else:
                if kind == "date" and value:
                    d = sys_date(value)
                    value = d.strftime("%d.%m.%Y") if d else value
                v = tk.StringVar(value="" if value is None else str(value))
                w = ttk.Entry(body, textvariable=v, font=F["ui"],
                              width=f.get("width", 14 if kind in ("date", "time") else width))
                w.grid(row=row, column=1, sticky="w" if kind in ("date", "time") else "we", pady=px(3))
                self.widgets[f["key"]] = v
            if first is None and kind not in ("check", "combo"):
                first = w
            row += 1
            if f.get("hint"):
                tk.Label(body, text=f["hint"], font=F["small"], bg=C.BG, fg=C.MUTED, anchor="w", justify="left",
                         wraplength=px(420)).grid(row=row, column=1, sticky="w")
                row += 1
        if scroll:
            btns = tk.Frame(self, bg=C.BG, padx=px(22), pady=px(12))
            btns.pack(side="bottom", fill="x")
            tk.Frame(self, bg=C.LINE, height=1).pack(side="bottom", fill="x")
        else:
            btns = tk.Frame(body, bg=C.BG)
            btns.grid(row=row, column=0, columnspan=2, sticky="we", pady=(px(16), 0))
        if on_delete:
            ttk.Button(btns, text=delete_text, command=self._delete).pack(side="left")
        for label, cmd in extra_buttons or []:
            ttk.Button(btns, text=label, command=lambda c=cmd: c(self)).pack(side="left", padx=(0, px(8)))
        ttk.Button(btns, text="Отмена", command=self.destroy).pack(side="right")
        ttk.Button(btns, text=ok_text, style="Work.TButton", command=self._save).pack(side="right",
                                                                                         padx=(0, px(8)))
        if scroll:
            self._sf.pack(fill="both", expand=True)
            self.update_idletasks()
            h = min(body.winfo_reqheight(), int(self.winfo_screenheight() * 0.68))
            self._sf.canvas.configure(width=body.winfo_reqwidth(), height=h)
        self.bind("<Escape>", lambda e: self.destroy())
        self.bind("<Return>", self._on_return)
        coach = getattr(app, "coach", None)
        if coach is not None and coach.lock is not None:
            try:
                self.attributes("-topmost", True)
            except tk.TclError:
                pass
        dialog_place(self, app)
        if first is not None:
            first.focus_set()
        dialog_grab(self)

    def _on_return(self, e):
        if isinstance(e.widget, tk.Text):
            return None
        self._save()
        return "break"

    def _warn(self, text):
        messagebox.showwarning(APP_NAME, text, parent=self)
        return None

    def values(self):
        out = {}
        for f in self.fields:
            key, kind = f.get("key"), f.get("kind", "entry")
            if kind == "section":
                continue
            w = self.widgets[key]
            if kind == "text":
                out[key] = w.get("1.0", "end").strip()
                if f.get("required") and not out[key]:
                    return self._warn(f"«{f['label']}»: заполни поле.")
                continue
            raw = w.get()
            if kind == "check":
                out[key] = bool(raw)
                continue
            raw = str(raw).strip()
            if kind == "date":
                if not raw:
                    if f.get("required"):
                        return self._warn(f"«{f['label']}»: нужна дата.")
                    out[key] = None
                    continue
                try:
                    d = parse_date(raw, self.app.today())
                except ValueError:
                    return self._warn(f"«{f['label']}»: не понял дату. Примеры: 25.10, 25.10.2026, пт, +3.")
                out[key] = d.isoformat() if d else None
            elif kind == "time":
                if not raw:
                    out[key] = None
                    continue
                m = re.fullmatch(r"(\d{1,2})[:.](\d{2})", raw)
                if not m or int(m[1]) > 23 or int(m[2]) > 59:
                    return self._warn(f"«{f['label']}»: время в виде 07:30.")
                out[key] = f"{int(m[1]):02d}:{m[2]}"
            elif kind in ("int", "float"):
                if not raw:
                    if f.get("optional"):
                        out[key] = None
                        continue
                    return self._warn(f"«{f['label']}»: нужно число.")
                try:
                    num = float(raw.replace(",", ".").replace(" ", ""))
                except ValueError:
                    return self._warn(f"«{f['label']}»: нужно число.")
                lo, hi = f.get("lo"), f.get("hi")
                if (lo is not None and num < lo) or (hi is not None and num > hi):
                    return self._warn(f"«{f['label']}»: число от {fmt_h(lo)} до {fmt_h(hi)}.")
                out[key] = int(round(num)) if kind == "int" else round(num, 2)
            else:
                if f.get("required") and not raw:
                    return self._warn(f"«{f['label']}»: заполни поле.")
                out[key] = raw
        return out

    def _save(self):
        vals = self.values()
        if vals is None:
            return
        if self.on_save(vals) is False:
            return
        self.destroy()

    def _delete(self):
        if self.on_delete() is False:
            return
        self.destroy()


class CheckinForm(tk.Frame):
    """Вечерняя сводка: тип дня, сон, тренировка, питание, энергия, план на завтра. Часы и касания — сами."""

    def __init__(self, parent, app, day=None, on_saved=None, lock=False):
        bg = parent.cget("bg")
        super().__init__(parent, bg=bg)
        self.app, self.on_saved, self.lock = app, on_saved, lock
        sysm = app.system
        F, px = app.fonts, app.px
        self.day = d = day or app.today()
        rec = sysm.day(d)
        when = "сегодня" if d == app.today() else ("вчера" if d == app.today() - timedelta(days=1) else "")
        head = f"{WD_FULL[d.weekday()].capitalize()}, {d.day} {MONTHS_GEN[d.month - 1]}" + (f" — {when}" if when else "")
        tk.Label(self, text=head, font=F["h2"], bg=bg, fg=C.INK).grid(row=0, column=0, columnspan=2, sticky="w")
        hours, plan = sysm.hours_on(d), sysm.day_plan(d)
        touches = sysm.touches_between(d, d)
        calls = sysm.touches_between(d, d, calls=True)
        facts = [f"Часы {fmt_h(hours)} из {fmt_h(plan)}", f"касаний {touches}" + (f", созвонов {calls}" if calls else "")]
        if rec.get("promise"):
            facts.append(f"на построении взял норму {fmt_h(rec['promise'])} ч")
        if rec.get("first_active"):
            facts.append(f"первое действие за компьютером {rec['first_active']}")
        prev = sysm.day(d - timedelta(days=1))
        if prev.get("last_active"):
            facts.append(f"вчера за компьютером до {prev['last_active']}")
        if float(rec.get("distract") or 0) >= 1:
            facts.append(f"залипание {fmt_minutes(float(rec['distract']))}")
        score, _parts = sysm.day_score(d)
        facts.append(f"боеготовность сейчас {score}")
