def konspektor_sources():
    """Где искать базу Конспектора: 2.0 — в APPDATA, 1.0 — в домашней папке."""
    out = []
    env = os.environ.get("KONSPEKTOR_DB")
    if env:
        out.append(Path(env).expanduser())
    if IS_WIN and os.environ.get("APPDATA"):
        out.append(Path(os.environ["APPDATA"]) / "Konspektor" / "konspektor.db")
    elif IS_MAC:
        out.append(Path.home() / "Library" / "Application Support" / "Konspektor" / "konspektor.db")
    else:
        out.append(Path(os.environ.get("XDG_DATA_HOME") or Path.home() / ".local" / "share") / "konspektor"
                   / "konspektor.db")
    out.append(Path.home() / ".konspektor" / "konspektor.db")
    return [p for p in out if p.exists()]


def open_note_store(path):
    """Открывает базу конспектов. Битую базу откладывает рядом (notes.broken-….db) и начинает с чистой,
    чтобы Генштаб всё равно запустился. Возвращает (база, путь к отложенной или None)."""
    try:
        st = NoteStore(path)
        st._q("SELECT COUNT(*) FROM cards").fetchone()
        st._q("SELECT COUNT(*) FROM notes").fetchone()
        return st, None
    except sqlite3.Error:
        traceback.print_exc()
    try:
        st.db.close()
    except Exception:
        pass
    broken = Path(path).with_name(f"notes.broken-{datetime.now():%Y%m%d-%H%M%S}.db")
    try:
        os.replace(path, broken)
    except OSError:
        broken = None
    try:
        return NoteStore(path), broken
    except sqlite3.Error:
        traceback.print_exc()
        return NoteStore(":memory:", seed=False), broken


class NoteStore:
    """Конспекты, майндмэпы и карточки — отдельная база SQLite рядом с data.json."""

    def __init__(self, path, seed=True):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fresh = not self.path.exists()
        self.db = sqlite3.connect(str(self.path))
        self.db.row_factory = sqlite3.Row
        self.db.executescript(NOTES_SCHEMA)
        cols = {r[1] for r in self.db.execute("PRAGMA table_info(notes)")}
        if "project" not in cols:
            self.db.execute("ALTER TABLE notes ADD COLUMN project TEXT NOT NULL DEFAULT ''")
        self.db.commit()
        self.new_per_day = 20
        self.today_fn = None     # логический день Генштаба (с учётом «день начинается в N часов»)
        self.imported = None
        if fresh and seed:
            for src in konspektor_sources():
                try:
                    counts = self.import_db(src)
                except sqlite3.Error:
                    continue
                if sum(counts.values()):
                    self.imported = (src, counts)
                    self.set_meta("imported_from", str(src))
                    break
            self.create_note("Как устроены конспекты в Генштабе", KONSPEKT_WELCOME, "справка")

    # --- служебное ---
    def _q(self, sql, args=()):
        return self.db.execute(sql, args)

    def _w(self, sql, args=()):
        cur = self.db.execute(sql, args)
        self.db.commit()
        return cur

    def count(self, table):
        return self._q(f"SELECT COUNT(*) FROM {table}").fetchone()[0]

    def close(self):
        try:
            self.db.close()
        except sqlite3.Error:
            pass

    def get_meta(self, key, default=None):
        row = self._q("SELECT value FROM meta WHERE key=?", (key,)).fetchone()
        return row["value"] if row else default

    def set_meta(self, key, value):
        self._w("INSERT OR REPLACE INTO meta(key, value) VALUES (?,?)", (key, str(value)))

    def day(self):
        try:
            d = self.today_fn() if self.today_fn else date.today()
        except Exception:
            d = date.today()
        return d if isinstance(d, date) else date.today()

    def today(self):
        return self.day().isoformat()

    # --- конспекты ---
    def list_notes(self):
        return self._q("SELECT id, title, tags, body, project, updated FROM notes ORDER BY updated DESC").fetchall()

    def get_note(self, nid):
        return self._q("SELECT * FROM notes WHERE id=?", (nid,)).fetchone()

    def find_note(self, title):
        key = title.strip().lower()
        for row in self._q("SELECT id, title FROM notes"):
            if row["title"].strip().lower() == key:
                return row
        return None

    def create_note(self, title, body="", tags="", project=""):
        ts = time.time()
        return self._w("INSERT INTO notes(title, body, tags, project, created, updated) VALUES (?,?,?,?,?,?)",
                       (title, body, tags, project or "", ts, ts)).lastrowid

    def update_note(self, nid, title, body, tags):
        self._w("UPDATE notes SET title=?, body=?, tags=?, updated=? WHERE id=?",
                (title, body, tags, time.time(), nid))

    def set_note_project(self, nid, project):
        self._w("UPDATE notes SET project=? WHERE id=?", (project or "", nid))

    def append_note(self, title, text, project=""):
        """Дописать текст в конспект (создать его, если нет). Для быстрой записи и Telegram."""
        row = self.find_note(title)
        if row is None:
            return self.create_note(title, text.strip() + "\n", "", project)
        body = self.get_note(row["id"])["body"].rstrip("\n")
        self._w("UPDATE notes SET body=?, updated=? WHERE id=?",
                ((body + "\n" if body else "") + text.strip() + "\n", time.time(), row["id"]))
        return row["id"]

    def delete_note(self, nid):
        self._w("DELETE FROM notes WHERE id=?", (nid,))

    def rename_project(self, old, new):
        self._w("UPDATE notes SET project=? WHERE project=?", (new, old))
        self._w("UPDATE decks SET project=? WHERE project=?", (new, old))

    # --- майндмэпы ---
    def list_maps(self):
        return self._q("SELECT id, title, updated FROM maps ORDER BY updated DESC").fetchall()

    def get_map(self, mid):
        return self._q("SELECT * FROM maps WHERE id=?", (mid,)).fetchone()

    def create_map(self, title, data):
        ts = time.time()
        return self._w("INSERT INTO maps(title, data, created, updated) VALUES (?,?,?,?)",
                       (title, data, ts, ts)).lastrowid

    def update_map(self, mid, title, data):
        self._w("UPDATE maps SET title=?, data=?, updated=? WHERE id=?", (title, data, time.time(), mid))

    def delete_map(self, mid):
        self._w("DELETE FROM maps WHERE id=?", (mid,))

    # --- карточки ---
    def add_card(self, deck, front, back):
        return self._w("INSERT INTO cards(deck, front, back, due, created) VALUES (?,?,?,?,?)",
                       (deck, front, back, self.today(), time.time())).lastrowid

    def upsert_card(self, deck, front, back):
        row = self._q("SELECT id, back FROM cards WHERE deck=? AND front=?", (deck, front)).fetchone()
        if row is None:
            self.add_card(deck, front, back)
            return "added"
        if row["back"] != back:
            self._w("UPDATE cards SET back=? WHERE id=?", (back, row["id"]))
            return "updated"
        return "same"

    def get_card(self, cid):
        return self._q("SELECT * FROM cards WHERE id=?", (cid,)).fetchone()

    def update_card(self, cid, deck, front, back):
        self._w("UPDATE cards SET deck=?, front=?, back=? WHERE id=?", (deck, front, back, cid))

    def delete_card(self, cid):
        self._w("DELETE FROM cards WHERE id=?", (cid,))
        self._w("DELETE FROM reviews WHERE card_id=?", (cid,))

    def delete_deck(self, deck):
        self._w("DELETE FROM reviews WHERE card_id IN (SELECT id FROM cards WHERE deck=?)", (deck,))
        self._w("DELETE FROM cards WHERE deck=?", (deck,))
        self._w("DELETE FROM decks WHERE name=?", (deck,))

    def rename_deck(self, old, new):
        self._w("UPDATE cards SET deck=? WHERE deck=?", (new, old))
        proj = self.deck_project(old)
        self._w("DELETE FROM decks WHERE name=?", (old,))
        if proj:
            self.set_deck_project(new, proj)

    def deck_project(self, deck):
        row = self._q("SELECT project FROM decks WHERE name=?", (deck,)).fetchone()
        return row["project"] if row else ""

    def set_deck_project(self, deck, project):
        self._w("INSERT OR REPLACE INTO decks(name, project) VALUES (?,?)", (deck, project or ""))

    def _new_left(self):
        return max(0, int(self.new_per_day) - self.new_started_today())

    def _due_rows(self, deck=None):
        """Карточки к повторению: все повторные + новые в пределах дневного лимита."""
        today = self.today()
        sql = ("SELECT c.*, " + self.NEW_SQL + " AS is_new FROM cards c "
               "WHERE c.due <= ?" + (" AND c.deck=?" if deck is not None else "") + " ORDER BY c.due, c.id")
        rows = self._q(sql, (today, deck) if deck is not None else (today,)).fetchall()
        old = [r for r in rows if not r["is_new"]]
        new = [r for r in rows if r["is_new"]][:self._new_left()]
        return old + new

    # новая карточка — ни разу не повторялась; перенесённые из Конспектора с интервалом новыми не считаются
    NEW_SQL = ("(c.reps = 0 AND c.ivl = 0 AND NOT EXISTS (SELECT 1 FROM reviews r WHERE r.card_id=c.id))")

    def due_cards(self, deck=None):
        return self._due_rows(deck)

    def due_count(self, deck=None):
        return len(self._due_rows(deck))

    def list_decks(self):
        today = self.today()
        rows = self._q("SELECT c.deck, COUNT(*) AS total, "
                       "SUM(CASE WHEN c.due <= ? AND NOT " + self.NEW_SQL + " THEN 1 ELSE 0 END) AS old_due, "
                       "SUM(CASE WHEN c.due <= ? AND " + self.NEW_SQL + " THEN 1 ELSE 0 END) AS new_due "
                       "FROM cards c GROUP BY c.deck ORDER BY c.deck COLLATE NOCASE", (today, today)).fetchall()
        left = self._new_left()
        return [{"deck": r["deck"], "total": r["total"], "due": (r["old_due"] or 0) + min(r["new_due"] or 0, left)}
                for r in rows]

    def list_cards(self, deck=None):
        if deck is None:
            return self._q("SELECT * FROM cards ORDER BY deck, id").fetchall()
        return self._q("SELECT * FROM cards WHERE deck=? ORDER BY id", (deck,)).fetchall()

    def count_cards(self, deck=None):
        if deck is None:
            return self.count("cards")
        return self._q("SELECT COUNT(*) FROM cards WHERE deck=?", (deck,)).fetchone()[0]

    def review(self, cid, grade):
        row = self.get_card(cid)
        if row is None:
            return None
        ease, ivl, reps = schedule(row["ease"], row["ivl"], row["reps"], grade)
        due = (self.day() + timedelta(days=ivl)).isoformat()
        self.db.execute("UPDATE cards SET ease=?, ivl=?, reps=?, due=? WHERE id=?", (ease, ivl, reps, due, cid))
        self.db.execute("INSERT INTO reviews(card_id, grade, day, ts) VALUES (?,?,?,?)",
                        (cid, grade, self.today(), time.time()))
        self.db.commit()
        return ivl

    def new_started_today(self):
        return self._q("SELECT COUNT(*) FROM (SELECT card_id, MIN(day) AS d FROM reviews GROUP BY card_id) "
                       "WHERE d = ?", (self.today(),)).fetchone()[0]

    def reviews_on(self, day_iso):
        return self._q("SELECT COUNT(*) FROM reviews WHERE day=?", (day_iso,)).fetchone()[0]

    def reviews_today(self):
        return self.reviews_on(self.today())

    def review_days(self):
        return {r["day"] for r in self._q("SELECT DISTINCT day FROM reviews")}

    def streak(self):
        days = self.review_days()
        d = self.day()
        if d.isoformat() not in days:
            d -= timedelta(days=1)
        n = 0
        while d.isoformat() in days:
            n += 1
            d -= timedelta(days=1)
        return n

    def next_due(self):
        row = self._q("SELECT MIN(due) AS d FROM cards WHERE due > ?", (self.today(),)).fetchone()
        return row["d"] if row else None

    # --- перенос и копии ---
    def import_db(self, path):
        """Добавить конспекты, карты, карточки и историю повторений из другой базы Конспектора."""
        src = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
        src.row_factory = sqlite3.Row
        counts = {"notes": 0, "maps": 0, "cards": 0, "reviews": 0}
        try:
            tables = {r[0] for r in src.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if "notes" in tables:
                cols = {r[1] for r in src.execute("PRAGMA table_info(notes)")}
                for r in src.execute("SELECT * FROM notes"):
                    if self._q("SELECT 1 FROM notes WHERE title=? AND body=?", (r["title"], r["body"])).fetchone():
                        continue
                    self.db.execute("INSERT INTO notes(title, body, tags, project, created, updated) "
                                    "VALUES (?,?,?,?,?,?)",
                                    (r["title"], r["body"], r["tags"], r["project"] if "project" in cols else "",
                                     r["created"], r["updated"]))
                    counts["notes"] += 1
            if "maps" in tables:
                for r in src.execute("SELECT * FROM maps"):
                    if self._q("SELECT 1 FROM maps WHERE title=? AND data=?", (r["title"], r["data"])).fetchone():
                        continue
                    self.db.execute("INSERT INTO maps(title, data, created, updated) VALUES (?,?,?,?)",
                                    (r["title"], r["data"], r["created"], r["updated"]))
                    counts["maps"] += 1
            if "cards" in tables:
                idmap = {}
                for r in src.execute("SELECT * FROM cards"):
                    if self._q("SELECT 1 FROM cards WHERE deck=? AND front=?", (r["deck"], r["front"])).fetchone():
                        continue
                    cur = self.db.execute("INSERT INTO cards(deck, front, back, ease, ivl, reps, due, created) "
                                          "VALUES (?,?,?,?,?,?,?,?)",
                                          (r["deck"], r["front"], r["back"], r["ease"], r["ivl"], r["reps"], r["due"],
                                           r["created"]))
                    idmap[r["id"]] = cur.lastrowid
                    counts["cards"] += 1
                if "reviews" in tables and idmap:
                    for r in src.execute("SELECT * FROM reviews"):
                        if r["card_id"] in idmap:
                            self.db.execute("INSERT INTO reviews(card_id, grade, day, ts) VALUES (?,?,?,?)",
                                            (idmap[r["card_id"]], r["grade"], r["day"], r["ts"]))
                            counts["reviews"] += 1
            self.db.commit()
        finally:
            src.close()
        return counts

    def backup_to(self, target):
        dst = sqlite3.connect(str(target))
        with dst:
            self.db.backup(dst)
        dst.close()

    def backup_daily(self, folder, keep=14):
        today = self.today()
        folder = Path(folder)
        target = folder / f"notes-{today}.db"
        if target.exists():
            return
        try:
            folder.mkdir(parents=True, exist_ok=True)
            self.backup_to(target)
            for old in sorted(folder.glob("notes-????-??-??.db"))[:-keep]:
                old.unlink()
        except (OSError, sqlite3.Error):
            pass

    def summary(self):
        return {"notes": self.count("notes"), "maps": self.count("maps"), "cards": self.count("cards"),
                "due": self.due_count(), "streak": self.streak(), "today": self.reviews_today()}


# ───────── вкладки Конспектора в Генштабе ─────────

class TNotesTab(NotesTab):
    """Конспекты + направление: время, пока пишешь, идёт в часы этого направления."""

    def _build(self):
        super()._build()
        row = self.tags_entry.master
        self.proj_var = tk.StringVar()
        box = ttk.Combobox(row, textvariable=self.proj_var, state="readonly", width=22,
                           values=[""] + list(self.app.tempo.store.projects))
        box.pack(side="right", before=self.tags_entry)
        ttk.Label(row, text="Направление:", style="KHint.TLabel").pack(side="right", padx=(12, 6), after=box)
        box.bind("<<ComboboxSelected>>", lambda e: self._set_project())
        self.proj_box = box
        Tooltip(box, "Пока пишешь этот конспект, время идёт в часы этого направления")

    def _config_tags(self):
        super()._config_tags()
        mono = self.app.mono_family
        self.text.tag_configure("code", font=(mono, 11), background=C.SOFT, foreground=C.FLOW)
        self.text.tag_configure("mark", foreground=C.MUTED)

    def _set_project(self):
        if self.current_id is None:
            return
        self.store.set_note_project(self.current_id, self.proj_var.get())
        self.app.set_status(f"Направление конспекта: {self.proj_var.get() or 'не выбрано'}")

    def open_note(self, nid):
        super().open_note(nid)
        row = self.store.get_note(nid)
        if row is not None:
            self.proj_box.configure(values=[""] + list(self.app.tempo.store.projects))
            self.proj_var.set(row["project"] or "")

    def _set_enabled(self, enabled):
        super()._set_enabled(enabled)
        try:
            self.proj_box.configure(state="readonly" if enabled else "disabled")
            if not enabled:
                self.proj_var.set("")
        except (AttributeError, tk.TclError):
            pass

    def new_note(self):
        self.save_now()
        proj = self.app.tempo.store.settings.get("current_project") or ""
        nid = self.store.create_note("Новый конспект", "", "", proj)
        self.app.nb.select(0)
        self.show(nid)
        self.title_entry.focus_set()
        self.title_entry.select_range(0, "end")

    def current_project(self):
        if self.current_id is None:
            return None
        return self.proj_var.get()


class TCardsTab(CardsTab):
    """Карточки + направление колоды, клавиши повторения без ручной маршрутизации."""

    def _build(self):
        super()._build()
        left = self.deck_tree.master.master
        row3 = ttk.Frame(left, style="KSide.TFrame")
        row3.pack(fill="x", pady=(6, 0))
        ttk.Button(row3, text="Направление колоды", command=self.set_deck_project).pack(side="left")
        self.bind("<KeyPress>", self.on_key)

        def bind_keys(w):
            # клавиши повторения работают, даже если фокус на списке колод или на кнопке
            for ch in w.winfo_children():
                if not isinstance(ch, (tk.Text, tk.Entry, ttk.Entry, tk.Spinbox)):
                    ch.bind("<KeyPress>", self.on_key, add="+")
                bind_keys(ch)
        bind_keys(self)
        px = self.app.tempo.px
        self.deck_tree.column("deck", width=px(124))
        self.deck_tree.column("due", width=px(82))
        self.deck_tree.column("total", width=px(60))

    def set_deck_project(self):
        if self.deck is None:
            messagebox.showinfo(APP_NAME, "Выбери колоду в списке слева.", parent=self)
            return
        tempo = self.app.tempo
        cur = self.store.deck_project(self.deck)

        def save(v):
            self.store.set_deck_project(self.deck, v["project"])
            self.app.set_status(f"Колода «{self.deck}» → {v['project'] or 'без направления'}")
        FormDialog(tempo, f"Колода «{self.deck}»", [
            {"key": "project", "label": "Направление", "kind": "combo", "options": [""] + list(tempo.store.projects),
             "value": cur, "hint": "время повторения этой колоды пойдёт в часы направления"}], save)

    def grade(self, g):
        super().grade(g)
        self.app.update_header()

    def refresh(self, restart=False):
        self.store.new_per_day = self.app.new_per_day()
        super().refresh(restart)
        self.app.update_header()

    def refresh_decks(self):
        super().refresh_decks()
        # по колодам лимит новых считается для каждой; в сумме — один общий лимит на день
        t = self.deck_tree
        try:
            vals = list(t.item(self.ALL, "values"))
            due = self.store.due_count()
            t.item(self.ALL, values=("Все колоды", due, vals[2] if len(vals) > 2 else ""),
                   tags=("all", "due") if due else ("all",))
        except (tk.TclError, sqlite3.Error):
            pass

    def rename_deck(self):
        if self.deck is None:
            messagebox.showinfo(APP_NAME, "Выбери колоду в списке слева.", parent=self)
            return
        new = simpledialog.askstring(APP_NAME, "Новое название колоды:", initialvalue=self.deck, parent=self)
        new = " ".join((new or "").split())
        if not new or new == self.deck:
            return
        self.store.rename_deck(self.deck, new)
        self.deck = new
        self.refresh()

    def current_project(self):
        deck = self.current["deck"] if self.current is not None else self.deck
        return self.store.deck_project(deck) if deck else None


class _Pages:
    """Совместимость с Конспектором: app.nb.select(0/1/2)."""

    def __init__(self, view):
        self.view = view

    def select(self, index):
        self.view.select(NotesView.TABS[index][0])

    def index(self, _what="current"):
        return [k for k, _t in NotesView.TABS].index(self.view.tab)


class NotesView(tk.Frame):
    """Раздел «Конспекты»: конспекты, майндмэпы и карточки из Конспектора — внутри Генштаба."""

    TABS = [("notes", "Конспекты"), ("maps", "Майндмэпы"), ("cards", "Карточки")]

    def __init__(self, master, app):
        super().__init__(master, bg=C.BG)
        self.tempo = app
        self.store = app.notes_store
        konspekt_palette()
        setup_konspekt_styles(app)
        F, px = app.fonts, app.px
        self.ui_family = F["ui"][0]
        self.mono_family = F["mono"][0]
        self.f_editor = tkfont.Font(self, family=self.ui_family, size=F["ui"][1] + 2)
        self.nb = _Pages(self)
        self.tab = app.store.settings.get("notes_tab") or "notes"
        if self.tab not in dict(self.TABS):
            self.tab = "notes"

        head = tk.Frame(self, bg=C.BG)
        head.pack(fill="x", padx=px(24), pady=(px(16), px(6)))
        tk.Label(head, text="Арсенал", font=F["h1"], bg=C.BG, fg=C.INK).pack(side="left")
        self.seg = Segmented(head, app, self.TABS, self.select)
        self.seg.pack(side="left", padx=(px(18), 0))
        menu_btn = ttk.Menubutton(head, text="Файл", style="KTool.TMenubutton")
        m = tk.Menu(menu_btn, tearoff=False)
        m.add_command(label="Новый конспект", command=lambda: (self.select("notes"), self.notes.new_note()))
        m.add_command(label="Новая карта", command=lambda: (self.select("maps"), self.maps.new_map()))
        m.add_command(label="Новая карточка", command=lambda: (self.select("cards"), self.cards.new_card()))
        m.add_separator()
        m.add_command(label="Импортировать .md / .txt…", command=self.import_files)
        m.add_command(label="Экспортировать конспект в .md…", command=lambda: self.notes.export_md())
        m.add_command(label="Экспортировать все конспекты в папку…", command=self.export_all)
        m.add_separator()
        m.add_command(label="Добавить базу Конспектора…", command=self.import_konspektor)
        m.add_command(label="Сохранить копию базы…", command=self.backup)
        m.add_command(label="Новых карточек в день…", command=self.edit_limit)
        m.add_separator()
        m.add_command(label="Горячие клавиши", command=self.show_help)
        menu_btn["menu"] = m
        menu_btn.pack(side="right")
        self.stats = tk.Label(head, text="", font=F["small"], bg=C.BG, fg=C.MUTED)
        self.stats.pack(side="right", padx=px(12))

        self.status_var = tk.StringVar(value="")
        tk.Label(self, textvariable=self.status_var, font=F["small"], bg=C.SIDEBAR, fg=C.MUTED, anchor="w",
                 padx=px(12), pady=px(3)).pack(side="bottom", fill="x")
        self.body = tk.Frame(self, bg=C.BG)
        self.body.pack(fill="both", expand=True)
        self.store.new_per_day = self.new_per_day()
        self.notes = TNotesTab(self.body, self)
        self.maps = MapsTab(self.body, self)
        self.cards = TCardsTab(self.body, self)
        self._pages = {"notes": self.notes, "maps": self.maps, "cards": self.cards}
        self.notes.start()
        self.maps.start()
        self.cards.refresh(restart=True)
        self._shown = None
        self.select(self.tab, focus=False)

    # --- совместимость с Конспектором ---
    def set_status(self, text):
        self.status_var.set(text)

    def update_header(self):
        try:
            s = self.store.summary()
        except sqlite3.Error:
            return
        parts = [f"к повторению {s['due']}" if s["due"] else "повторять нечего"]
        if s["today"]:
            parts.append(f"сегодня ответов {s['today']}")
        if s["streak"]:
            parts.append(f"серия {s['streak']} дн.")
        parts.append(f"конспектов {s['notes']}, карточек {s['cards']}")
        self.stats.configure(text=" · ".join(parts), fg=C.DANGER if s["due"] else C.MUTED)
        self.seg.labels["cards"].configure(text=f"Карточки · {s['due']}" if s["due"] else "Карточки")
        self.seg.set(self.tab, C.FOCUS)

    def new_per_day(self):
        try:
            return int((self.tempo.system.s.get("notes_cfg") or {}).get("new_per_day", 20))
        except (TypeError, ValueError):
            return 20

    # --- вкладки ---
    def select(self, key, focus=True):
        if key not in self._pages:
            return
        prev = self._shown
        if prev == "notes" and key != "notes":
            self.notes.save_now()
        if prev == "maps" and key != "maps":
            self.maps.save_now()
        for k, w in self._pages.items():
            if k != key:
                w.pack_forget()
        self._pages[key].pack(fill="both", expand=True)
        self.tab = self._shown = key
        self.tempo.store.settings["notes_tab"] = key
        self.update_header()
        if key == "notes" and focus and str(self.notes.text["state"]) == "normal":
            self.notes.text.focus_set()
        elif key == "maps":
            self.maps.on_show()
        elif key == "cards":
            self.cards.refresh()
            if focus:
                self.cards.focus_set()

    def on_show(self):
        self.select(self.tab)

    def refresh(self):
        self.update_header()

    def save_all(self):
        for fn in (self.notes.save_now, self.maps.save_now):
            try:
                fn()
            except (tk.TclError, sqlite3.Error):
                pass

    def destroy(self):
        self.save_all()
        super().destroy()

    def activity(self):
        """Над чем идёт работа в разделе: (направление, подпись) или None."""
        if self.tab == "notes":
            proj = self.notes.current_project()
            if proj is None:
                return None
            return proj, "Конспект: " + (self.notes.title_var.get().strip() or "без названия")
        if self.tab == "cards":
            if self.cards.current is None:
                return None
            return self.cards.current_project() or "", "Карточки: " + (self.cards.current["deck"] or "")
        if self.tab == "maps" and self.maps.data is not None:
            return "", "Майндмэп: " + self.maps._title()
        return None

    def open_cards(self):
        self.select("cards")
        self.cards.set_mode("review")
        self.cards.refresh(restart=True)

    def open_note_by_id(self, nid):
        self.select("notes")
        self.notes.show(nid)

    # --- файлы ---
    def import_files(self):
        paths = filedialog.askopenfilenames(parent=self.tempo, title="Импорт конспектов",
                                            filetypes=[("Markdown и текст", "*.md *.markdown *.txt"),
                                                       ("Все файлы", "*.*")])
        if not paths:
            return
        last, done = None, 0
        for path in paths:
            try:
                with open(path, encoding="utf-8-sig", errors="replace") as fh:
                    raw = fh.read()
            except OSError as e:
                messagebox.showerror(APP_NAME, f"Не удалось прочитать {path}:\n{e}", parent=self.tempo)
                continue
            title, body = split_title(raw, os.path.splitext(os.path.basename(path))[0])
            last = self.store.create_note(title, body, "")
            done += 1
        if last:
            self.select("notes")
            self.notes.show(last)
        self.set_status(f"Импортировано конспектов: {done}")

    def export_all(self):
        self.notes.save_now()
        folder = filedialog.askdirectory(parent=self.tempo, title="Папка для экспорта")
        if not folder:
            return
        used = set()
        rows = self.store.list_notes()
        done = 0
        try:
            for row in rows:
                name = safe_filename(row["title"])
                if name.lower() in used:
                    name = f"{name} ({row['id']})"
                used.add(name.lower())
                with open(os.path.join(folder, name + ".md"), "w", encoding="utf-8") as fh:
                    fh.write(note_to_markdown(row["title"], row["body"], row["tags"]))
                done += 1
        except OSError as e:
            messagebox.showerror(APP_NAME, f"Экспорт остановлен на {done} из {len(rows)}:\n{e}", parent=self.tempo)
        self.set_status(f"Экспортировано конспектов: {done} → {folder}")

    def import_konspektor(self):
        start = konspektor_sources()
        path = filedialog.askopenfilename(parent=self.tempo, title="База Конспектора",
                                          initialdir=str(start[0].parent) if start else str(Path.home()),
                                          filetypes=[("База SQLite", "*.db"), ("Все файлы", "*.*")])
        if not path:
            return
        if Path(path).resolve() == self.store.path.resolve():
            messagebox.showerror(APP_NAME, "Это и есть текущая база.", parent=self.tempo)
            return
        try:
            n = self.store.import_db(path)
        except (sqlite3.Error, KeyError, IndexError) as e:
            messagebox.showerror(APP_NAME, f"Не удалось прочитать базу: {e}", parent=self.tempo)
            return
        self.notes.refresh_list()
        self.maps.refresh_list()
        self.cards.refresh(restart=True)
        self.tempo.toast(f"Добавлено: конспектов {n['notes']}, карт {n['maps']}, карточек {n['cards']} "
                         f"(повторений {n['reviews']}). Повторы пропущены.", ms=9000)

    def backup(self):
        path = filedialog.asksaveasfilename(parent=self.tempo, title="Копия базы конспектов", defaultextension=".db",
                                            initialfile=f"notes-{date.today():%Y-%m-%d}.db",
                                            filetypes=[("База SQLite", "*.db"), ("Все файлы", "*.*")])
        if not path:
            return
        if Path(path).resolve() == self.store.path.resolve():
            messagebox.showerror(APP_NAME, "Выбери другой файл: это сама рабочая база.", parent=self.tempo)
            return
        self.save_all()
        try:
            self.store.backup_to(path)
        except (OSError, sqlite3.Error) as e:
            messagebox.showerror(APP_NAME, f"Не удалось сохранить копию:\n{e}", parent=self.tempo)
            return
        self.set_status(f"Копия сохранена: {path}")

    def edit_limit(self):
        sysm = self.tempo.system

        def save(v):
            sysm.s.setdefault("notes_cfg", {})["new_per_day"] = int(v["n"])
            self.tempo.store.save()
            self.store.new_per_day = int(v["n"])
            self.cards.refresh(restart=True)
        FormDialog(self.tempo, "Новые карточки", [
            {"key": "n", "label": "Новых в день", "kind": "int", "value": self.new_per_day(), "lo": 0, "hi": 500,
             "hint": "остальные новые подождут до завтра: лавина новых убивает привычку повторять"}], save)

    def show_help(self):
        win = tk.Toplevel(self.tempo)
        win.title("Конспекты: клавиши")
        win.configure(bg=C.SURFACE)
        win.transient(self.tempo)
        txt = tk.Text(win, width=78, height=38, font=self.tempo.fonts["mono"], bg=C.SURFACE, fg=C.INK,
                      relief="flat", padx=20, pady=16, highlightthickness=0)
        txt.insert("1.0", KONSPEKT_HELP)
        txt.configure(state="disabled")
        txt.pack(fill="both", expand=True)
        win.bind("<Escape>", lambda e: win.destroy())
        dialog_place(win, self.tempo, 40)
        win.focus_set()


def capture_cards(app, text):
    """Быстрая запись: если все строки — «вопрос :: ответ», это карточки во «Входящие». Вернёт число или 0."""
    lines = [ln for ln in text.splitlines() if ln.strip()]
    if not lines or not all(" :: " in ln and CARD_RE.match(ln) for ln in lines):
        return 0
    pairs = extract_cards("\n".join(lines))
    store = app.notes_store
    n = 0
    for front, back in pairs:
        if store.upsert_card(KONSPEKT_HOME, front, back) == "added":
            n += 1
    v = app.views.get("notes") if getattr(app, "_views_ready", False) else None
    if v is not None:
        v.cards.refresh()
    return n


def fix_russian_shortcuts(root):
    """Ctrl+C/V/X/A/Z/Y в русской раскладке: Tk их не понимает — переводим по физической клавише."""
    events = {"c": "<<Copy>>", "v": "<<Paste>>", "x": "<<Cut>>", "a": "<<SelectAll>>", "z": "<<Undo>>",
              "y": "<<Redo>>"}

    def handler(event):
        ks = event.keysym
        if len(ks) == 1 and ks.isascii():
            return None
        virtual = events.get(KEYCODE_LETTERS.get(event.keycode))
        if virtual:
            event.widget.event_generate(virtual)
            return "break"
        return None

    for cls in ("Text", "Entry", "TEntry", "TCombobox", "TSpinbox", "Spinbox"):
        root.bind_class(cls, "<Control-KeyPress>", handler, add="+")


