def net_defaults():
    return {
        "quota": False, "me_name": "Александр", "me_short": "студент 3 курса совместного бакалавриата ВШЭ и РЭШ",
        "cadence": dict(NET_CADENCE),
        "insights": [], "commitments": [], "opportunities": [],
        "questions": [{"id": _sid(), "aud": a, "cat": c, "text": t, "answer": "", "star": False, "used": 0}
                      for a, c, t in NET_SEED_QUESTIONS],
        "templates": [{"id": _sid(), "name": n, "body": b} for n, b in NET_SEED_TEMPLATES],
    }


def normalize_net(raw):
    base = net_defaults()
    if not isinstance(raw, dict):
        return base
    out = dict(base)
    for k, v in raw.items():
        if k in base and isinstance(v, type(base[k])):
            out[k] = v
    cad = dict(NET_CADENCE)
    for k, v in (raw.get("cadence") or {}).items():
        try:
            cad[str(k)] = max(1, int(v))
        except (TypeError, ValueError):
            pass
    out["cadence"] = cad
    for coll in ("insights", "commitments", "opportunities", "questions", "templates"):
        out[coll] = [x for x in out[coll] if isinstance(x, dict)]
        for x in out[coll]:
            x.setdefault("id", _sid())
    for o in out["opportunities"]:
        o.setdefault("tasks", [])
        o["tasks"] = [t for t in o["tasks"] if isinstance(t, dict)]
        for t in o["tasks"]:
            t.setdefault("id", _sid())
    return out


def normalize_contact(c):
    for key, val in (("company", ""), ("role", ""), ("location", ""), ("linkedin", ""), ("telegram", ""),
                     ("email", ""), ("source", ""), ("segment", ""), ("channel", ""), ("tier", 2), ("status", "Найден"),
                     ("tags", ""), ("notes", ""), ("insight", ""), ("next_step", ""), ("next_date", None),
                     ("introduced_by", None)):
        c.setdefault(key, val)
    c.setdefault("touches", [])
    for t in c["touches"]:
        t.setdefault("id", _sid())
        t.setdefault("dir", "in" if t.get("kind") in NET_TWO_WAY else "out")
    return c


# --- логика ---
def net_cfg(sysm):
    return sysm.s["net"]


def net_cadence(sysm, tier):
    try:
        return int(net_cfg(sysm)["cadence"].get(str(int(tier or 2)), NET_CADENCE["2"]))
    except (TypeError, ValueError):
        return 30


def net_contact(sysm, cid):
    return next((c for c in sysm.s["contacts"] if c.get("id") == cid), None)


def net_last_touch(c):
    ts = [t for t in c.get("touches") or [] if sys_date(t.get("date"))]
    return max(ts, key=lambda t: (t.get("date") or "", c["touches"].index(t))) if ts else None


def net_advance(c, kind, direction):
    cur = c.get("status") if c.get("status") in SYS_STATUSES else "Найден"
    if kind in ("Созвон", "Встреча"):
        new = "Созвон проведён"
    elif direction == "in" and kind != "Заметка":
        new = "Ответил"
    else:
        new = {"Инвайт": "Инвайт", "Сообщение": "Написал", "Письмо": "Написал", "Фоллоу-ап": "Написал",
               "Рекомендация": "Тёплый контакт"}.get(kind)
    if not new:
        return
    if cur in ("Затих", "Отказ") or SYS_STATUSES.index(new) > SYS_STATUSES.index(cur):
        c["status"] = new


def net_recompute(sysm, c, today=None):
    """Следующее касание: от последнего касания через каденс приоритета; без ответа — через неделю."""
    if c.get("status") == "Отказ":
        c["next_date"] = None
        return
    last = net_last_touch(c)
    base = sys_date(last.get("date")) if last else (today or sysm.app.today())
    step = net_cadence(sysm, c.get("tier"))
    if last and last.get("dir") == "out" and c.get("status") in ("Инвайт", "Написал", "Нет ответа"):
        step = min(step, 8)
    c["next_date"] = (base + timedelta(days=step)).isoformat()


def net_touch(sysm, c, day, kind="Сообщение", direction="out", channel=None, note="", notes="", next_date=None,
              status=None, next_step=None):
    """Записать касание: стадия и следующее касание считаются сами (если их не задали руками)."""
    normalize_contact(c)
    t = {"id": _sid(), "date": day.isoformat(), "kind": kind, "dir": direction,
         "channel": channel or c.get("channel") or "", "note": note or "", "notes": notes or ""}
    c["touches"].append(t)
    if status:
        c["status"] = status
    else:
        net_advance(c, kind, direction)
    if next_date:
        c["next_date"] = next_date
    elif kind in ("Созвон", "Встреча") and c.get("status") == "Созвон проведён":
        c["next_date"] = (day + timedelta(days=1)).isoformat()
        c["next_step"] = next_step or "Благодарность и просьба о 1–2 контактах"
    else:
        net_recompute(sysm, c, day)
    if next_step is not None and next_step != "":
        c["next_step"] = next_step
    elif kind not in NET_TWO_WAY and c.get("status") in ("Написал", "Инвайт") and not c.get("next_step"):
        c["next_step"] = "Напоминание, если нет ответа"
    c["updated"] = datetime.now().isoformat(timespec="seconds")
    sysm.invalidate()
    return t


def net_lines(text):
    out = []
    for raw in (text or "").splitlines():
        s = raw.strip().lstrip("-•*").strip()
        if s:
            out.append(s)
    return out


def net_split_topic(line, default):
    """«найм: берут через стажировки» → ("Найм", "берут через стажировки")."""
    m = re.match(r"^\s*([^:]{2,24}):\s*(.+)$", line)
    if m:
        head = m.group(1).strip().lower()
        for t in NET_TOPICS:
            if t.lower().startswith(head):
                return t, m.group(2).strip()
    return default, line


def net_parse_ref(line):
    """«Иван Петров — Citadel, quant researcher» → имя, компания, роль."""
    parts = re.split(r"\s+[—–-]\s+", line, maxsplit=1)
    name = parts[0].strip()
    rest = parts[1].strip() if len(parts) > 1 else ""
    company, _, role = rest.partition(",")
    return name, company.strip(), role.strip()


def net_add_insights(sysm, cid, tid, text, topic, day, star=False):
    n = 0
    for line in net_lines(text):
        tp, body = net_split_topic(line, topic)
        net_cfg(sysm)["insights"].append({"id": _sid(), "contact": cid, "touch": tid, "topic": tp, "text": body,
                                          "star": bool(star), "date": day.isoformat()})
        n += 1
    return n


def net_new_contact(sysm, name, **fields):
    c = normalize_contact({"id": _sid(), "name": name.strip(), "created": sysm.app.today().isoformat(),
                           "touches": []})
    c.update({k: v for k, v in fields.items() if v is not None})
    sysm.s["contacts"].append(c)
    sysm.invalidate()
    return c


def net_due(sysm, horizon_days=0):
    today = sysm.app.today()
    lim = (today + timedelta(days=horizon_days)).isoformat()
    rows = [c for c in sysm.s["contacts"] if c.get("next_date") and c["next_date"] <= lim
            and c.get("status") != "Отказ"]
    rows.sort(key=lambda c: (int(c.get("tier") or 2), c["next_date"]))
    return rows


def net_open_commitments(sysm, who=None):
    rows = [m for m in net_cfg(sysm)["commitments"] if not m.get("done") and (who is None or m.get("who") == who)]
    rows.sort(key=lambda m: (m.get("due") is None, m.get("due") or ""))
    return rows


def net_open_opps(sysm):
    return [o for o in net_cfg(sysm)["opportunities"] if o.get("stage") not in OPP_CLOSED]


def due_label(due_iso, today):
    d = sys_date(due_iso)
    if d is None:
        return "без срока"
    n = (d - today).days
    if n < 0:
        return f"просрочено на {-n} д"
    if n == 0:
        return "сегодня"
    if n == 1:
        return "завтра"
    return f"через {n} д"


def import_netcrm(sysm, path):
    """Перенести базу netapp / netcrm (SQLite) в Сеть Генштаба. Повторы по имени и тексту пропускаются."""
    net = net_cfg(sysm)
    src = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
    src.row_factory = sqlite3.Row
    counts = defaultdict(int)
    try:
        tables = {r[0] for r in src.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        ids = {}
        by_name = {c.get("name", "").lower(): c for c in sysm.s["contacts"]}
        if "contacts" in tables:
            cols = {r[1] for r in src.execute("PRAGMA table_info(contacts)")}
            for r in src.execute("SELECT * FROM contacts"):
                c = by_name.get((r["name"] or "").lower())
                if c is None:
                    c = net_new_contact(sysm, r["name"] or "без имени",
                                        company=r["company"] or "", role=r["role"] or "", location=r["location"] or "",
                                        linkedin=r["linkedin"] or "", email=r["email"] or "",
                                        telegram=r["telegram"] or "", source=r["source"] or "",
                                        tier=int(r["tier"] or 2), status=NETCRM_STAGES.get(r["stage"], "Найден"),
                                        tags=r["tags"] or "", notes=r["notes"] or "", next_date=r["next_due"])
                    counts["contacts"] += 1
                    by_name[c["name"].lower()] = c
                ids[r["id"]] = c
            if "introduced_by" in cols:
                for r in src.execute("SELECT id, introduced_by FROM contacts WHERE introduced_by IS NOT NULL"):
                    if r["id"] in ids and r["introduced_by"] in ids:
                        ids[r["id"]]["introduced_by"] = ids[r["introduced_by"]]["id"]
        tids = {}
        if "touches" in tables:
            tcols = {r[1] for r in src.execute("PRAGMA table_info(touches)")}
            for r in src.execute("SELECT * FROM touches ORDER BY happened_on, id"):
                c = ids.get(r["contact_id"])
                if c is None:
                    continue
                t = {"id": _sid(), "date": r["happened_on"], "kind": NETCRM_KINDS.get(r["kind"], "Сообщение"),
                     "dir": r["direction"] if r["direction"] in ("in", "out") else "out",
                     "channel": NETCRM_CHANNELS.get((r["channel"] or "").lower(), r["channel"] or ""),
                     "note": r["summary"] or "", "notes": r["notes"] if "notes" in tcols else ""}
                if any(x.get("date") == t["date"] and x.get("kind") == t["kind"] and x.get("note") == t["note"]
                       for x in c["touches"]):
                    continue
                c["touches"].append(t)
                tids[r["id"]] = t["id"]
                counts["touches"] += 1
        if "insights" in tables:
            have = {(i.get("text"), i.get("contact")) for i in net["insights"]}
            for r in src.execute("SELECT * FROM insights"):
                c = ids.get(r["contact_id"])
                key = (r["text"], c["id"] if c else None)
                if key in have:
                    continue
                net["insights"].append({"id": _sid(), "contact": key[1], "touch": tids.get(r["touch_id"]),
                                        "topic": r["topic"] or "Другое", "text": r["text"], "star": bool(r["starred"]),
                                        "date": r["created_on"] or sysm.app.today().isoformat()})
                counts["insights"] += 1
        if "questions" in tables:
            have = {(q.get("aud"), q.get("text")) for q in net["questions"]}
            for r in src.execute("SELECT * FROM questions"):
                key = (r["audience"], r["text"])
                old = next((q for q in net["questions"] if (q.get("aud"), q.get("text")) == key), None)
                if old is not None:
                    if r["answer"] and not old.get("answer"):
                        old["answer"] = r["answer"]
                    old["used"] = max(int(old.get("used") or 0), int(r["times_used"] or 0))
                    old["star"] = bool(old.get("star") or r["starred"])
                    continue
                net["questions"].append({"id": _sid(), "aud": r["audience"], "cat": r["category"] or "",
                                         "text": r["text"], "answer": r["answer"] or "", "star": bool(r["starred"]),
                                         "used": int(r["times_used"] or 0)})
                have.add(key)
                counts["questions"] += 1
        if "commitments" in tables:
            have = {(m.get("contact"), m.get("who"), m.get("text")) for m in net["commitments"]}
            for r in src.execute("SELECT * FROM commitments"):
                c = ids.get(r["contact_id"])
                key = (c["id"] if c else None, r["who"], r["text"])
                if key in have:
                    continue
                have.add(key)
                net["commitments"].append({"id": _sid(), "contact": c["id"] if c else None, "who": r["who"],
                                           "text": r["text"], "due": r["due"], "done": bool(r["done"]),
                                           "created": r["created_on"]})
                counts["commitments"] += 1
        if "opportunities" in tables:
            have = {(o.get("title"), o.get("org")) for o in net["opportunities"]}
            oids = {}
            for r in src.execute("SELECT * FROM opportunities"):
                if (r["title"], r["org"]) in have:
                    continue
                o = {"id": _sid(), "title": r["title"], "org": r["org"] or "", "kind": r["kind"] or "other",
                     "url": r["url"] or "", "deadline": r["deadline"], "stage": r["stage"] or "watch",
                     "priority": int(r["priority"] or 2), "notes": r["notes"] or "",
                     "created": r["created_at"], "tasks": []}
                net["opportunities"].append(o)
                oids[r["id"]] = o
                counts["opportunities"] += 1
            if "opp_tasks" in tables:
                for r in src.execute("SELECT * FROM opp_tasks"):
                    if r["opp_id"] in oids:
                        oids[r["opp_id"]]["tasks"].append({"id": _sid(), "title": r["title"], "due": r["due"],
                                                           "done": bool(r["done"])})
        if "templates" in tables:
            have = {t.get("name") for t in net["templates"]}
            for r in src.execute("SELECT * FROM templates"):
                if r["name"] in have:
                    continue
                net["templates"].append({"id": _sid(), "name": r["name"], "body": r["body"]})
                counts["templates"] += 1
        if "settings" in tables:
            st = {r["key"]: r["value"] for r in src.execute("SELECT key, value FROM settings")}
            if st.get("me_name"):
                net["me_name"] = st["me_name"]
            if st.get("me_short"):
                net["me_short"] = st["me_short"]
            for t in ("1", "2", "3"):
                if st.get(f"cad_{t}"):
                    try:
                        net["cadence"][t] = max(1, int(st[f"cad_{t}"]))
                    except ValueError:
                        pass
    finally:
        src.close()
    sysm.invalidate()
    return dict(counts)


def netcrm_source():
    p = Path(os.environ.get("NETCRM_DB") or Path.home() / ".netcrm" / "netcrm.db").expanduser()
    return p if p.exists() else None


def import_linkedin(sysm, text, tier):
    lines = text.splitlines()
    start = next((i for i, l in enumerate(lines) if l.lower().startswith("first name")), 0)
    reader = csv.DictReader(io.StringIO("\n".join(lines[start:])))
    have = {c.get("linkedin") for c in sysm.s["contacts"] if c.get("linkedin")}
    added = skipped = 0
    for row in reader:
        name = f"{(row.get('First Name') or '').strip()} {(row.get('Last Name') or '').strip()}".strip()
        if not name:
            continue
        li = (row.get("URL") or "").strip()
        if li and li in have:
            skipped += 1
            continue
        net_new_contact(sysm, name, company=(row.get("Company") or "").strip(),
                        role=(row.get("Position") or "").strip(), linkedin=li,
                        email=(row.get("Email Address") or "").strip(), source="LinkedIn", tier=tier,
                        status="В контактах", channel="LinkedIn",
                        notes=f"в контактах с {row.get('Connected On', '')}".strip())
        have.add(li)
        added += 1
    return added, skipped


def export_net_csv(sysm, folder):
    folder = Path(folder)
    net = net_cfg(sysm)
    names = {c["id"]: c.get("name", "") for c in sysm.s["contacts"]}
    tables = {
        "люди.csv": (["Имя", "Компания", "Роль", "Город", "Приоритет", "Стадия", "Сегмент", "Канал", "LinkedIn",
                      "Telegram", "Email", "Откуда", "Теги", "Следующее касание", "Следующий шаг", "Главный вывод",
                      "Заметки"],
                     [[c.get("name"), c.get("company"), c.get("role"), c.get("location"), f"T{c.get('tier', 2)}",
                       c.get("status"), c.get("segment"), c.get("channel"), c.get("linkedin"), c.get("telegram"),
                       c.get("email"), c.get("source"), c.get("tags"), c.get("next_date"), c.get("next_step"),
                       c.get("insight"), c.get("notes")] for c in sysm.s["contacts"]]),
        "касания.csv": (["Человек", "Дата", "Вид", "Направление", "Канал", "Коротко", "Заметки"],
                        [[c.get("name"), t.get("date"), t.get("kind"), NET_DIRS.get(t.get("dir"), ""), t.get("channel"),
                          t.get("note"), t.get("notes")] for c in sysm.s["contacts"] for t in c.get("touches") or []]),
        "что_узнал.csv": (["Дата", "Тема", "Текст", "От кого", "Важное"],
                          [[i.get("date"), i.get("topic"), i.get("text"), names.get(i.get("contact"), ""),
                            "да" if i.get("star") else ""] for i in net["insights"]]),
        "обязательства.csv": (["Кто", "Что", "Человек", "Срок", "Сделано"],
                         [["я" if m.get("who") == "me" else "он/она", m.get("text"), names.get(m.get("contact"), ""),
                           m.get("due"), "да" if m.get("done") else ""] for m in net["commitments"]]),
        "возможности.csv": (["Что", "Где", "Тип", "Стадия", "Дедлайн", "Приоритет", "Ссылка", "Заметки"],
                            [[o.get("title"), o.get("org"), OPP_KINDS.get(o.get("kind"), ""),
                              OPP_STAGES.get(o.get("stage"), ""), o.get("deadline"), f"P{o.get('priority', 2)}",
                              o.get("url"), o.get("notes")] for o in net["opportunities"]]),
        "вопросы.csv": (["Кто спрашивает", "Категория", "Вопрос", "Ответ", "Важный", "Задавал"],
                        [["я" if q.get("aud") == "ask" else "меня", q.get("cat"), q.get("text"), q.get("answer"),
                          "да" if q.get("star") else "", q.get("used", 0)] for q in net["questions"]]),
    }
    for name, (head, rows) in tables.items():
        with open(folder / name, "w", newline="", encoding="utf-8-sig") as f:
            w = csv.writer(f, delimiter=";")
            w.writerow(head)
            w.writerows(rows)
    return list(tables)


class _Safe(dict):
    def __missing__(self, k):
        return "{" + k + "}"


# ───────── окно раздела ─────────

class NetworkView(tk.Frame):
    """Сеть: люди, разговоры, что узнал, вопросы, обязательства, возможности, шаблоны."""

    TABS = [("today", "Сегодня"), ("people", "Люди"), ("call", "Разговор"), ("insights", "Что узнал"),
            ("questions", "Вопросы"), ("opps", "Возможности"), ("templates", "Шаблоны")]

    def __init__(self, master, app):
        super().__init__(master, bg=C.BG)
        self.app = app
        F, px = app.fonts, app.px
        tab = app.store.settings.get("net_tab")
        self.tab = tab if tab in dict(self.TABS) else "today"
        self.sel = None          # выбранный человек
        self.call_contact = None
        self.horizon = 3
        self.q_aud = "ask"
        self.opp_sel = None
        self.tpl_sel = None
        self.ins_group = "topic"
        self.people_filter = {"q": "", "stage": "Все", "tier": "Все"}
        self._call_ui = None      # поля открытой формы «Разговор»
        self._drafts = {}         # недописанные разговоры по людям: переживают обновление экрана
        self._call_asked = {}     # отмеченные вопросы по людям
        wrap = tk.Frame(self, bg=C.BG)
        wrap.pack(fill="both", expand=True, padx=px(28), pady=(px(22), px(8)))
        head = tk.Frame(wrap, bg=C.BG)
        head.pack(fill="x")
        tk.Label(head, text="Связи", font=F["h1"], bg=C.BG, fg=C.INK).pack(side="left")
        self.kpi = tk.Label(head, text="", font=F["ui"], bg=C.BG, fg=C.MUTED)
        self.kpi.pack(side="left", padx=(px(14), 0), pady=(px(6), 0))
        ttk.Button(head, text="Новый человек", style="Work.TButton", command=lambda: app.edit_contact(None)).pack(
            side="right")
        ttk.Button(head, text="Касание", command=lambda: app.quick_touch()).pack(side="right", padx=px(6))
        data_btn = ttk.Menubutton(head, text="Данные")
        m = tk.Menu(data_btn, tearoff=False)
        m.add_command(label="О себе, частота касаний, квота…", command=self.edit_settings)
        m.add_command(label="Пересчитать сроки касаний у всех", command=self.recompute_all)
        m.add_separator()
        m.add_command(label="Импорт контактов LinkedIn (Connections.csv)…", command=self.import_li)
        m.add_command(label="Перенести базу netapp (netcrm.db)…", command=self.import_db)
        m.add_command(label="Выгрузить всё в CSV…", command=self.export_csv)
        data_btn["menu"] = m
        data_btn.pack(side="right")
        self.seg = Segmented(wrap, app, self.TABS, self.set_tab)
        self.seg.pack(anchor="w", pady=(px(10), px(10)))
        self.page = tk.Frame(wrap, bg=C.BG)
        self.page.pack(fill="both", expand=True)

    # --- навигация ---
    def set_tab(self, key):
        self.tab = key
        self.app.store.settings["net_tab"] = key
        if self.app.current_view != "network":
            self.app._goto("network")
        else:
            self.refresh()

    def on_show(self):
        self.refresh()

    def open_call(self, cid):
        self.call_contact = cid
        self.set_tab("call")

    def open_person(self, cid):
        self.sel = cid
        self.set_tab("people")

    def _snapshot_call(self):
        """Запоминает недописанную форму «Разговор», чтобы перестройка экрана её не стёрла."""
        ui, self._call_ui = self._call_ui, None
        if not ui:
            return
        try:
            texts = {k: t.get("1.0", "end-1c") for k, t in ui["texts"].items()}
            vals = {k: v.get() for k, v in ui["vars"].items()}
        except tk.TclError:
            return
        if any(x.strip() for x in texts.values()) or vals != ui["init"]:
            self._drafts[ui["cid"]] = {"texts": texts, "vars": vals}
        else:
            self._drafts.pop(ui["cid"], None)

    def refresh(self):
        sysm = self.app.system
        self._snapshot_call()
        for w in self.page.winfo_children():
            w.destroy()
        self.seg.set(self.tab, C.FOCUS)
        contacts = sysm.s["contacts"]
        warm = sum(1 for c in contacts if c.get("status") in ("Ответил", "Созвон назначен", "Созвон проведён",
                                                              "Тёплый контакт"))
        today = self.app.today()
        week_ago = today - timedelta(days=7)
        out7 = sum(1 for c in contacts for t in c.get("touches") or []
                   if t.get("dir") == "out" and (sys_date(t.get("date")) or date.min) >= week_ago)
        reached = [c for c in contacts if any(t.get("dir") == "out" for t in c.get("touches") or [])]
        replied = [c for c in reached if any(t.get("dir") == "in" for t in c.get("touches") or [])]
        parts = [f"тёплых {warm} из {len(contacts)}", f"написал за неделю {out7}",
                 f"отвечают {len(replied) * 100 // len(reached)}%" if reached else "отвечают —",
                 f"инсайтов {len(net_cfg(sysm)['insights'])}"]
        if sysm.quota():
            parts.insert(0, f"касаний {sysm.touches_total()} из {int(sysm.goal('touches', 500))}")
        self.kpi.configure(text=" · ".join(parts))
        getattr(self, "_tab_" + self.tab)()

    def _scroll(self):
        sf = ScrollFrame(self.page)
        sf.pack(fill="both", expand=True)
        return sf.inner

    def _tree(self, parent, cols, height=10, select="browse"):
        px = self.app.px
        frame = tk.Frame(parent, bg=C.LINE, padx=1, pady=1)
        tree = ttk.Treeview(frame, columns=[c[0] for c in cols], show="headings", selectmode=select, height=height)
        for key, text, w, stretch in cols:
            tree.heading(key, text=text, anchor="w")
            tree.column(key, width=px(w), minwidth=px(40), anchor="w", stretch=stretch)
        sb = ttk.Scrollbar(frame, orient="vertical", command=tree.yview)
        tree.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        tree.pack(side="left", fill="both", expand=True)
        tree.tag_configure("due", foreground=C.DANGER)
        tree.tag_configure("muted", foreground=C.MUTED)
        tree.tag_configure("warm", foreground=C.BREAK)
        tree.tag_configure("group", font=self.app.fonts["ui_bold"], background=C.SOFT)
        tree.tag_configure("star", foreground=C.LONG)
        return frame, tree

    def _h2(self, parent, text, link=None, command=None):
        F, px = self.app.fonts, self.app.px
        row = tk.Frame(parent, bg=parent.cget("bg"))
        row.pack(fill="x", pady=(px(10), px(4)))
        tk.Label(row, text=text, font=F["h2"], bg=row.cget("bg"), fg=C.INK).pack(side="left")
        if link:
            ui_link(row, self.app, link, command).pack(side="right", pady=(px(4), 0))
        return row

    def _changed(self, msg=None):
        self.app._sys_changed(msg)

    # ───────── Сегодня ─────────
    def _tab_today(self):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        body = self._scroll()
        today = app.today()
        row = self._h2(body, "Кому написать")
        seg = Segmented(row, app, [(0, "сегодня"), (3, "3 дня"), (7, "неделя"), (14, "2 недели")],
                        lambda k: (setattr(self, "horizon", k), self.refresh()))
        seg.pack(side="right")
        seg.set(self.horizon, C.FOCUS)
        due = net_due(sysm, self.horizon)
        if not due:
            ui_text(body, app, "В этом горизонте никого. Добавь людей во вкладке «Люди» или расширь горизонт.").pack(
                fill="x")
        else:
            frame, tree = self._tree(body, [("name", "Кто", 220, True), ("where", "Где", 200, True),
                                            ("stage", "Стадия", 140, False), ("last", "Последнее", 260, True),
                                            ("when", "Когда", 120, False)], height=min(10, len(due)))
            frame.pack(fill="x")
            for c in due:
                last = net_last_touch(c)
                tree.insert("", "end", iid=c["id"], tags=("due",) if c["next_date"] <= today.isoformat() else (),
                            values=(f"{c.get('name')} · T{c.get('tier', 2)}", c.get("company") or "—",
                                    c.get("status"),
                                    (f"{sys_date(last['date']):%d.%m} {last.get('kind', '').lower()}: "
                                     f"{last.get('note') or '—'}") if last else "ещё не писал",
                                    due_label(c["next_date"], today)))
            acts = tk.Frame(body, bg=C.BG)
            acts.pack(fill="x", pady=(px(6), 0))

            def sel():
                s = tree.selection()
                return net_contact(sysm, s[0]) if s else None

            def act(fn):
                c = sel()
                if c is None:
                    app.toast("Выбери человека в списке")
                    return
                fn(c)
            ttk.Button(acts, text="Разговор", command=lambda: act(lambda c: self.open_call(c["id"]))).pack(side="left")
            ttk.Button(acts, text="Написал", command=lambda: act(self._wrote)).pack(side="left", padx=px(6))
            ttk.Button(acts, text="Через неделю", command=lambda: act(lambda c: self._snooze(c, 7))).pack(side="left")
            ttk.Button(acts, text="Карточка", command=lambda: act(lambda c: self.open_person(c["id"]))).pack(
                side="left", padx=px(6))
            tree.bind("<Double-1>", lambda e: act(lambda c: self.open_person(c["id"])))

        cols = tk.Frame(body, bg=C.BG)
        cols.pack(fill="x", pady=(px(8), 0))
        cols.columnconfigure(0, weight=1, uniform="p")
        cols.columnconfigure(1, weight=1, uniform="p")
        names = {c["id"]: c.get("name", "") for c in sysm.s["contacts"]}
        for i, (who, title, empty) in enumerate((("me", "Я обещал", "Долгов нет."),
                                                 ("them", "Жду от них", "Ничего не жду."))):
            box = tk.Frame(cols, bg=C.BG)
            box.grid(row=0, column=i, sticky="nsew", padx=(0, px(8)) if i == 0 else 0)
            self._h2(box, title)
            ms = net_open_commitments(sysm, who)
            if not ms:
                ui_text(box, app, empty).pack(fill="x")
            for m in ms[:12]:
                r = tk.Frame(box, bg=C.BG)
                r.pack(fill="x")
                late = m.get("due") and m["due"] < today.isoformat()
                ui_link(r, app, "сделано", lambda mm=m: self._commit_done(mm), fg=C.MUTED).pack(side="right")
                ui_text(r, app, f"{m.get('text')} — {names.get(m.get('contact')) or 'без человека'}, "
                                f"{due_label(m.get('due'), today)}", fg=C.DANGER if late else C.INK).pack(
                    side="left", fill="x", expand=True)

        self._h2(body, "Дедлайны на месяц", "все возможности", lambda: self.set_tab("opps"))
        lim = (today + timedelta(days=30)).isoformat()
        opps = sorted((o for o in net_open_opps(sysm) if o.get("deadline") and o["deadline"] <= lim),
                      key=lambda o: o["deadline"])
        if not opps:
            ui_text(body, app, "Ближайший месяц свободен.").pack(fill="x")
        for o in opps:
            ui_text(body, app, f"{o.get('title')}, {o.get('org') or 'без организации'}: {sys_date(o['deadline']):%d.%m}, "
                               f"{due_label(o['deadline'], today)} ({OPP_STAGES.get(o.get('stage'), '')})",
                    fg=C.DANGER if o["deadline"] <= (today + timedelta(days=7)).isoformat() else C.INK).pack(fill="x")
        tasks = [(o, t) for o in net_open_opps(sysm) for t in o.get("tasks") or []
                 if not t.get("done") and t.get("due") and t["due"] <= (today + timedelta(days=7)).isoformat()]
        if tasks:
            tk.Label(body, text="Задачи на неделю", font=F["ui_bold"], bg=C.BG, fg=C.INK).pack(anchor="w",
                                                                                            pady=(px(6), 0))
            for o, t in sorted(tasks, key=lambda x: x[1]["due"]):
                r = tk.Frame(body, bg=C.BG)
                r.pack(fill="x")
                ui_link(r, app, "сделано", lambda tt=t: self._task_done(tt), fg=C.MUTED).pack(side="right")
                ui_text(r, app, f"{t.get('title')} ({o.get('title')}), {due_label(t['due'], today)}",
                        fg=C.INK).pack(side="left", fill="x", expand=True)

        self._h2(body, "Последнее, что узнал", "всё", lambda: self.set_tab("insights"))
        recent = list(reversed(net_cfg(sysm)["insights"]))[:6]
        if not recent:
            ui_text(body, app, "Пока пусто. Записывай после каждого разговора — во вкладке «Разговор» или быстрым "
                               "вводом: «узнал: найм: у них всё через летнюю стажировку».").pack(fill="x")
        for i in recent:
            ui_text(body, app, f"{i.get('topic')}: {i.get('text')} — {names.get(i.get('contact')) or 'без автора'}",
                    fg=C.INK).pack(fill="x")

    def _wrote(self, c):
        net_touch(self.app.system, c, self.app.today(), "Сообщение", "out", note="написал")
        self._changed("Касание записано")

    def _snooze(self, c, days):
        c["next_date"] = (self.app.today() + timedelta(days=days)).isoformat()
        self._changed(f"{c.get('name')}: через {days} дней")

    def _commit_done(self, m):
        m["done"] = True
        m["done_at"] = self.app.today().isoformat()
        self._changed("Обязательство закрыто")

    def _task_done(self, t):
        t["done"] = True
        self._changed("Задача закрыта")

    # ───────── Люди ─────────
    def _tab_people(self):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        today = app.today()
        bar = tk.Frame(self.page, bg=C.BG)
        bar.pack(fill="x", pady=(0, px(8)))
        q_var = tk.StringVar(value=self.people_filter["q"])
        tk.Label(bar, text="Поиск", font=F["small"], bg=C.BG, fg=C.MUTED).pack(side="left")
        e = ttk.Entry(bar, textvariable=q_var, font=F["ui"], width=24)
        e.pack(side="left", padx=(px(6), px(14)))
        tk.Label(bar, text="Стадия", font=F["small"], bg=C.BG, fg=C.MUTED).pack(side="left")
        st_var = tk.StringVar(value=self.people_filter["stage"])
        ttk.Combobox(bar, textvariable=st_var, values=["Все", "В работе"] + list(SYS_STATUSES), state="readonly",
                     width=18, font=F["ui"]).pack(side="left", padx=(px(6), px(14)))
        tk.Label(bar, text="Приоритет", font=F["small"], bg=C.BG, fg=C.MUTED).pack(side="left")
        tier_var = tk.StringVar(value=self.people_filter["tier"])
        ttk.Combobox(bar, textvariable=tier_var, values=["Все", "T1", "T2", "T3"], state="readonly", width=6,
                     font=F["ui"]).pack(side="left", padx=px(6))

        pane = tk.Frame(self.page, bg=C.BG)
        pane.pack(fill="both", expand=True)
        pane.columnconfigure(0, weight=5, uniform="pp")
        pane.columnconfigure(1, weight=4, uniform="pp")
        pane.rowconfigure(0, weight=1)
        frame, tree = self._tree(pane, [("name", "Имя", 150, True), ("company", "Компания", 120, True),
                                        ("tier", "T", 36, False), ("stage", "Стадия", 140, False),
                                        ("n", "Касаний", 76, False), ("when", "Следующее", 120, False)],
                                 height=18)
        frame.grid(row=0, column=0, sticky="nsew", padx=(0, px(10)))
        detail_sf = ScrollFrame(pane)
        detail_sf.grid(row=0, column=1, sticky="nsew")
        detail = detail_sf.inner

        def fill():
            self.people_filter.update(q=q_var.get(), stage=st_var.get(), tier=tier_var.get())
            q = q_var.get().strip().lower()
            tree.delete(*tree.get_children())
            rows = []
            for c in sysm.s["contacts"]:
                if q and q not in " ".join(str(c.get(k) or "") for k in ("name", "company", "role", "tags", "source",
                                                                         "segment", "notes")).lower():
                    continue
                if st_var.get() == "В работе" and c.get("status") == "Отказ":
                    continue
                if st_var.get() not in ("Все", "В работе") and c.get("status") != st_var.get():
                    continue
                if tier_var.get() != "Все" and f"T{c.get('tier', 2)}" != tier_var.get():
                    continue
                rows.append(c)
            rows.sort(key=lambda c: (c.get("next_date") is None, c.get("next_date") or "", c.get("name", "").lower()))
            for c in rows:
                due = c.get("next_date") and c["next_date"] <= today.isoformat() and c.get("status") != "Отказ"
                tag = "due" if due else ("muted" if c.get("status") == "Отказ" else
                                         ("warm" if c.get("status") == "Тёплый контакт" else ""))
                tree.insert("", "end", iid=c["id"], tags=(tag,) if tag else (), values=(
                    c.get("name"), c.get("company") or "", f"T{c.get('tier', 2)}", c.get("status"),
                    sum(1 for t in c.get("touches") or [] if t.get("kind") != "Заметка"),
                    due_label(c.get("next_date"), today) if c.get("next_date") else ""))
            if self.sel and tree.exists(self.sel):
                tree.selection_set(self.sel)
                tree.see(self.sel)
            elif rows:
                tree.selection_set(rows[0]["id"])
            if not sysm.s["contacts"]:
                for w in detail.winfo_children():
                    w.destroy()
                ui_text(detail, app, "База пустая. «Новый человек» — добавить вручную, «Данные» → импорт контактов "
                                     "LinkedIn или перенос базы netapp.").pack(fill="x")

        def on_sel(_e=None):
            s = tree.selection()
            if s:
                self.sel = s[0]
                self._person_card(detail, net_contact(sysm, s[0]))
        tree.bind("<<TreeviewSelect>>", on_sel)
        tree.bind("<Double-1>", lambda e: self.sel and app.edit_contact(net_contact(sysm, self.sel)))
        tree.bind("<Return>", lambda e: self.sel and app.add_touch(net_contact(sysm, self.sel)))
        for v in (q_var, st_var, tier_var):
            v.trace_add("write", lambda *a: fill())
        fill()
        on_sel()

    def _person_card(self, parent, c):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        for w in parent.winfo_children():
            w.destroy()
        if c is None:
            return
        normalize_contact(c)
        today = app.today()
        tk.Label(parent, text=c.get("name"), font=F["h2"], bg=C.BG, fg=C.INK, anchor="w").pack(fill="x")
        meta = ", ".join(s for s in (c.get("role"), c.get("company"), c.get("location")) if s)
        if meta:
            ui_text(parent, app, meta, fg=C.INK).pack(fill="x")
        ui_text(parent, app, f"T{c.get('tier', 2)} (раз в {net_cadence(sysm, c.get('tier'))} дн.), {c.get('status')}. "
                             f"Следующее касание: {due_label(c.get('next_date'), today)}"
                             + (f" — {c['next_step']}" if c.get("next_step") else "")).pack(fill="x")
        links = tk.Frame(parent, bg=C.BG)
        links.pack(fill="x", pady=(px(2), 0))
        if c.get("linkedin"):
            ui_link(links, app, "LinkedIn", lambda u=c["linkedin"]: webbrowser.open(u)).pack(side="left",
                                                                                          padx=(0, px(10)))
        if c.get("telegram"):
            tg = c["telegram"] if c["telegram"].startswith("http") else f"https://t.me/{c['telegram'].lstrip('@')}"
            ui_link(links, app, "Telegram", lambda u=tg: webbrowser.open(u)).pack(side="left", padx=(0, px(10)))
        if c.get("email"):
            ui_link(links, app, c["email"], lambda u=c["email"]: webbrowser.open("mailto:" + u)).pack(side="left")
        intro = net_contact(sysm, c.get("introduced_by")) if c.get("introduced_by") else None
        if intro:
            ui_text(parent, app, f"Познакомил(а): {intro.get('name')}").pack(fill="x")
        referred = [x.get("name") for x in sysm.s["contacts"] if x.get("introduced_by") == c["id"]]
        if referred:
            ui_text(parent, app, "Через него/неё: " + ", ".join(referred)).pack(fill="x")
        if c.get("source"):
            ui_text(parent, app, f"Откуда: {c['source']}").pack(fill="x")
        acts = tk.Frame(parent, bg=C.BG)
        acts.pack(fill="x", pady=(px(8), px(4)))
        ttk.Button(acts, text="Разговор", style="Work.TButton", command=lambda: self.open_call(c["id"])).pack(
            side="left")
        ttk.Button(acts, text="Касание", command=lambda: app.add_touch(c)).pack(side="left", padx=px(6))
        ttk.Button(acts, text="Изменить", command=lambda: app.edit_contact(c)).pack(side="left")
        ttk.Button(acts, text="Шаблон", command=lambda: (setattr(self, "tpl_contact", c["id"]),
                                                          self.set_tab("templates"))).pack(side="left", padx=px(6))
        if c.get("insight"):
            ui_text(parent, app, "Главный вывод: " + c["insight"], fg=C.INK).pack(fill="x", pady=(px(4), 0))
        if c.get("notes"):
            ui_text(parent, app, c["notes"], fg=C.INK).pack(fill="x", pady=(px(4), 0))

        self._h2(parent, "Что узнал от него/неё", "добавить", lambda: self.add_insight(c["id"]))
        ins = [i for i in net_cfg(sysm)["insights"] if i.get("contact") == c["id"]]
        if not ins:
            ui_text(parent, app, "Пока ничего.").pack(fill="x")
        for i in reversed(ins[-12:]):
            ui_text(parent, app, f"{'★ ' if i.get('star') else ''}{i.get('topic')}: {i.get('text')}",
                    fg=C.INK).pack(fill="x")

        self._h2(parent, "Обязательства", "добавить", lambda: self.add_commitment(c["id"]))
        ms = [m for m in net_cfg(sysm)["commitments"] if m.get("contact") == c["id"]]
        if not ms:
            ui_text(parent, app, "Нет.").pack(fill="x")
        for m in sorted(ms, key=lambda m: (bool(m.get("done")), m.get("due") or "")):
            r = tk.Frame(parent, bg=C.BG)
            r.pack(fill="x")
            who = "я" if m.get("who") == "me" else "он/она"
            if not m.get("done"):
                ui_link(r, app, "сделано", lambda mm=m: self._commit_done(mm), fg=C.MUTED).pack(side="right")
            ui_text(r, app, f"{who}: {m.get('text')}, {due_label(m.get('due'), today)}" if not m.get("done")
                    else f"{who}: {m.get('text')} — сделано", fg=C.MUTED if m.get("done") else C.INK).pack(
                side="left", fill="x", expand=True)

        self._h2(parent, "История касаний", "убрать последнее", lambda: self._undo_touch(c))
        ts = sorted(c.get("touches") or [], key=lambda t: t.get("date") or "", reverse=True)
        if not ts:
            ui_text(parent, app, "Касаний ещё не было.").pack(fill="x")
        for t in ts[:30]:
            d = sys_date(t.get("date"))
            arrow = "⇄" if t.get("kind") in NET_TWO_WAY else ("→" if t.get("dir") == "out" else "←")
            line = (f"{d:%d.%m.%y} {arrow} {t.get('kind', '').lower()}" + (f", {t['channel']}" if t.get("channel") else "")
                    + (f": {t['note']}" if t.get("note") else ""))
            ui_text(parent, app, line, fg=C.INK).pack(fill="x")
            if t.get("notes"):
                ui_text(parent, app, "    " + one_line(t["notes"], 200)).pack(fill="x")

    def _undo_touch(self, c):
        ts = sorted(c.get("touches") or [], key=lambda t: t.get("date") or "")
        if not ts:
            self.app.toast("Касаний нет")
            return
        last = ts[-1]
        if messagebox.askyesno(APP_NAME, f"Убрать касание {last.get('date')} ({last.get('kind')})?", parent=self.app):
            c["touches"].remove(last)
            net_recompute(self.app.system, c)
            self._changed()

    def add_insight(self, cid=None):
        app, sysm = self.app, self.app.system
        names = {c["id"]: c.get("name", "") for c in sysm.s["contacts"]}
        rev = {v: k for k, v in names.items()}

        def save(v):
            n = net_add_insights(sysm, rev.get(v["who"]), None, v["text"], v["topic"], app.today(), v["star"])
            if not n:
                return False
            self._changed(f"Записано: {n}")
        FormDialog(app, "Что узнал", [
            {"key": "text", "label": "По строке", "kind": "text", "height": 5, "value": "",
             "hint": "можно с темой: «найм: берут только через летнюю стажировку»"},
            {"key": "topic", "label": "Тема для строк без темы", "kind": "combo", "options": NET_TOPICS,
             "value": "Другое"},
            {"key": "who", "label": "От кого", "kind": "combo", "options": [""] + sorted(names.values()),
             "value": names.get(cid, "")},
            {"key": "star", "label": "Важное ★", "kind": "check", "value": False},
        ], save)

    def add_commitment(self, cid=None):
        app, sysm = self.app, self.app.system
        names = {c["id"]: c.get("name", "") for c in sysm.s["contacts"]}
        rev = {v: k for k, v in names.items()}

        def save(v):
            net_cfg(sysm)["commitments"].append({
                "id": _sid(), "contact": rev.get(v["who"]), "who": "me" if v["dir"] == "я" else "them",
                "text": v["text"].strip(), "due": v["due"], "done": False, "created": app.today().isoformat()})
            self._changed("Обязательство добавлено")
        FormDialog(app, "Обязательство", [
            {"key": "dir", "label": "Кто обещал", "kind": "combo", "options": ["я", "он/она"], "value": "я"},
            {"key": "text", "label": "Что", "value": "", "required": True},
            {"key": "who", "label": "Человек", "kind": "combo", "options": [""] + sorted(names.values()),
             "value": names.get(cid, "")},
            {"key": "due", "label": "Срок", "kind": "date", "value": (app.today() + timedelta(days=7)).isoformat(),
             "optional": True},
        ], save, note="Обязательства с датой попадают в Штаб: просроченное видно в сигналах.")

    # ───────── Разговор ─────────
    def _tab_call(self):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        contacts = sorted(sysm.s["contacts"], key=lambda c: c.get("name", "").lower())
        if not contacts:
            ui_text(self.page, app, "Сначала добавь человека: «Новый человек» справа вверху.").pack(fill="x")
            return
        labels = {c["id"]: c.get("name", "") + (f" ({c['company']})" if c.get("company") else "") for c in contacts}
        if self.call_contact not in labels:
            self.call_contact = (self.sel if self.sel in labels else contacts[0]["id"])
        top = tk.Frame(self.page, bg=C.BG)
        top.pack(fill="x")
        tk.Label(top, text="С кем", font=F["small"], bg=C.BG, fg=C.MUTED).pack(side="left")
        rev = {v: k for k, v in labels.items()}
        who = tk.StringVar(value=labels[self.call_contact])
        cb = ttk.Combobox(top, textvariable=who, values=list(labels.values()), state="readonly", width=40,
                          font=F["ui"])
        cb.pack(side="left", padx=px(6))
        cb.bind("<<ComboboxSelected>>", lambda e: (setattr(self, "call_contact", rev[who.get()]), self.refresh()))
        c = net_contact(sysm, self.call_contact)
        draft = self._drafts.get(c["id"])
        if draft:
            tk.Label(top, text="черновик не сохранён", font=F["small"], bg=C.BG, fg=C.DANGER).pack(
                side="left", padx=px(8))

            def drop():
                self._drafts.pop(c["id"], None)
                self._call_asked.pop(c["id"], None)
                self._call_ui = None
                self.refresh()
            ui_link(top, app, "очистить", drop).pack(side="left")
        body = self._scroll()
        cols = tk.Frame(body, bg=C.BG)
        cols.pack(fill="x")
        cols.columnconfigure(0, weight=1, uniform="cc")
        cols.columnconfigure(1, weight=1, uniform="cc")
        left = tk.Frame(cols, bg=C.BG)
        left.grid(row=0, column=0, sticky="nsew", padx=(0, px(14)))
        right = tk.Frame(cols, bg=C.BG)
        right.grid(row=0, column=1, sticky="nsew")
        self._person_card(left, c)
        self._question_sheet(right)

        tk.Frame(body, bg=C.LINE, height=1).pack(fill="x", pady=px(12))
        tk.Label(body, text="Записи по разговору", font=F["h2"], bg=C.BG, fg=C.INK).pack(anchor="w")
        form = tk.Frame(body, bg=C.BG)
        form.pack(fill="x", pady=(px(6), 0))
        form.columnconfigure(1, weight=1)
        form.columnconfigure(3, weight=1)

        def text_field(row, col, label, height, span=1):
            tk.Label(form, text=label, font=F["small"], bg=C.BG, fg=C.MUTED, anchor="nw", justify="left",
                     wraplength=px(150)).grid(row=row, column=col, sticky="nw", padx=(0, px(8)), pady=px(3))
            t = tk.Text(form, height=height, wrap="word", font=F["ui"], bg=C.SURFACE, fg=C.INK, relief="flat",
                        insertbackground=C.INK, highlightthickness=1, highlightbackground=C.LINE,
                        highlightcolor=C.FOCUS, padx=px(6), pady=px(4))
            t.grid(row=row, column=col + 1, columnspan=span, sticky="ew", pady=px(3))
            return t
        notes = text_field(0, 0, "Заметки по ходу", 5, 3)
        ins = text_field(1, 0, "Что узнал — по пункту на строку («найм: …»)", 4, 3)
        mine = text_field(2, 0, "Я обещал, по строке", 3)
        theirs = text_field(2, 2, "Он/она обещал(а)", 3)
        refs = text_field(3, 0, "Посоветовал(а) поговорить с — «Имя — компания, роль»", 2, 3)
        row = tk.Frame(body, bg=C.BG)
        row.pack(fill="x", pady=(px(6), 0))
        v_topic = tk.StringVar(value="Другое")
        v_sum = tk.StringVar()
        v_kind = tk.StringVar(value="Созвон")
        v_stage = tk.StringVar(value="Созвон проведён" if c.get("status") in (
            "Найден", "Инвайт", "В контактах", "Написал", "Нет ответа", "Ответил", "Созвон назначен", "Затих", "Отказ")
            else c.get("status"))
        cad = net_cadence(sysm, c.get("tier"))
        v_next = tk.StringVar(value=(app.today() + timedelta(days=cad)).isoformat())
        v_cdue = tk.StringVar(value=(app.today() + timedelta(days=7)).isoformat())
        v_when = tk.StringVar(value=app.today().isoformat())
        texts = {"notes": notes, "ins": ins, "mine": mine, "theirs": theirs, "refs": refs}
        tvars = {"sum": v_sum, "topic": v_topic, "kind": v_kind, "stage": v_stage, "next": v_next, "cdue": v_cdue,
                 "when": v_when}
        init = {k: v.get() for k, v in tvars.items()}
        if draft:
            for k, t in texts.items():
                t.insert("1.0", draft["texts"].get(k, ""))
            for k, v in tvars.items():
                if k in draft["vars"]:
                    v.set(draft["vars"][k])
        self._call_ui = {"cid": c["id"], "texts": texts, "vars": tvars, "init": init}
        for label, var, kind, opts, w in (("Итог одной строкой", v_sum, "entry", None, 34),
                                          ("Тема строк без темы", v_topic, "combo", NET_TOPICS, 16),
                                          ("Формат", v_kind, "combo", list(NET_TWO_WAY) + ["Сообщение"], 12)):
            tk.Label(row, text=label, font=F["small"], bg=C.BG, fg=C.MUTED).pack(side="left", padx=(0, px(4)))
            if kind == "entry":
                ttk.Entry(row, textvariable=var, width=w, font=F["ui"]).pack(side="left", padx=(0, px(12)))
            else:
                ttk.Combobox(row, textvariable=var, values=opts, state="readonly", width=w, font=F["ui"]).pack(
                    side="left", padx=(0, px(12)))
        row2 = tk.Frame(body, bg=C.BG)
        row2.pack(fill="x", pady=(px(6), 0))
        for label, var, kind, opts, w in (("Когда", v_when, "entry", None, 11),
                                          ("Стадия после", v_stage, "combo", list(SYS_STATUSES), 16),
                                          ("Следующее касание", v_next, "entry", None, 11),
                                          ("Срок обязательств", v_cdue, "entry", None, 11)):
            tk.Label(row2, text=label, font=F["small"], bg=C.BG, fg=C.MUTED).pack(side="left", padx=(0, px(4)))
            if kind == "entry":
                ttk.Entry(row2, textvariable=var, width=w, font=F["ui"]).pack(side="left", padx=(0, px(12)))
            else:
                ttk.Combobox(row2, textvariable=var, values=opts, state="readonly", width=w, font=F["ui"]).pack(
                    side="left", padx=(0, px(12)))

        def save():
            dates = {}
            for key, var, label, default in (("when", v_when, "Когда", app.today()), ("next", v_next,
                                             "Следующее касание", None), ("cdue", v_cdue, "Срок обязательств", None)):
                raw = var.get().strip()
                try:
                    dates[key] = parse_date(raw, app.today()) if raw else default
                except ValueError:
                    dates[key] = False
                if dates[key] is False or (key == "when" and dates[key] is None):
                    messagebox.showwarning(APP_NAME, f"«{label}»: не понял дату. Примеры: 05.10, 05.10.2026, пт, +3.",
                                           parent=app)
                    return
            when, nxt, cdue = dates["when"], dates["next"], dates["cdue"]
            kind = v_kind.get() or "Созвон"
            t = net_touch(sysm, c, when, kind, "in", channel="Лично" if kind in ("Встреча", "Мероприятие") else
                          (c.get("channel") or ""), note=v_sum.get().strip() or kind,
                          notes=notes.get("1.0", "end-1c").strip(), next_date=nxt.isoformat() if nxt else None,
                          status=v_stage.get() or None)
            n_ins = net_add_insights(sysm, c["id"], t["id"], ins.get("1.0", "end-1c"), v_topic.get() or "Другое",
                                     when)
            for whose, box in (("me", mine), ("them", theirs)):
                for line in net_lines(box.get("1.0", "end-1c")):
                    net_cfg(sysm)["commitments"].append({"id": _sid(), "contact": c["id"], "who": whose,
                                                         "text": line, "due": cdue.isoformat() if cdue else None,
                                                         "done": False, "created": app.today().isoformat()})
            n_new = 0
            for line in net_lines(refs.get("1.0", "end-1c")):
                name, company, role = net_parse_ref(line)
                if name:
                    nc = net_new_contact(sysm, name, company=company, role=role,
                                         source=f"рекомендация от {c.get('name')}", introduced_by=c["id"])
                    net_recompute(sysm, nc)
                    n_new += 1
            for qid in self._call_asked.get(c["id"], set()):
                q = next((x for x in net_cfg(sysm)["questions"] if x["id"] == qid), None)
                if q:
                    q["used"] = int(q.get("used") or 0) + 1
            if n_ins and not c.get("insight"):
                c["insight"] = net_split_topic(net_lines(ins.get("1.0", "end-1c"))[0], "")[1]
            self._call_ui = None
            self._drafts.pop(c["id"], None)
            self._call_asked.pop(c["id"], None)
            self._changed(f"Разговор сохранён: инсайтов {n_ins}, новых людей {n_new}")
            app.check_milestones()
        bottom = tk.Frame(body, bg=C.BG)
        bottom.pack(fill="x", pady=(px(10), px(20)))
        ttk.Button(bottom, text="Сохранить разговор", style="Work.TButton", command=save).pack(side="left")
        ui_text(bottom, app, "Сохранит касание, инсайты, обязательства с обеих сторон и новых людей по рекомендации; "
                             "отмеченные вопросы посчитаются как заданные.").pack(side="left", fill="x", expand=True,
                                                                                 padx=px(12))

    def _question_sheet(self, parent):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        self._asked = {}
        asked = self._call_asked.setdefault(self.call_contact, set())
        head = tk.Frame(parent, bg=C.BG)
        head.pack(fill="x")
        tk.Label(head, text="Вопросы", font=F["h2"], bg=C.BG, fg=C.INK).pack(side="left")
        seg = Segmented(head, app, [("ask", "Спросить"), ("asked", "Меня спросят")],
                        lambda k: (setattr(self, "q_aud", k), self.refresh()))
        seg.pack(side="right")
        seg.set(self.q_aud, C.FOCUS)
        qs = [q for q in net_cfg(sysm)["questions"] if q.get("aud") == self.q_aud]
        base = NET_ASK_CATS if self.q_aud == "ask" else NET_ASKED_CATS
        cats = [c for c in base if any(q.get("cat") == c for q in qs)]
        cats += [c for c in dict.fromkeys(q.get("cat") or "Без категории" for q in qs) if c not in cats]
        for cat in cats:
            tk.Label(parent, text=cat, font=F["ui_bold"], bg=C.BG, fg=C.INK).pack(anchor="w", pady=(px(6), 0))
            for q in sorted((q for q in qs if (q.get("cat") or "Без категории") == cat), key=lambda q: not q.get("star")):
                if self.q_aud == "ask":
                    var = tk.BooleanVar(value=q["id"] in asked)
                    var.trace_add("write", lambda *_a, qid=q["id"], v=var: (asked.add(qid) if v.get() else
                                                                             asked.discard(qid)))
                    self._asked[q["id"]] = var
                    tk.Checkbutton(parent, text=("★ " if q.get("star") else "") + q.get("text", ""), variable=var,
                                   bg=C.BG, fg=C.INK, activebackground=C.BG, activeforeground=C.INK,
                                   selectcolor=C.SURFACE, font=F["ui"], anchor="w", justify="left",
                                   wraplength=px(440), highlightthickness=0, bd=0).pack(anchor="w", fill="x")
                else:
                    ui_text(parent, app, ("★ " if q.get("star") else "") + q.get("text", ""), fg=C.INK).pack(fill="x")
                    ui_text(parent, app, "    " + (q.get("answer") or "ответ не подготовлен — допиши во вкладке "
                                                                     "«Вопросы»"),
                            fg=C.MUTED if not q.get("answer") else C.BREAK).pack(fill="x")

    # ───────── Что узнал ─────────
    def _tab_insights(self):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        net = net_cfg(sysm)
        names = {c["id"]: c for c in sysm.s["contacts"]}
        bar = tk.Frame(self.page, bg=C.BG)
        bar.pack(fill="x", pady=(0, px(8)))
        q_var = tk.StringVar()
        tk.Label(bar, text="Поиск", font=F["small"], bg=C.BG, fg=C.MUTED).pack(side="left")
        ttk.Entry(bar, textvariable=q_var, font=F["ui"], width=26).pack(side="left", padx=(px(6), px(14)))
        topic_var = tk.StringVar(value="Все темы")
        ttk.Combobox(bar, textvariable=topic_var, values=["Все темы"] + NET_TOPICS, state="readonly", width=16,
                     font=F["ui"]).pack(side="left")
        star_var = tk.BooleanVar(value=False)
        ttk.Checkbutton(bar, text="Только важное ★", variable=star_var).pack(side="left", padx=px(14))
        seg = Segmented(bar, app, [("topic", "по темам"), ("person", "по людям")],
                        lambda k: (setattr(self, "ins_group", k), self.refresh()))
        seg.pack(side="left")
        seg.set(self.ins_group, C.FOCUS)
        ttk.Button(bar, text="Записать", style="Work.TButton", command=self.add_insight).pack(side="right")
        frame, tree = self._tree(self.page, [("text", "Что", 560, True), ("src", "От кого / тема", 220, True),
                                             ("date", "Когда", 90, False)], height=20, select="extended")
        frame.pack(fill="both", expand=True)
        acts = tk.Frame(self.page, bg=C.BG)
        acts.pack(fill="x", pady=(px(6), 0))

        def fill():
            tree.delete(*tree.get_children())
            q = q_var.get().strip().lower()
            rows = []
            for i in net["insights"]:
                c = names.get(i.get("contact"))
                hay = f"{i.get('text')} {c.get('name') if c else ''} {c.get('company') if c else ''}".lower()
                if q and q not in hay:
                    continue
                if topic_var.get() != "Все темы" and i.get("topic") != topic_var.get():
                    continue
                if star_var.get() and not i.get("star"):
                    continue
                rows.append((i, c))
            groups = defaultdict(list)
            for i, c in rows:
                key = i.get("topic") or "Другое" if self.ins_group == "topic" else (c.get("name") if c else "Без автора")
                groups[key].append((i, c))
            if self.ins_group == "topic":
                order = [t for t in NET_TOPICS if t in groups] + [g for g in groups if g not in NET_TOPICS]
            else:
                order = sorted(groups, key=lambda g: -len(groups[g]))
            for g in order:
                gid = "g:" + g
                tree.insert("", "end", iid=gid, values=(f"{g} ({len(groups[g])})", "", ""), tags=("group",))
                for i, c in sorted(groups[g], key=lambda x: x[0].get("date") or "", reverse=True):
                    src = (f"{c.get('name')}" + (f", {c['company']}" if c.get("company") else "")) if c else "без автора"
                    tree.insert("", "end", iid=i["id"], tags=("star",) if i.get("star") else (), values=(
                        ("★ " if i.get("star") else "") + i.get("text", ""),
                        src if self.ins_group == "topic" else i.get("topic"),
                        f"{sys_date(i.get('date')):%d.%m.%y}" if sys_date(i.get("date")) else ""))
            if not rows:
                tree.insert("", "end", iid="empty", values=("Ничего не найдено. Инсайты появляются после «Разговора» "
                                                            "или записи вручную.", "", ""), tags=("muted",))

        def selected():
            return [i for i in net["insights"] if i["id"] in tree.selection()]

        def star():
            for i in selected():
                i["star"] = not i.get("star")
            self._changed()

        def delete():
            sel = selected()
            if sel and messagebox.askyesno(APP_NAME, f"Удалить записей: {len(sel)}?", parent=app):
                for i in sel:
                    net["insights"].remove(i)
                self._changed("Удалено")

        def edit():
            sel = selected()
            if not sel:
                return
            i = sel[0]

            def save(v):
                i.update(text=v["text"].strip(), topic=v["topic"])
                self._changed()
            FormDialog(app, "Запись", [
                {"key": "text", "label": "Что", "kind": "text", "height": 4, "value": i.get("text", ""), "required": True},
                {"key": "topic", "label": "Тема", "kind": "combo", "options": NET_TOPICS, "value": i.get("topic")}],
                save)
        ttk.Button(acts, text="★ Важное", command=star).pack(side="left")
        ttk.Button(acts, text="Изменить", command=edit).pack(side="left", padx=px(6))
        ttk.Button(acts, text="Удалить", command=delete).pack(side="left")
        tree.bind("<Double-1>", lambda e: edit())
        for v in (q_var, topic_var, star_var):
            v.trace_add("write", lambda *a: fill())
        fill()

    # ───────── Вопросы ─────────
    def _tab_questions(self):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        net = net_cfg(sysm)
        bar = tk.Frame(self.page, bg=C.BG)
        bar.pack(fill="x", pady=(0, px(8)))
        seg = Segmented(bar, app, [("ask", "Спрашиваю я"), ("asked", "Спросят меня")],
                        lambda k: (setattr(self, "q_aud", k), self.refresh()))
        seg.pack(side="left")
        seg.set(self.q_aud, C.FOCUS)
        qs = [q for q in net["questions"] if q.get("aud") == self.q_aud]
        if self.q_aud == "asked":
            miss = sum(1 for q in qs if not (q.get("answer") or "").strip())
            if miss:
                tk.Label(bar, text=f"без подготовленного ответа: {miss} из {len(qs)}", font=F["small"], bg=C.BG,
                         fg=C.DANGER).pack(side="left", padx=px(14))
        ttk.Button(bar, text="Добавить вопрос", style="Work.TButton", command=lambda: self._edit_question(None)).pack(
            side="right")
        pane = tk.Frame(self.page, bg=C.BG)
        pane.pack(fill="both", expand=True)
        pane.columnconfigure(0, weight=3, uniform="qq")
        pane.columnconfigure(1, weight=2, uniform="qq")
        pane.rowconfigure(0, weight=1)
        frame, tree = self._tree(pane, [("text", "Вопрос", 460, True), ("used", "Задавал", 70, False)], height=20)
        frame.grid(row=0, column=0, sticky="nsew", padx=(0, px(10)))
        side = tk.Frame(pane, bg=C.BG)
        side.grid(row=0, column=1, sticky="nsew")
        base = NET_ASK_CATS if self.q_aud == "ask" else NET_ASKED_CATS
        cats = [c for c in base if any(q.get("cat") == c for q in qs)]
        cats += [c for c in dict.fromkeys(q.get("cat") or "Без категории" for q in qs) if c not in cats]
        for cat in cats:
            gid = "g:" + cat
            tree.insert("", "end", iid=gid, values=(cat, ""), tags=("group",))
            for q in sorted((q for q in qs if (q.get("cat") or "Без категории") == cat),
                            key=lambda q: not q.get("star")):
                title = ("★ " if q.get("star") else "") + q.get("text", "")
                if self.q_aud == "asked" and not (q.get("answer") or "").strip():
                    title += "  (нет ответа)"
                tree.insert("", "end", iid=q["id"], values=(title, q.get("used") or ""),
                            tags=("due",) if self.q_aud == "asked" and not q.get("answer") else ())

        def show(_e=None):
            for w in side.winfo_children():
                w.destroy()
            s = tree.selection()
            q = next((x for x in qs if s and x["id"] == s[0]), None)
            if q is None:
                ui_text(side, app, "Выбери вопрос, чтобы увидеть и изменить "
                                   + ("зачем его задавать." if self.q_aud == "ask" else "подготовленный ответ.")).pack(
                    fill="x")
                return
            tk.Label(side, text=q.get("text"), font=F["ui_bold"], bg=C.BG, fg=C.INK, wraplength=px(380),
                     justify="left", anchor="w").pack(fill="x")
            ui_text(side, app, f"{q.get('cat') or 'без категории'} · задавал {q.get('used') or 0} раз").pack(fill="x")
            tk.Label(side, text="Мой ответ" if self.q_aud == "asked" else "Зачем спрашиваю, что хочу услышать",
                     font=F["small"], bg=C.BG, fg=C.MUTED).pack(anchor="w", pady=(px(8), 0))
            ans = tk.Text(side, height=12, wrap="word", font=F["ui"], bg=C.SURFACE, fg=C.INK, relief="flat",
                          insertbackground=C.INK, highlightthickness=1, highlightbackground=C.LINE,
                          highlightcolor=C.FOCUS, padx=px(8), pady=px(6))
            ans.insert("1.0", q.get("answer") or "")
            ans.pack(fill="both", expand=True)
            r = tk.Frame(side, bg=C.BG)
            r.pack(fill="x", pady=(px(6), 0))

            def save_answer():
                q["answer"] = ans.get("1.0", "end-1c").strip()
                self._changed("Ответ сохранён")
            ttk.Button(r, text="Сохранить", style="Work.TButton", command=save_answer).pack(side="left")
            ttk.Button(r, text="Изменить вопрос", command=lambda: self._edit_question(q)).pack(side="left",
                                                                                             padx=px(6))
            ttk.Button(r, text="★" if not q.get("star") else "Снять ★",
                       command=lambda: (q.update(star=not q.get("star")), self._changed())).pack(side="left")
        tree.bind("<<TreeviewSelect>>", show)
        show()

    def _edit_question(self, q):
        app, sysm = self.app, self.app.system
        net = net_cfg(sysm)
        base = NET_ASK_CATS if self.q_aud == "ask" else NET_ASKED_CATS
        cats = list(dict.fromkeys(base + [x.get("cat") for x in net["questions"] if x.get("aud") == self.q_aud
                                          and x.get("cat")]))

        def save(v):
            data = {"text": v["text"].strip(), "cat": v["cat"].strip() or "Без категории", "star": v["star"]}
            if q is None:
                net["questions"].append(dict(data, id=_sid(), aud=self.q_aud, answer=v.get("answer", ""), used=0))
            else:
                q.update(data)
            self._changed("Вопрос сохранён")

        def delete():
            net["questions"].remove(q)
            self._changed("Вопрос удалён")
        fields = [{"key": "text", "label": "Вопрос", "kind": "text", "height": 3, "value": (q or {}).get("text", ""),
                   "required": True},
                  {"key": "cat", "label": "Категория", "kind": "combo", "options": cats, "free": True,
                   "value": (q or {}).get("cat") or cats[0]},
                  {"key": "star", "label": "Важный ★", "kind": "check", "value": bool((q or {}).get("star"))}]
        if q is None:
            fields.insert(2, {"key": "answer", "label": "Ответ" if self.q_aud == "asked" else "Зачем спрашиваю",
                              "kind": "text", "height": 4, "value": ""})
        FormDialog(app, "Вопрос", fields, save, on_delete=delete if q else None)

    # ───────── Возможности ─────────
    def _tab_opps(self):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        net = net_cfg(sysm)
        today = app.today()
        bar = tk.Frame(self.page, bg=C.BG)
        bar.pack(fill="x", pady=(0, px(8)))
        closed_var = tk.BooleanVar(value=bool(getattr(self, "opp_closed", False)))
        ttk.Checkbutton(bar, text="Показывать закрытые", variable=closed_var,
                        command=lambda: (setattr(self, "opp_closed", closed_var.get()), self.refresh())).pack(
            side="left")
        ttk.Button(bar, text="Добавить возможность", style="Work.TButton", command=lambda: self.edit_opp(None)).pack(
            side="right")
        pane = tk.Frame(self.page, bg=C.BG)
        pane.pack(fill="both", expand=True)
        pane.columnconfigure(0, weight=3, uniform="oo")
        pane.columnconfigure(1, weight=2, uniform="oo")
        pane.rowconfigure(0, weight=1)
        frame, tree = self._tree(pane, [("title", "Что", 220, True), ("org", "Где", 140, True),
                                        ("kind", "Тип", 110, False), ("stage", "Стадия", 110, False),
                                        ("dl", "Дедлайн", 120, False), ("p", "P", 36, False)], height=18)
        frame.grid(row=0, column=0, sticky="nsew", padx=(0, px(10)))
        side_sf = ScrollFrame(pane)
        side_sf.grid(row=0, column=1, sticky="nsew")
        side = side_sf.inner
        rows = [o for o in net["opportunities"] if closed_var.get() or o.get("stage") not in OPP_CLOSED]
        rows.sort(key=lambda o: (o.get("deadline") is None, o.get("deadline") or "", int(o.get("priority") or 2)))
        for o in rows:
            d = sys_date(o.get("deadline"))
            hot = d is not None and (d - today).days <= 14 and o.get("stage") not in OPP_CLOSED
            tree.insert("", "end", iid=o["id"], tags=("due",) if hot else (("muted",) if o.get("stage") in OPP_CLOSED
                                                                          else ()),
                        values=(o.get("title"), o.get("org") or "", OPP_KINDS.get(o.get("kind"), ""),
                                OPP_STAGES.get(o.get("stage"), ""),
                                (f"{d:%d.%m} · {due_label(o['deadline'], today)}" if d else ""),
                                f"P{o.get('priority', 2)}"))
        if not rows:
            ui_text(side, app, "Список пуст. Добавь стажировку, магистратуру, грант или конкурс — дедлайны появятся "
                               "в Ставке и календаре, задачи — в «Сегодня».").pack(fill="x")

        def show(_e=None):
            for w in side.winfo_children():
                w.destroy()
            s = tree.selection()
            o = next((x for x in rows if s and x["id"] == s[0]), None)
            if o is None:
                return
            self.opp_sel = o["id"]
            tk.Label(side, text=o.get("title"), font=F["h2"], bg=C.BG, fg=C.INK, anchor="w", wraplength=px(380),
                     justify="left").pack(fill="x")
            ui_text(side, app, ", ".join(x for x in (o.get("org"), OPP_KINDS.get(o.get("kind"))) if x)).pack(fill="x")
            r = tk.Frame(side, bg=C.BG)
            r.pack(fill="x", pady=(px(6), 0))
            tk.Label(r, text="Стадия", font=F["small"], bg=C.BG, fg=C.MUTED).pack(side="left")
            st = tk.StringVar(value=OPP_STAGES.get(o.get("stage"), "слежу"))
            rev = {v: k for k, v in OPP_STAGES.items()}
            cb = ttk.Combobox(r, textvariable=st, values=list(OPP_STAGES.values()), state="readonly", width=18,
                              font=F["ui"])
            cb.pack(side="left", padx=px(6))
            cb.bind("<<ComboboxSelected>>", lambda e: (o.update(stage=rev[st.get()]), self._changed("Стадия обновлена")))
            ui_link(r, app, "изменить", lambda: self.edit_opp(o), fg=C.MUTED).pack(side="right")
            if o.get("url"):
                ui_link(side, app, "открыть ссылку", lambda u=o["url"]: webbrowser.open(u)).pack(anchor="w",
                                                                                               pady=(px(4), 0))
            if o.get("notes"):
                ui_text(side, app, o["notes"], fg=C.INK).pack(fill="x", pady=(px(4), 0))
            self._h2(side, "Что сделать", "добавить", lambda: self._add_task(o))
            tasks = sorted(o.get("tasks") or [], key=lambda t: (bool(t.get("done")), t.get("due") or "9999"))
            if not tasks:
                ui_text(side, app, "Задач нет.").pack(fill="x")
            for t in tasks:
                rr = tk.Frame(side, bg=C.BG)
                rr.pack(fill="x")
                var = tk.BooleanVar(value=bool(t.get("done")))
                ttk.Checkbutton(rr, variable=var, text=t.get("title", "") + (
                    f", {sys_date(t['due']):%d.%m}" if sys_date(t.get("due")) else ""),
                    command=lambda tt=t, vv=var: (tt.update(done=vv.get()), self._changed())).pack(side="left")
        tree.bind("<<TreeviewSelect>>", show)
        tree.bind("<Double-1>", lambda e: self.opp_sel and self.edit_opp(
            next((x for x in net["opportunities"] if x["id"] == self.opp_sel), None)))
        if self.opp_sel and tree.exists(self.opp_sel):
            tree.selection_set(self.opp_sel)
        elif rows:
            tree.selection_set(rows[0]["id"])
        show()

    def _add_task(self, o):
        def save(v):
            o.setdefault("tasks", []).append({"id": _sid(), "title": v["title"].strip(), "due": v["due"], "done": False})
            self._changed("Задача добавлена")
        FormDialog(self.app, f"Задача: {o.get('title')}", [
            {"key": "title", "label": "Что сделать", "value": "", "required": True},
            {"key": "due", "label": "Срок", "kind": "date", "value": None, "optional": True}], save)

    def edit_opp(self, o):
        app, sysm = self.app, self.app.system
        net = net_cfg(sysm)
        cur = o or {"kind": "internship", "stage": "watch", "priority": 2}
        kinds, stages = OPP_KINDS, OPP_STAGES
        rk, rs = {v: k for k, v in kinds.items()}, {v: k for k, v in stages.items()}

        def save(v):
            data = {"title": v["title"].strip(), "org": v["org"].strip(), "kind": rk.get(v["kind"], "other"),
                    "stage": rs.get(v["stage"], "watch"), "deadline": v["deadline"], "priority": int(v["priority"]),
                    "url": v["url"].strip(), "notes": v["notes"].strip()}
            if o is None:
                net["opportunities"].append(dict(data, id=_sid(), created=app.today().isoformat(), tasks=[]))
            else:
                o.update(data)
            self._changed("Возможность сохранена")

        def delete():
            net["opportunities"].remove(o)
            self._changed("Возможность удалена")
        FormDialog(app, "Возможность", [
            {"key": "title", "label": "Название", "value": cur.get("title", ""), "required": True},
            {"key": "org", "label": "Организация", "value": cur.get("org", "")},
            {"key": "kind", "label": "Тип", "kind": "combo", "options": list(kinds.values()),
             "value": kinds.get(cur.get("kind"), "другое")},
            {"key": "stage", "label": "Стадия", "kind": "combo", "options": list(stages.values()),
             "value": stages.get(cur.get("stage"), "слежу")},
            {"key": "deadline", "label": "Дедлайн", "kind": "date", "value": cur.get("deadline"), "optional": True},
            {"key": "priority", "label": "Приоритет 1–3", "kind": "int", "value": cur.get("priority", 2), "lo": 1,
             "hi": 3},
            {"key": "url", "label": "Ссылка", "value": cur.get("url", "")},
            {"key": "notes", "label": "Заметки", "kind": "text", "height": 4, "value": cur.get("notes", ""),
             "hint": "требования, что подготовить"},
        ], save, on_delete=delete if o else None)

    # ───────── Шаблоны ─────────
    def _tab_templates(self):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        net = net_cfg(sysm)
        tpls = net["templates"]
        bar = tk.Frame(self.page, bg=C.BG)
        bar.pack(fill="x", pady=(0, px(8)))
        ttk.Button(bar, text="Новый шаблон", command=lambda: self._edit_template(None)).pack(side="right")
        if not tpls:
            ui_text(self.page, app, "Шаблонов нет. «Новый шаблон» — создать.").pack(fill="x")
            return
        tmap = {t["id"]: t for t in tpls}
        if self.tpl_sel not in tmap:
            self.tpl_sel = tpls[0]["id"]
        contacts = sorted(sysm.s["contacts"], key=lambda c: c.get("name", "").lower())
        labels = {c["id"]: c.get("name", "") for c in contacts}
        cid = getattr(self, "tpl_contact", None)
        if cid not in labels:
            cid = None
        tk.Label(bar, text="Шаблон", font=F["small"], bg=C.BG, fg=C.MUTED).pack(side="left")
        t_var = tk.StringVar(value=tmap[self.tpl_sel]["name"])
        names = {t["name"]: t["id"] for t in tpls}
        cb = ttk.Combobox(bar, textvariable=t_var, values=list(names), state="readonly", width=34, font=F["ui"])
        cb.pack(side="left", padx=(px(6), px(14)))
        cb.bind("<<ComboboxSelected>>", lambda e: (setattr(self, "tpl_sel", names[t_var.get()]), self.refresh()))
        tk.Label(bar, text="Кому", font=F["small"], bg=C.BG, fg=C.MUTED).pack(side="left")
        c_var = tk.StringVar(value=labels.get(cid, "никому конкретно"))
        rev = {v: k for k, v in labels.items()}
        cb2 = ttk.Combobox(bar, textvariable=c_var, values=["никому конкретно"] + list(labels.values()),
                           state="readonly", width=26, font=F["ui"])
        cb2.pack(side="left", padx=px(6))
        cb2.bind("<<ComboboxSelected>>", lambda e: (setattr(self, "tpl_contact", rev.get(c_var.get())), self.refresh()))
        t = tmap[self.tpl_sel]
        phs = list(dict.fromkeys(re.findall(r"\{(\w+)\}", t["body"])))
        auto = {"me_name": net.get("me_name", ""), "me_short": net.get("me_short", "")}
        c = net_contact(sysm, cid) if cid else None
        if c:
            auto.update(name=(c.get("name") or "").split()[0] if c.get("name") else "", company=c.get("company") or "",
                        role=c.get("role") or "")
        body = self._scroll()
        grid = tk.Frame(body, bg=C.BG)
        grid.pack(fill="x")
        grid.columnconfigure(1, weight=1)
        grid.columnconfigure(3, weight=1)
        vals = {}
        for k, ph in enumerate(phs):
            r, col = divmod(k, 2)
            tk.Label(grid, text=NET_PH_LABELS.get(ph, ph), font=F["small"], bg=C.BG, fg=C.MUTED, anchor="w").grid(
                row=r, column=col * 2, sticky="w", padx=(0 if col == 0 else px(14), px(6)), pady=px(2))
            var = tk.StringVar(value=auto.get(ph, ""))
            ttk.Entry(grid, textvariable=var, font=F["ui"]).grid(row=r, column=col * 2 + 1, sticky="ew", pady=px(2))
            vals[ph] = var
        out = tk.Text(body, height=10, wrap="word", font=F["ui"], bg=C.SURFACE, fg=C.INK, relief="flat",
                      highlightthickness=1, highlightbackground=C.LINE, padx=px(10), pady=px(8))
        out.pack(fill="x", pady=(px(10), px(4)))
        warn = ui_text(body, app, "", fg=C.DANGER)
        warn.pack(fill="x")

        def render(*_a):
            filled = {k: (v.get().strip() or f"[{NET_PH_LABELS.get(k, k)}]") for k, v in vals.items()}
            try:
                text = t["body"].format_map(_Safe(filled))
            except (ValueError, IndexError, KeyError):
                text = t["body"]
            out.configure(state="normal")
            out.delete("1.0", "end")
            out.insert("1.0", text)
            missing = [NET_PH_LABELS.get(p, p) for p in phs if not vals[p].get().strip()]
            warn.configure(text=("Не заполнено: " + ", ".join(missing)) if missing else "")
        for v in vals.values():
            v.trace_add("write", render)
        render()
        acts = tk.Frame(body, bg=C.BG)
        acts.pack(fill="x", pady=(px(6), 0))

        def copy():
            app.clipboard_clear()
            app.clipboard_append(out.get("1.0", "end-1c"))
            app.toast("Скопировано в буфер")

        def sent():
            net_touch(sysm, c, app.today(), "Сообщение", "out", note=f"шаблон «{t['name']}»")
            self._changed(f"Касание записано: {c.get('name')}")
        ttk.Button(acts, text="Копировать", style="Work.TButton", command=copy).pack(side="left")
        if c:
            ttk.Button(acts, text="Отметить как отправленное", command=sent).pack(side="left", padx=px(6))
        ttk.Button(acts, text="Изменить шаблон", command=lambda: self._edit_template(t)).pack(side="right")

    def _edit_template(self, t):
        app, sysm = self.app, self.app.system
        net = net_cfg(sysm)

        def save(v):
            name = v["name"].strip()
            if any(x["name"] == name and x is not t for x in net["templates"]):
                messagebox.showwarning(APP_NAME, "Шаблон с таким названием уже есть.", parent=app)
                return False
            if t is None:
                nt = {"id": _sid(), "name": name, "body": v["body"]}
                net["templates"].append(nt)
                self.tpl_sel = nt["id"]
            else:
                t.update(name=name, body=v["body"])
            self._changed("Шаблон сохранён")

        def delete():
            net["templates"].remove(t)
            self._changed("Шаблон удалён")
        FormDialog(app, "Шаблон", [
            {"key": "name", "label": "Название", "value": (t or {}).get("name", ""), "required": True},
            {"key": "body", "label": "Текст", "kind": "text", "height": 10, "value": (t or {}).get("body", ""),
             "required": True, "hint": "поля в фигурных скобках: {name}, {hook}, {ask}, {me_short}…"},
        ], save, on_delete=delete if t else None, width=60)

    # ───────── Данные ─────────
    def edit_settings(self):
        app, sysm = self.app, self.app.system
        net = net_cfg(sysm)

        def save(v):
            net.update(me_name=v["me_name"].strip(), me_short=v["me_short"].strip(), quota=bool(v["quota"]))
            for t in ("1", "2", "3"):
                net["cadence"][t] = int(v["cad" + t])
            self._changed("Настройки сети сохранены")
        FormDialog(app, "Сеть: настройки", [
            {"key": "me_name", "label": "Подпись", "value": net.get("me_name", "")},
            {"key": "me_short", "label": "Кто я, одной фразой", "value": net.get("me_short", ""),
             "hint": "подставляется в шаблоны: {me_short}"},
            {"key": "cad1", "label": "T1: касание раз в, дней", "kind": "int", "value": net["cadence"]["1"], "lo": 1,
             "hi": 365},
            {"key": "cad2", "label": "T2: раз в, дней", "kind": "int", "value": net["cadence"]["2"], "lo": 1, "hi": 365},
            {"key": "cad3", "label": "T3: раз в, дней", "kind": "int", "value": net["cadence"]["3"], "lo": 1, "hi": 365},
            {"key": "quota", "label": "Квота касаний в кампании", "kind": "check", "value": net.get("quota", True),
             "hint": "включено — касания идут в боеготовность, план по неделям и напоминание в 21:30"},
        ], save)

    def recompute_all(self):
        sysm = self.app.system
        for c in sysm.s["contacts"]:
            if c.get("next_date"):
                net_recompute(sysm, c)
        self._changed("Сроки касаний пересчитаны")

    def import_li(self):
        app = self.app
        path = filedialog.askopenfilename(parent=app, title="Connections.csv из выгрузки LinkedIn",
                                          filetypes=[("CSV", "*.csv"), ("Все файлы", "*.*")])
        if not path:
            return
        try:
            text = Path(path).read_text(encoding="utf-8-sig", errors="replace")
        except OSError as e:
            messagebox.showerror(APP_NAME, f"Не удалось прочитать файл: {e}", parent=app)
            return
        added, skipped = import_linkedin(app.system, text, 3)
        self._changed()
        messagebox.showinfo(APP_NAME, f"Добавлено {added}, дублей пропущено {skipped}. Все импортированные — T3 "
                                      "без напоминаний: тем, кого реально ведёшь, поставь T1 или T2 в карточке.",
                            parent=app)

    def import_db(self):
        app = self.app
        start = netcrm_source()
        path = filedialog.askopenfilename(parent=app, title="База netapp (netcrm.db)",
                                          initialdir=str(start.parent) if start else str(Path.home()),
                                          filetypes=[("База SQLite", "*.db"), ("Все файлы", "*.*")])
        if not path:
            return
        try:
            n = import_netcrm(app.system, path)
        except sqlite3.Error as e:
            messagebox.showerror(APP_NAME, f"Не удалось прочитать базу: {e}", parent=app)
            return
        self._changed()
        messagebox.showinfo(APP_NAME, "Перенесено: " + (", ".join(f"{k} {v}" for k, v in n.items()) or "новых записей "
                                                                                                       "нет"),
                            parent=app)

    def export_csv(self):
        folder = filedialog.askdirectory(parent=self.app, title="Папка для выгрузки")
        if not folder:
            return
        files = export_net_csv(self.app.system, folder)
        self.app.toast(f"Выгружено файлов: {len(files)} → {folder}", lambda: open_path(Path(folder)), "Открыть",
                       ms=9000)


# ───────────────────────── система 96 дней: Штаб ─────────────────────────

COURSE_SHORT = {"Машинное обучение 1": "ML", "Финансовая инженерия": "Фининж", "Микроструктура рынка": "Микроструктура",
                "Введение в прогнозирование": "Прогнозирование", "Корпоративные финансы": "Корпфин"}


def course_short(name):
    return COURSE_SHORT.get(name, name if len(name) <= 16 else name[:15] + "…")


class SystemView(tk.Frame):
    """Ставка: как идёт кампания — приказ, фронты, разведка, наряды, дневник, навыки, календарь, дежурный, устав."""

    TABS = [("overview", "Сводка"), ("soldier", "Солдат"), ("fronts", "Фронты"), ("intel", "Разведка"), ("duty", "Наряды"),
            ("dossier", "Личное дело"), ("diary", "Дневник"), ("skills", "Навыки"), ("calendar", "Календарь"),
            ("discipline", "Дежурный"), ("plan", "Устав")]
    CAL_FILTERS = [("upcoming", "Предстоящие"), ("undated", "Без даты"), ("all", "Все")]

    def __init__(self, master, app):
        super().__init__(master, bg=C.BG)
        self.app = app
        F, px = app.fonts, app.px
        tab = app.store.settings.get("system_tab")
        self.tab = tab if tab in dict(self.TABS) else "overview"
        self.cal_filter = "upcoming"
        wrap = tk.Frame(self, bg=C.BG)
        wrap.pack(fill="both", expand=True, padx=px(28), pady=(px(22), px(8)))
        head = tk.Frame(wrap, bg=C.BG)
        head.pack(fill="x")
        tk.Label(head, text="Ставка", font=F["h1"], bg=C.BG, fg=C.INK).pack(side="left")
        self.days_lbl = tk.Label(head, text="", font=F["ui"], bg=C.BG, fg=C.MUTED)
        self.days_lbl.pack(side="left", padx=(px(14), 0), pady=(px(6), 0))
        ttk.Button(head, text="Вечерняя сводка", style="Work.TButton",
                   command=lambda: app.checkin()).pack(side="right")
        ttk.Button(head, text="Разбор недели", command=app.weekly_review).pack(side="right", padx=px(6))
        ttk.Button(head, text="Построение", command=lambda: app.coach.open_morning()).pack(side="right")
        ttk.Button(head, text="Донесение", command=lambda: app.open_report("day")).pack(side="right", padx=(0, px(6)))
        self.sub = ui_text(wrap, app, "")
        self.sub.pack(fill="x", pady=(px(4), px(8)))
        self.seg = Segmented(wrap, app, self.TABS, self.set_tab)
        self.seg.pack(anchor="w", pady=(0, px(10)))
        self.scroll = ScrollFrame(wrap)
        self.scroll.pack(fill="both", expand=True)
        self.body = self.scroll.inner
        self._menu = None

    # --- навигация ---
    def set_tab(self, key):
        self.tab = key
        self.app.store.settings["system_tab"] = key
        if self.app.current_view != "system":
            self.app._goto("system")
        else:
            self.refresh()
        self.scroll.canvas.yview_moveto(0)

    def on_show(self):
        self.refresh()
        self.focus_set()

    def refresh(self):
        app, sysm = self.app, self.app.system
        for w in self.body.winfo_children():
            w.destroy()
        self.seg.set(self.tab, C.FOCUS)
        today = app.today()
        total = sysm.total_days()
        if today < sysm.start():
            days = f"{sysm.name()}: старт {sysm.start():%d.%m}, {total} {plural(total, DAY_FORMS)}"
        else:
            days = sysm.campaign_line(today)
        self.days_lbl.configure(text=days)
        ph = sysm.phase_at(min(max(today, sysm.start()), sysm.end()))
        self.sub.configure(text=(f"Этап «{ph['name']}», {ph['start']:%d.%m}–{ph['end']:%d.%m}. {ph['focus']}"
                                 if ph else ""))
        getattr(self, "_tab_" + self.tab)()

    def _popup(self, menu):
        if self._menu is not None:
            try:
                self._menu.destroy()
            except tk.TclError:
                pass
        self._menu = menu
        try:
            menu.tk_popup(self.winfo_pointerx(), self.winfo_pointery())
        finally:
            menu.grab_release()

    def _new_menu(self):
        return tk.Menu(self, tearoff=False, bg=C.SURFACE, fg=C.INK, activebackground=C.SELECT,
                       activeforeground=C.INK, font=self.app.fonts["ui"])

    def type_menu(self, day):
        app, sysm = self.app, self.app.system
        m = self._new_menu()
        for name in sysm.type_names():
            if name == LEAVE_TYPE:
                continue
            m.add_command(label=f"{name} — {fmt_h(sysm.type_hours(name))} ч",
                          command=lambda n=name: app.set_day_type(day, n))
        m.add_separator()
        m.add_command(label="По умолчанию для дня недели", command=lambda: app.set_day_type(day, None))
        m.add_separator()
        if sysm.is_reserve(day):
            if day >= app.today():
                m.add_command(label="Отменить резерв Ставки",
                              command=lambda: (sysm.cancel_reserve(day), app._sys_changed("Резерв отменён")))
        else:
            ok, why = sysm.reserve_check(day)
            m.add_command(label=f"Резерв Ставки (осталось {sysm.reserve_left(app.today())})…" if ok
                          else f"Резерв: {why}", state="normal" if ok else "disabled",
                          command=lambda: app.ask_reserve(day))
        self._popup(m)

    def _h2(self, parent, text, link=None, command=None, bg=None):
        F, px = self.app.fonts, self.app.px
        row = tk.Frame(parent, bg=bg or parent.cget("bg"))
        row.pack(fill="x")
        tk.Label(row, text=text, font=F["h2"], bg=row.cget("bg"), fg=C.INK).pack(side="left")
        if link:
            ui_link(row, self.app, link, command).pack(side="right", pady=(px(4), 0))
        return row

    # ───────── Обзор ─────────
    def _tab_overview(self):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        today = app.today()
        alerts = self._app_alerts() + sysm.alerts(today)
        if alerts:
            box = tk.Frame(self.body, bg=C.BG)
            box.pack(fill="x", pady=(0, px(10)))
            colors = {"bad": C.DANGER, "warn": C.LONG, "info": C.MUTED}
            for level, text, action, label in alerts[:8]:
                row = tk.Frame(box, bg=C.BG)
                row.pack(fill="x", pady=px(1))
                tk.Label(row, text="●", font=F["small"], bg=C.BG, fg=colors[level]).pack(side="left", anchor="n")
                if action:
                    ui_link(row, app, label, action).pack(side="right", anchor="n", padx=(px(10), 0))
                ui_text(row, app, text, fg=C.INK).pack(side="left", fill="x", expand=True, padx=(px(6), 0))
            if len(alerts) > 8:
                ui_text(box, app, f"и ещё {len(alerts) - 8}").pack(fill="x")
        self._order_card(today)
        self._today_card(today)
        self._motivation_row(today)
        self._kpis(today)
        self._directions(today)
        self._insights(today)
        self._weeks_chart(today)
        cols = tk.Frame(self.body, bg=C.BG)
        cols.pack(fill="x", pady=(0, px(10)))
        cols.columnconfigure(0, weight=3, uniform="c")
        cols.columnconfigure(1, weight=2, uniform="c")
        self._upcoming(cols, today).grid(row=0, column=0, sticky="nsew", padx=(0, px(8)))
        self._skills_mini(cols).grid(row=0, column=1, sticky="nsew")

    def _tab_soldier(self):
        app, sysm = self.app, self.app.system
        today = app.today()
        cfg = sysm.s.setdefault("soldier", {"profile": "Боевой", "checks": {}})
        outer, card = ui_card(self.body, app)
        outer.pack(fill="x", pady=(0, app.px(12)))
        ui_text(card, app, "СОЛДАТ · приказ → действие → доклад", font="h2").pack(anchor="w")
        ui_text(card, app, "Твёрдый порядок без саморазрушения. Сон важнее лишнего часа. "
                "При болезни — оборона, при перегрузке — пересмотр плана.").pack(fill="x")
        if sysm.s.get("start") != CAMPAIGN_START or sysm.s.get("end") != CAMPAIGN_END:
            def replan():
                if not messagebox.askyesno(APP_NAME, "Перестроить кампанию на 23.10–31.12.2026 и 630 часов? "
                        "Сессии, дни, оценки и выслуга сохранятся. Старый план будет в архиве; "
                        "итоги текущей кампании будут считаться с 23 октября.", parent=app):
                    return
                try:
                    app.store.backup_now()
                except OSError as exc:
                    messagebox.showerror(APP_NAME, str(exc), parent=app)
                    return
                replan_70(sysm.s)
                app.store.save()
                sysm.invalidate()
                self.refresh()
            ttk.Button(card, text="Развернуть кампанию-70 · с резервной копией", command=replan).pack(anchor="w", pady=8)
        ui_text(card, app, f"Сегодня: {sysm.day_type(today)} · норма {fmt_h(sysm.day_plan(today))} ч", font="ui").pack(anchor="w", pady=8)
        for label, command in [("Построение / главный удар", app.coach.open_morning),
                               ("Вечерняя сводка", app.checkin),
                               ("Изменить нормы и правила", lambda: self.set_tab("plan"))]:
            ttk.Button(card, text=label, command=command).pack(anchor="w", pady=3)
        outer, card = ui_card(self.body, app)
        outer.pack(fill="x")
        ui_text(card, app, "Осмотр готовности · личный чек-лист", font="h2").pack(anchor="w")
        ui_text(card, app, "Отметки сохраняются на каждый день. Это осмотр, не дополнительные штрафы.").pack(fill="x")
        records = cfg.setdefault("checks", {})
        if not isinstance(records.get(today.isoformat()), dict):
            records[today.isoformat()] = {}
        checks = records[today.isoformat()]
        for key, label in SOLDIER_CHECKS:
            var = tk.BooleanVar(value=bool(checks.get(key)))
            def toggle(k=key, v=var):
                checks[k] = v.get()
                app.store.save()
            ttk.Checkbutton(card, text=label, variable=var, command=toggle).pack(anchor="w", pady=5)

    def _app_alerts(self):
        """Сигналы о самой программе: без автозапуска дежурный после перезагрузки молчит."""
        app = self.app
        out = []
        if not (IS_WIN or IS_MAC) or not app.system.coach.get("enabled", True):
            return out
        try:
            auto = app.integration.autostart_enabled()
        except Exception:
            auto = True
        if not auto:
            out.append(("warn", "Автозапуск выключен: после перезагрузки Генштаб не запустится, и дежурный будет молчать.",
                        lambda: (app.do_autostart(True), self.refresh()), "Включить"))
        return out

    def _today_card(self, today):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        outer, card = ui_card(self.body, app)
        outer.pack(fill="x", pady=(0, px(10)))
        if not sysm.active(today):
            ui_text(card, app, f"Сегодня вне кампании ({sysm.start():%d.%m}–{sysm.end():%d.%m}). Даты меняются "
                               "на вкладке «Устав».", font="ui").pack(fill="x")
            return
        dtype, plan, hours = sysm.day_type(today), sysm.day_plan(today), sysm.hours_on(today)
        top = tk.Frame(card, bg=C.SURFACE)
        top.pack(fill="x")
        tk.Label(top, text=f"Сегодня, {WD_FULL[today.weekday()]}, {today.day} {MONTHS_GEN[today.month - 1]}",
                 font=F["h2"], bg=C.SURFACE, fg=C.INK).pack(side="left")
        ui_link(top, app, ("резерв Ставки" if sysm.is_reserve(today) else f"режим «{dtype}», норма {fmt_h(plan)} ч")
                + " ▾", lambda: self.type_menu(today)).pack(
            side="left", padx=(px(12), 0), pady=(px(3), 0))
        score, parts = sysm.day_score(today)
        good = int(sysm.coach.get("good_score", 70) or 70)
        tk.Label(top, text=f"боеготовность {score}", font=F["h2"], bg=C.SURFACE,
                 fg=C.BREAK if score >= good else (C.LONG if score >= good * 0.6 else C.DANGER)).pack(side="right")
        rec0 = sysm.day(today)
        sched = []
        now = PLATFORM["now"]()
        cur = sysm.block_at(now)
        nxt = sysm.next_block(now)
        if cur:
            sched.append(f"сейчас «{cur[0].get('label')}» до {cur[2]:%H:%M}")
        if nxt:
            sched.append(f"дальше «{nxt[0].get('label')}» в {nxt[1]:%H:%M}")
        if rec0.get("promise") is not None:
            sched.append(f"на построении взял {fmt_h(rec0['promise'])} ч")
        missing = [t for k, (p, t) in parts.items() if p < 0.999]
        if missing:
            sched.append("до 100: " + ", ".join(missing[:4]))
        if sched:
            ui_text(card, app, " · ".join(sched)).pack(fill="x", pady=(px(2), 0))
        tl = tk.Canvas(card, bg=C.SURFACE, highlightthickness=0, height=px(48))
        tl.pack(fill="x", pady=(px(8), 0))
        tl.bind("<Configure>", lambda e: self._draw_timeline(tl, today))
        frac = hours / plan if plan else (1.0 if hours else 0.0)
        Bar(card, app, frac, C.BREAK if plan and hours >= plan else C.FOCUS, height=10).pack(
            fill="x", pady=(px(6), px(6)))
        text = (f"Сделано {fmt_h(hours)} ч из {fmt_h(plan)}" + (f" ({int(round(frac * 100))}%)" if plan else "")
                if not sysm.is_reserve(today) else f"Резерв Ставки: {sysm.reserve_reason(today) or 'отдых'}")
        p = app.pomo
        if p.mode in FOCUS_MODES and p.is_active() and p.elapsed() >= 60:
            text += f", плюс идёт штурм {fmt_minutes(p.elapsed() / 60)}"
        rec = sysm.day(today)
        if rec.get("done"):
            state = (f"Сводка принята: сон {fmt_h(rec.get('sleep'))} ч, {(rec.get('train') or 'Нет').lower()}, "
                     f"питание {sysm.food_score(today)} из 5")
        else:
            state = "Вечерняя сводка ещё не подана"
        row = tk.Frame(card, bg=C.SURFACE)
        row.pack(fill="x")
        ui_link(row, app, "изменить" if rec.get("done") else "заполнить", lambda: app.checkin(today)).pack(
            side="right", anchor="n")
        ui_text(row, app, f"{text}. {state}.").pack(side="left", fill="x", expand=True)
        behind = sysm.behind(today)
        nxt = tk.Frame(card, bg=C.SURFACE)
        nxt.pack(fill="x", pady=(px(8), 0))
        if behind:
            tk.Label(nxt, text="Недобор за неделю, клик — в штурм:", font=F["small"], bg=C.SURFACE,
                     fg=C.MUTED).pack(side="left")
            for gap, proj, _b, _f in behind[:3]:
                ui_link(nxt, app, f"{proj} −{fmt_h(gap)} ч", lambda pr=proj: app.work_on(pr)).pack(
                    side="left", padx=(px(10), 0))
        else:
            tk.Label(nxt, text="Бюджет недели на сегодня закрыт по всем направлениям.", font=F["small"],
                     bg=C.SURFACE, fg=C.BREAK).pack(side="left")

    def _kpi(self, grid, col, title, big, lines, frac=None, mark=None, color=None, big_font="stat"):
        app = self.app
        F, px = app.fonts, app.px
        outer, card = ui_card(grid, app, padx=12, pady=10)
        outer.grid(row=0, column=col, sticky="nsew", padx=(0 if col == 0 else px(8), 0))
        tk.Label(card, text=title.upper(), font=F["tiny"], bg=C.SURFACE, fg=C.MUTED, anchor="w").pack(fill="x")
        tk.Label(card, text=big, font=F[big_font], bg=C.SURFACE, fg=C.INK, anchor="w", justify="left",
                 wraplength=px(220)).pack(fill="x")
        if frac is not None:
            Bar(card, app, frac, color or C.FOCUS, mark).pack(fill="x", pady=(px(4), px(6)))
        for text, fg in lines:
            ui_text(card, app, text, fg=fg or C.MUTED).pack(fill="x")

    def _kpis(self, today):
        app, sysm = self.app, self.app.system
        px = app.px
        grid = tk.Frame(self.body, bg=C.BG)
        grid.pack(fill="x", pady=(0, px(10)))
        for i in range(4):
            grid.columnconfigure(i, weight=1, uniform="kpi")
        start, end = sysm.start(), sysm.end()
        total = sysm.total_days()
        upto = min(today, end)

        # часы
        fact, goal = sysm.hours_total(), sysm.goal("hours", 1000)
        plan_td = sysm.plan_between(start, upto)
        elapsed = sysm.day_no(today)
        pace = goal * elapsed / total if total else 0.0
        left = sysm.days_to_finish(today)
        need = max(0.0, goal - fact) / left if left else 0.0
        rest = sysm.plan_between(today + timedelta(days=1), end)
        if sysm.active(today):
            rest += max(0.0, sysm.day_plan(today) - sysm.hours_on(today))
        fc = sysm.forecast(today)
        p_goal = int(round(fc.get("p", 0) * 100))
        lines = [(f"норма к концу дня {fmt_h(plan_td)}, темп {int(goal)}: {fmt_h(pace)}", None),
                 (f"нужно в день до {int(goal)}: {fmt_h(need)} ч", C.DANGER if need > 10.5 else None),
                 (f"если дальше по норме: {fmt_h(fact + rest)}", None),
                 ("разведка: прогноз появится после 3 дней с данными", None) if fc.get("prior") else
                 (f"разведка: цель возьмём с вероятностью {p_goal}%", C.BREAK if p_goal >= 70 else
                  (C.LONG if p_goal >= 40 else C.DANGER))]
        pre = sysm.pre_campaign_hours()
        if pre and pre[2] > 0:
            lines.append((f"до кампании ({pre[0]:%d.%m}–{pre[1]:%d.%m}): {fmt_h(pre[2])} ч", None))
        self._kpi(grid, 0, "Часы", f"{fmt_h(fact)} из {int(goal)}", lines,
                  frac=fact / goal if goal else 0, mark=pace / goal if goal else None)

        # оценки
        grades, lines = [], []
        for c in sysm.s["courses"]:
            calc = course_calc(c)
            name = course_short(c["name"])
            if calc["total_w"] <= 0:
                lines.append((f"{name}: нет формулы", C.LONG))
                continue
            g = calc["current_grade"]
            if g is not None:
                grades.append(g)
            need_txt = ""
            if calc["need"] is not None and calc["need"] > 0:
                need_txt = f", нужно {fmt_score(c, calc['need'])}"
            elif calc["need"] is not None:
                need_txt = ", цель обеспечена"
            bad = (g is not None and g < sysm.goal("grade_min", 8)) or (
                calc["need"] is not None and calc["need"] > calc["top"] * 0.95)
            lines.append((f"{name}: {g if g is not None else '—'}{need_txt}", C.DANGER if bad else None))
        waiting = sum(1 for r in sysm.s["retakes"] if r.get("status") == "Ожидает")
        failed = sum(1 for r in sysm.s["retakes"] if r.get("status") == "Не сдано")
        if waiting or failed:
            lines.append((f"пересдачи: ждут {waiting}" + (f", не сдано {failed}" if failed else ""),
                          C.DANGER if failed else C.LONG))
        big = fmt_num(sum(grades) / len(grades), 1) if grades else "—"
        self._kpi(grid, 1, "Рубежи (оценки)", big + (" сейчас" if grades else ""), lines)

        # сеть
        touches, tgoal = sysm.touches_total(), sysm.goal("touches", 500)
        monday = week_monday(today)
        wk, wt = sysm.touches_between(monday, today), sysm.touch_target(monday)
        fu = len(sysm.followups(today))
        lines = [(f"эта неделя: {wk} из {wt}", C.DANGER if wt and today.weekday() >= 3 and wk < wt * 0.4 else None),
                 (f"созвонов и встреч: {sysm.touches_total(calls=True)}", None),
                 (f"людей в базе: {len(sysm.s['contacts'])}", None),
                 (f"фоллоу-апов на сегодня: {fu}", C.DANGER if fu else None)]
        until = sysm.touch_target_until(today)
        if sysm.quota():
            self._kpi(grid, 2, "Сеть", f"{touches} из {int(tgoal)}", lines,
                      frac=touches / tgoal if tgoal else 0, mark=until / tgoal if tgoal else None, color=C.FLOW)
        else:
            store = getattr(app, "notes_store", None)
            try:
                s = store.summary() if store is not None else None
            except sqlite3.Error:
                s = None
            net = sysm.s.get("net") or {}
            mine = [m for m in net.get("commitments") or [] if m.get("who") == "me" and not m.get("done")]
            klines = [(f"к повторению: {s['due']}", C.DANGER if s and s["due"] and not s["today"] else None)
                      if s else ("база конспектов недоступна", C.DANGER),
                      (f"серия повторения: {s['streak']} дн." if s else "", None),
                      (f"конспектов {s['notes']}, карточек {s['cards']}" if s else "", None),
                      (f"сеть: написать {fu}, обязательств {len(mine)}", C.DANGER if fu or mine else None)]
            self._kpi(grid, 2, "Знания", f"{s['today'] if s else 0} повторено", [x for x in klines if x[0]],
                      frac=(s["today"] / (s["today"] + s["due"])) if s and (s["today"] + s["due"]) else None,
                      color=C.FLOW)

        # здоровье
        a7 = max(start, today - timedelta(days=6))
        tw = sysm.trainings_between(max(monday, start), today)
        tgw = int(sysm.goal("trainings", 6))
        sleep = sysm.sleep_values(a7, today)
        food = sysm.food_values(a7, today)
        wake = next((sysm.day(d).get("wake") for d in (today - timedelta(days=i) for i in range(7))
                     if sysm.day(d).get("wake")), None)
        checked = sysm.checkins_between(a7, today)
        span = (today - a7).days + 1 if today >= start else 0
        s_avg = sum(sleep) / len(sleep) if sleep else None
        f_avg = sum(food) / len(food) if food else None
        lines = [(f"сон за 7 дней: {fmt_num(s_avg)} ч", C.DANGER if s_avg is not None and s_avg < 7 else None),
                 (f"питание: {fmt_num(f_avg)} из 5", C.LONG if f_avg is not None and f_avg < 4 else None),
                 (f"последний подъём: {wake or '—'}", None),
                 (f"сводок за 7 дней: {checked} из {span}", C.LONG if span and checked < span - 1 else None)]
        self._kpi(grid, 3, "Тыл: тренировки", f"{tw} из {tgw}", lines, frac=tw / tgw if tgw else 0, color=C.BREAK)

    def _directions(self, today):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        outer, card = ui_card(self.body, app)
        outer.pack(fill="x", pady=(0, px(10)))
        self._h2(card, "Распределение огня: часы по направлениям")
        ui_text(card, app, "Полоса — факт к бюджету на сегодня, черта — где надо быть, справа — текущая неделя. "
                           "Клик по строке — штурм на направлении. Бюджет меняется на вкладке «Устав».").pack(fill="x")
        start, end = sysm.start(), sysm.end()
        upto = min(today, end)
        monday = max(week_monday(today), start)
        sunday = week_monday(today) + timedelta(days=6)
        tot, week = sysm.hours_by_project(), sysm.hours_by_project(monday, today)
        rows = []
        for p in sysm.directions():
            rows.append((p, tot.get(p, 0.0), sysm.budget_between(p, start, upto), sysm.budget_between(p, start, end),
                         week.get(p, 0.0), sysm.budget_between(p, monday, sunday)))
        if not rows:
            ui_text(card, app, "Пока ни бюджета, ни часов.").pack(fill="x", pady=(px(6), 0))
            return
        rows.append(("Итого", sum(r[1] for r in rows), sum(r[2] for r in rows), sum(r[3] for r in rows),
                     sum(r[4] for r in rows), sum(r[5] for r in rows)))
        row_h = px(24)
        canvas = tk.Canvas(card, bg=C.SURFACE, highlightthickness=0, height=row_h * len(rows) + px(6),
                           cursor="hand2")
        canvas.pack(fill="x", pady=(px(8), 0))
        canvas.bind("<Configure>", lambda e: self._draw_dirs(canvas, rows, row_h))

        def click(e):
            i = int(e.y // row_h)
            if 0 <= i < len(rows) - 1 and rows[i][0]:
                app.work_on(rows[i][0])
        canvas.bind("<Button-1>", click)

    def _draw_dirs(self, c, rows, row_h):
        app = self.app
        F, px = app.fonts, app.px
        c.delete("all")
        W = c.winfo_width()
        if W < 300:
            return
        font = tkfont.Font(font=F["small"])
        name_w, text_w = px(170), px(300)
        x0, x1 = name_w + px(8), W - text_w - px(8)
        for i, (name, fact, b_td, b_all, wf, wb) in enumerate(rows):
            y = i * row_h + px(3)
            last = i == len(rows) - 1
            fnt = F["small_bold"] if last else F["small"]
            if last:
                c.create_line(0, y - px(2), W, y - px(2), fill=C.LINE)
            c.create_text(0, y + row_h / 2 - px(2), anchor="w", font=fnt, fill=C.INK,
                          text=fit_text(font, name or "Без направления", name_w))
            scale = max(b_td, fact, 0.01)
            bw = x1 - x0
            top, bot = y + px(5), y + row_h - px(9)
            c.create_rectangle(x0, top, x1, bot, fill=C.TRACK, outline="")
            if b_td <= 0:
                color = C.MUTED
            elif fact >= b_td * 0.95:
                color = C.BREAK
            elif fact >= b_td * 0.7:
                color = C.LONG
            else:
                color = C.DANGER
            if fact > 0:
                c.create_rectangle(x0, top, x0 + max(2, bw * fact / scale), bot, fill=color, outline="")
            if b_td > 0:
                bx = x0 + bw * b_td / scale
                c.create_line(bx, top - px(2), bx, bot + px(2), fill=C.INK, width=2)
            c.create_text(W, y + row_h / 2 - px(2), anchor="e", font=fnt, fill=C.MUTED if not last else C.INK,
                          text=f"{fmt_h(fact)} из {fmt_h(b_td)} ч · неделя {fmt_h(wf)} из {fmt_h(wb)}")

    def _weeks_chart(self, today):
        app, sysm = self.app, self.app.system
        px = app.px
        outer, card = ui_card(self.body, app)
        outer.pack(fill="x", pady=(0, px(10)))
        self._h2(card, "Часы по неделям")
        ui_text(card, app, "Светлое — план по типам дней, яркое — факт. Зелёное — неделя выполнена. "
                           "Цифра сверху — касания за неделю.").pack(fill="x")
        canvas = tk.Canvas(card, bg=C.SURFACE, highlightthickness=0, height=px(150))
        canvas.pack(fill="x", pady=(px(8), 0))
        canvas.bind("<Configure>", lambda e: self._draw_weeks(canvas, today))

    def _draw_weeks(self, c, today):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        c.delete("all")
        W, H = c.winfo_width(), c.winfo_height()
        if W < 200:
            return
        start, end = sysm.start(), sysm.end()
        weeks = []
        m = week_monday(start)
        while m <= end:
            a, b = max(m, start), min(m + timedelta(days=6), end)
            upto = min(b, today)
            weeks.append((m, sysm.plan_between(a, b), sysm.hours_between(a, b),
                          sysm.touches_between(a, upto) if upto >= a else 0, a <= today))
            m += timedelta(days=7)
        top = max([w[1] for w in weeks] + [w[2] for w in weeks] + [1]) * 1.1
        base = H - px(18)
        step = W / max(1, len(weeks))
        bw = min(step * 0.34, px(18))
        cur = week_monday(today)
        for i, (m, plan, fact, touches, started) in enumerate(weeks):
            cx = step * i + step / 2
            hp = (base - px(24)) * plan / top
            hf = (base - px(24)) * fact / top
            c.create_rectangle(cx - bw - 1, base - hp, cx - 1, base, fill=C.TRACK, outline="")
            if fact > 0:
                color = C.BREAK if plan and fact >= plan * 0.97 else C.FOCUS
                c.create_rectangle(cx + 1, base - hf, cx + bw + 1, base, fill=color, outline="")
            if m == cur:
                c.create_rectangle(cx - bw - px(4), px(20), cx + bw + px(4), base + px(2), outline=C.INK, dash=(2, 3))
            if started and touches:
                c.create_text(cx, px(4), anchor="n", text=str(touches), font=F["tiny"], fill=C.FLOW)
            c.create_text(cx, base + px(4), anchor="n", text=f"{m:%d.%m}", font=F["tiny"],
                          fill=C.INK if m == cur else C.MUTED)
        c.create_line(0, base, W, base, fill=C.LINE)

    def _upcoming(self, parent, today):
        app, sysm = self.app, self.app.system
        px = app.px
        outer, card = ui_card(parent, app)
        self._h2(card, "Ближайшие 14 дней", "весь календарь", lambda: self.set_tab("calendar"), bg=C.SURFACE)
        rows = sysm.calendar()
        overdue = sorted((r for r in rows if r["date"] and r["date"] < today and not r["done"]
                          and r["status"] != "Перенесено"), key=lambda r: r["date"])
        soon = sorted((r for r in rows if r["date"] and today <= r["date"] <= today + timedelta(days=14)
                       and not r["done"]), key=lambda r: r["date"])
        if not overdue and not soon:
            ui_text(card, app, "С датой ничего. Впиши даты контрольных в «Рубежах» — они появятся здесь.").pack(
                fill="x", pady=(px(6), 0))
        for r in overdue[:4]:
            ui_text(card, app, f"просрочено {r['date']:%d.%m} · {r['title']}", fg=C.DANGER).pack(fill="x", pady=px(1))
        for r in soon[:10]:
            when = fmt_due(r["date"].isoformat(), today)
            ui_text(card, app, f"{when} · {r['title']}",
                    fg=C.INK if (r["date"] - today).days <= 3 else C.MUTED).pack(fill="x", pady=px(1))
        return outer

    def _skills_mini(self, parent):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        outer, card = ui_card(parent, app)
        self._h2(card, "Навыки", "подробно", lambda: self.set_tab("skills"), bg=C.SURFACE)
        hours = sysm.hours_by_project()
        for s in sysm.s["skills"]:
            proj = s.get("project") or ""
            h, b = hours.get(proj, 0.0), sysm.budget_between(proj, sysm.start(), sysm.end())
            cps = sorted((cp for cp in s.get("checkpoints") or [] if not cp.get("done")),
                         key=lambda cp: cp.get("date") or "9999")
            row = tk.Frame(card, bg=C.SURFACE)
            row.pack(fill="x", pady=(px(4), 0))
            tk.Label(row, text=s.get("name", ""), font=F["small_bold"], bg=C.SURFACE, fg=C.INK).pack(side="left")
            st = s.get("status", "")
            tk.Label(row, text=st, font=F["small"], bg=C.SURFACE,
                     fg=C.BREAK if st == "Готово" else (C.FOCUS if st == "В работе" else C.MUTED)).pack(side="right")
            text = f"{fmt_h(h)} из {fmt_h(b)} ч"
            if cps:
                d = sys_date(cps[0].get("date"))
                text += f" · дальше: {cps[0].get('text', '')}" + (f" к {d:%d.%m}" if d else "")
            ui_text(card, app, text).pack(fill="x")
        return outer

    # ───────── Генштаб: приказ, фронты, разведка, наряды ─────────
    def _order_card(self, today):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
        if not sysm.active(today):
            return
        rec = sysm.day(today)
        outer, card = ui_card(self.body, app)
        outer.pack(fill="x", pady=(0, px(10)))
        head = self._h2(card, "Приказ на сегодня", bg=C.SURFACE)
        if sysm.is_reserve(today):
            tk.Label(head, text="резерв Ставки", font=F["small_bold"], bg=C.SURFACE, fg=C.BREAK).pack(side="right")
        elif rec.get("morning"):
            tk.Label(head, text="построение проведено", font=F["small"], bg=C.SURFACE, fg=C.BREAK).pack(side="right")
        else:
            ui_link(head, app, "провести построение", lambda: app.coach.open_morning(), fg=C.DANGER).pack(side="right")
        for title, text in sysm.order_items(today):
            row = tk.Frame(card, bg=C.SURFACE)
            row.pack(fill="x", pady=px(1))
            tk.Label(row, text=title, font=F["small_bold"], bg=C.SURFACE, fg=C.INK, width=18, anchor="nw").pack(
                side="left", anchor="n")
            ui_text(row, app, text, fg=C.INK).pack(side="left", fill="x", expand=True)
        if rec.get("mit_text"):
            row = tk.Frame(card, bg=C.SURFACE)
            row.pack(fill="x", pady=px(1))
            tk.Label(row, text="Главный удар", font=F["small_bold"], bg=C.SURFACE, fg=C.FOCUS, width=18,
                     anchor="nw").pack(side="left", anchor="n")
            mit = app.task_by_id(rec.get("mit_id"))
            done = mit is not None and mit.get("status") == "done"
            ui_text(row, app, rec["mit_text"] + (" — доведён" if done else ""), fg=C.BREAK if done else C.INK).pack(
                side="left", fill="x", expand=True)
        btns = tk.Frame(card, bg=C.SURFACE)
        btns.pack(fill="x", pady=(px(8), 0))
        ok, _why = sysm.reserve_check(today)
        if ok:
            ttk.Button(btns, text=f"Резерв ({sysm.reserve_left(today)})", command=lambda: app.ask_reserve(today)).pack(
                side="left", padx=(0, px(6)))
        if sysm.day_type(today) != DEFENSE_TYPE and not sysm.is_reserve(today) \
                and sysm.type_change_check(today, DEFENSE_TYPE)[0]:
            ttk.Button(btns, text="Оборона", command=lambda: app.set_day_type(today, DEFENSE_TYPE)).pack(
                side="left", padx=(0, px(6)))
        hours, _why = sysm.carry_info(today)
        if hours <= 0:
            hours, _why = sysm.carry_info(today - timedelta(days=1))
        if hours > 0:
            ttk.Button(btns, text=f"Перенос до {fmt_h(hours)} ч", command=app.ask_carry).pack(side="left",
                                                                                             padx=(0, px(6)))
        n = len(sysm.duties_open())
        ttk.Button(btns, text=f"Наряды: {n}" if n else "Нарядов нет", command=lambda: self.set_tab("duty")).pack(
            side="right")

    def _tab_fronts(self):
        app, sysm = self.app, self.app.system
        F, px = app.fonts, app.px
