    def export_ics(self):
        text, count = ics_text(self.store.tasks)
        if not count:
            self.toast("Сроков пока нет: экспортировать нечего")
            return
        path = filedialog.asksaveasfilename(parent=self, defaultextension=".ics",
                                            initialfile=f"genshtab-{date.today():%Y%m%d}.ics",
                                            filetypes=[("Календарь", "*.ics")])
        if not path:
            return
        try:
            Path(path).write_text(text, encoding="utf-8")
        except OSError as exc:
            messagebox.showerror(APP_NAME, f"Не получилось сохранить: {exc}", parent=self)
            return
        messagebox.showinfo(APP_NAME,
                            f"Сроков выгружено: {count}.\n{path}\n\n"
                            "Файл можно импортировать в Google Календарь (Настройки → Импорт и экспорт) "
                            "или открыть в календаре на телефоне. Повторяющиеся задачи выгружаются "
                            "как повторяющиеся события.", parent=self)

    def clear_old_done(self, days=60):
        limit = (self.today() - timedelta(days=days)).isoformat()
        old = [t for t in self.store.tasks
               if t["status"] == "done" and t.get("completed_day") and t["completed_day"] < limit]
        if not old:
            self.toast(f"Выполненных задач старше {days} дней нет")
            return
        if not messagebox.askyesno(APP_NAME, f"Удалить {len(old)} {plural(len(old), TASK_FORMS)}, "
                                             f"выполненных больше {days} дней назад? "
                                             "Статистика по времени останется.", parent=self):
            return
        self.checkpoint()
        drop = {t["id"] for t in old}
        self.store.data["tasks"] = [t for t in self.store.tasks if t["id"] not in drop]
        self._commit(f"Удалено {len(old)} старых {plural(len(old), TASK_FORMS)}")

    def _day_prompt(self):
        s = self.store.settings
        today = self.today()
        ti = today.isoformat()
        if s.get("last_plan_prompt") == ti or not self._views_ready:
            return
        todo = [t for t in self.store.tasks if t["status"] == "todo"]
        if not todo:
            return
        s["last_plan_prompt"] = ti
        moved = [t for t in todo if t.get("planned_for") and t["planned_for"] < ti]
        planned = [t for t in todo if self.in_plan(t)]
        if moved:
            text = f"Со вчера перенеслось {len(moved)} {plural(len(moved), TASK_FORMS)}"
        elif planned:
            rem = self.remaining_pomos(planned)
            text = f"План на сегодня: {rem} {plural(rem, POMO_FORMS)}"
        else:
            text = "План на сегодня пуст"
        self.toast(text, self.plan_day, "Спланировать день", ms=10000)

    def _pause_check(self):
        p = self.pomo
        minutes = int(self.store.settings.get("pause_remind_min") or 0)
        if not minutes or p.running or p.mode not in FOCUS_MODES or not p.is_active():
            self._paused_since = None
            self._pause_warned = False
            return
        if self._paused_since is None:
            self._paused_since = time.time()
            return
        if not self._pause_warned and time.time() - self._paused_since >= minutes * 60:
            self._pause_warned = True
            self.notify("Таймер на паузе", f"Уже {fmt_minutes(minutes)}. Продолжить или закончить сессию?")

