    def _merge_legacy(self):
        """Первый запуск 8.0: база netapp — в «Сеть», без людей в базе квота касаний не мучает.
        Конспектор переносится сам, когда создаётся база конспектов. Возвращает, что перенесено."""
        s = self.store.settings
        if s.get("merged_80"):
            return None
        out = {}
        sysm = self.system
        src = netcrm_source()
        if src is not None:
            try:
                out["net"] = import_netcrm(sysm, src)
            except Exception:
                # старая или битая база netapp не должна мешать запуску; перенести можно вручную: Сеть → Данные
                traceback.print_exc()
        if self.notes_store.imported:
            out["notes"] = self.notes_store.imported[1]
        if not sysm.s["contacts"] and sysm.quota():
            # людей в базе нет — ежедневное «касания 0 из 5» только засоряет журнал; включается в Сеть → Данные
            sysm.s["net"]["quota"] = False
            out["quota_off"] = True
        s["merged_80"] = True
        self.store.save()
        return out

    def set_day_type(self, day, name, confirm=True):
        """Режим дня. Увольнение — только за резерв Ставки; третья оборона за 7 дней — со штрафом.
        True — режим поставлен, False — нет."""
        sysm = self.system
        if name == LEAVE_TYPE and not sysm.is_reserve(day):
            if confirm:
                self.ask_reserve(day)
            return False
        ok, why = sysm.type_change_check(day, name)
        if not ok:
            if confirm:
                messagebox.showwarning(APP_NAME, f"Режим на {day:%d.%m} не сменить: {why}.", parent=self)
            return False
        if name == DEFENSE_TYPE and sysm.day_type(day) != DEFENSE_TYPE:
            n = sysm.defense_count(day) + 1
            if confirm and n > sysm.rule("defense_free") and not messagebox.askyesno(
                    APP_NAME, f"Это {n}-я оборона за 7 дней. Бесплатно — {sysm.rule('defense_free')}, дальше — штраф "
                              f"{sysm.penalty_cfg()['defense']} очков опыта. Объявить оборону?", parent=self):
                return False
            sysm.journal_add("defense", f"{day:%d.%m}: норма {fmt_h(sysm.type_hours(DEFENSE_TYPE))} ч")
        sysm.day_update(day, type=name)
        sysm.invalidate()
        sysm.sync_habits(day)
        self.store.save()
        self.refresh_all()
        if name:
            self.toast(f"{day:%d.%m}: режим «{name}», норма {fmt_h(sysm.day_plan(day))} ч")
        return True

