    def edit_skill(self, skill):
        sysm = self.system
        s = skill or {}
        lines = []
        for cp in sorted(s.get("checkpoints") or [], key=lambda x: x.get("date") or "9999"):
            d = sys_date(cp.get("date"))
            lines.append(f"{d:%d.%m.%Y} {cp.get('text', '')}" if d else f"— {cp.get('text', '')}")

        def save(v):
            old = {cp.get("text"): cp for cp in s.get("checkpoints") or []}
            cps = []
            for line in v["cps"].splitlines():
                line = line.strip()
                if not line:
                    continue
                first, _sp, rest = line.partition(" ")
                d = None
                if first in ("—", "-"):
                    text = rest.strip()
                else:
                    try:
                        d = parse_date(first, self.today())
                    except ValueError:
                        d = None
                    text = rest.strip() if d else line
                prev = old.get(text)
                cps.append({"id": prev["id"] if prev else _sid(), "date": d.isoformat() if d else None,
                            "text": text, "done": bool(prev and prev.get("done"))})
            fields = {"name": v["name"], "project": v["project"], "result": v["result"], "status": v["status"],
                      "note": v["note"], "checkpoints": cps}
            if skill:
                skill.update(fields)
            else:
                fields["id"] = _sid()
                sysm.s["skills"].append(fields)
            self._sys_changed()

        def delete():
            if not messagebox.askyesno(APP_NAME, f"Удалить навык «{skill.get('name')}»?", parent=self):
                return False
            sysm.s["skills"].remove(skill)
            self._sys_changed()
        FormDialog(self, "Навык", [
            {"key": "name", "label": "Навык", "value": s.get("name", ""), "required": True},
            {"key": "project", "label": "Направление для часов", "kind": "combo",
             "options": [""] + list(self.store.projects), "value": s.get("project", "")},
            {"key": "result", "label": "Конечный результат", "kind": "text", "value": s.get("result", ""), "height": 3},
            {"key": "status", "label": "Статус", "kind": "combo", "options": list(SYS_SKILL_STATUS),
             "value": s.get("status", "Не начат")},
            {"key": "cps", "label": "Контрольные точки", "kind": "text", "value": "\n".join(lines), "height": 5,
             "hint": "строка — дата и что сделано: «25.10 оконные функции». «—» вместо даты — без даты"},
            {"key": "note", "label": "Заметка", "value": s.get("note", "")},
        ], save, on_delete=delete if skill else None)

