    def edit_contact(self, contact):
        sysm = self.system
        today = self.today()
        c = normalize_contact(dict(contact)) if contact else normalize_contact({"status": "Найден", "tier": 2})
        names = {x["id"]: x.get("name", "") for x in sysm.s["contacts"] if x is not contact}
        rev = {v: k for k, v in names.items()}
        fields = [
            {"key": "name", "label": "Имя", "value": c.get("name", ""), "required": True},
            {"key": "company", "label": "Компания", "value": c.get("company", "")},
            {"key": "role", "label": "Роль", "value": c.get("role", "")},
            {"key": "location", "label": "Город", "value": c.get("location", "")},
            {"key": "tier", "label": "Приоритет", "kind": "combo", "options": ["T1", "T2", "T3"],
             "value": f"T{c.get('tier', 2)}",
             "hint": "как часто напоминать: T1 — раз в " + str(net_cadence(sysm, 1)) + " дн., T2 — "
                     + str(net_cadence(sysm, 2)) + ", T3 — " + str(net_cadence(sysm, 3))},
            {"key": "status", "label": "Стадия", "kind": "combo", "options": list(SYS_STATUSES),
             "value": c.get("status", "Найден")},
            {"key": "segment", "label": "Сегмент", "kind": "combo", "options": sysm.segments(), "free": True,
             "value": c.get("segment", "")},
            {"key": "channel", "label": "Канал", "kind": "combo", "options": list(SYS_CHANNELS),
             "value": c.get("channel") or "LinkedIn"},
            {"key": "linkedin", "label": "LinkedIn", "value": c.get("linkedin", "")},
            {"key": "telegram", "label": "Telegram", "value": c.get("telegram", "")},
            {"key": "email", "label": "Email", "value": c.get("email", "")},
            {"key": "source", "label": "Откуда знаю", "value": c.get("source", "")},
            {"key": "intro", "label": "Кто познакомил", "kind": "combo", "options": [""] + sorted(names.values()),
             "value": names.get(c.get("introduced_by"), "")},
            {"key": "tags", "label": "Теги", "value": c.get("tags", "")},
        ]
        if contact is None:
            fields += [{"key": "first", "label": "Первое касание сегодня", "kind": "check", "value": True},
                       {"key": "kind", "label": "Какое", "kind": "combo", "options": list(SYS_TOUCH_KINDS),
                        "value": "Сообщение"}]
        fields += [
            {"key": "next_step", "label": "Следующий шаг", "value": c.get("next_step", "")},
            {"key": "next_date", "label": "Когда", "kind": "date", "value": c.get("next_date"), "optional": True,
             "hint": "пусто — посчитается по приоритету"},
            {"key": "insight", "label": "Главный вывод", "kind": "text", "value": c.get("insight", ""), "height": 2},
            {"key": "notes", "label": "Заметки о человеке", "kind": "text", "value": c.get("notes", ""), "height": 3},
        ]

        def save(v):
            data = {k: v[k] for k in ("name", "company", "role", "location", "segment", "channel", "status",
                                      "linkedin", "telegram", "email", "source", "tags", "next_step", "next_date",
                                      "insight", "notes")}
            data["name"] = data["name"].strip()
            data["linkedin"] = (data["linkedin"] or "").strip()
            data["tier"] = int(str(v["tier"] or "T2").lstrip("T") or 2)
            data["introduced_by"] = rev.get(v["intro"])
            if data["linkedin"] and any(x.get("linkedin") == data["linkedin"] and x is not contact
                                        for x in sysm.s["contacts"]):
                messagebox.showwarning(APP_NAME, "Этот LinkedIn уже привязан к другому человеку.", parent=self)
                return False
            if contact is None:
                new = net_new_contact(sysm, data.pop("name"), **data)
                if v.get("first"):
                    net_touch(sysm, new, today, v.get("kind") or "Сообщение", "out",
                              next_date=data.get("next_date") or None, next_step=data.get("next_step") or None)
                elif not new.get("next_date"):
                    net_recompute(sysm, new, today)
                v_sel = new["id"]
            else:
                tier_changed = data["tier"] != contact.get("tier") or data["status"] != contact.get("status")
                contact.update(data)
                if not data.get("next_date") or (tier_changed and data.get("next_date") == c.get("next_date")):
                    net_recompute(sysm, contact, today)
                v_sel = contact["id"]
            nv = self.views.get("network") if self._views_ready else None
            if nv is not None:
                nv.sel = v_sel
            self._sys_changed()
            if contact is None and v.get("first"):
                self.check_milestones()

        def delete():
            if not messagebox.askyesno(APP_NAME, f"Удалить «{contact.get('name')}» вместе с касаниями и обязательствами? "
                                                 "Инсайты останутся без автора.", parent=self):
                return False
            net = net_cfg(sysm)
            for x in sysm.s["contacts"]:
                if x.get("introduced_by") == contact["id"]:
                    x["introduced_by"] = None
            for i in net["insights"]:
                if i.get("contact") == contact["id"]:
                    i["contact"] = None
            net["commitments"] = [m for m in net["commitments"] if m.get("contact") != contact["id"]]
            sysm.s["contacts"].remove(contact)
            self._sys_changed()
        FormDialog(self, "Человек" if contact else "Новый человек", fields, save,
                   on_delete=delete if contact else None, width=48)

    def add_touch(self, contact):
        sysm = self.system
        today = self.today()
        normalize_contact(contact)
        status = contact.get("status") or "Найден"
        kind = "Созвон" if status == "Созвон назначен" else ("Фоллоу-ап" if contact.get("touches") else "Сообщение")

        def save(v):
            d = sys_date(v["date"]) or today
            direction = "in" if v["dir"] == NET_DIRS["in"] else "out"
            st = v["status"] if v["status"] != "посчитать само" else None
            net_touch(sysm, contact, d, v["kind"], direction, v["channel"], v["note"], v["notes"],
                      next_date=v["next_date"] or None, status=st, next_step=v["next_step"] or None)
            if v.get("insight"):
                net_add_insights(sysm, contact["id"], contact["touches"][-1]["id"], v["insight"], "Другое", d)
            self._sys_changed(f"Касание записано: {contact.get('name')}"
                              + (f". Всего {sysm.touches_total()} из {int(sysm.goal('touches', 500))}"
                                 if sysm.quota() else ""))
            self.check_milestones()
        FormDialog(self, f"Касание: {contact.get('name', '')}", [
            {"key": "date", "label": "Дата", "kind": "date", "value": today.isoformat(), "required": True},
            {"key": "kind", "label": "Что было", "kind": "combo", "options": list(SYS_TOUCH_KINDS), "value": kind},
            {"key": "dir", "label": "Кто", "kind": "combo", "options": list(NET_DIRS.values()), "value": NET_DIRS["out"]},
            {"key": "channel", "label": "Канал", "kind": "combo", "options": list(SYS_CHANNELS),
             "value": contact.get("channel") or "LinkedIn"},
            {"key": "note", "label": "Коротко", "value": "", "hint": "о чём"},
            {"key": "notes", "label": "Заметки", "kind": "text", "height": 3, "value": ""},
            {"key": "insight", "label": "Что узнал", "kind": "text", "height": 2, "value": "",
             "hint": "по строке, можно «найм: …» — попадёт в «Что узнал»"},
            {"key": "status", "label": "Стадия теперь", "kind": "combo",
             "options": ["посчитать само"] + list(SYS_STATUSES), "value": "посчитать само"},
            {"key": "next_step", "label": "Следующий шаг", "value": ""},
            {"key": "next_date", "label": "Следующее касание", "kind": "date", "value": None, "optional": True,
             "hint": "пусто — по приоритету; без ответа — через неделю"},
        ], save, note="Подробный разговор с вопросами и обязательствами — Сеть → «Разговор».", width=46)

    def _checkin_check(self):
        now = time.time()
        if now - self._ci_checked < 60:
            return
        self._ci_checked = now
        sysm, s = self.system, self.store.settings
        today = self.today()
        if not sysm.active(today) or sysm.day(today).get("done"):
            return
        try:
            hour = int(sysm.s.get("checkin_hour") or 21)
        except (TypeError, ValueError):
            hour = 21
        if datetime.now().hour < hour or s.get("last_checkin_prompt") == today.isoformat():
            return
        s["last_checkin_prompt"] = today.isoformat()
        self.store.save()
        if s.get("system_notify"):
            if not self.tray.notify("Вечерняя сводка", "Минута: тип дня, сон, тренировка, питание"):
                system_notification("Вечерняя сводка", "Минута: тип дня, сон, тренировка, питание")
        self.toast("Вечерняя сводка: минута на сон, тренировку и питание", self.checkin, "Заполнить", ms=30000)

